Object.assign(window.verseCommentary, {
  "Matthew 9:18": { title: "A Ruler Appeals to Jesus", text: "While Jesus is speaking, a ruler bows before Him and says his daughter has just died, yet asks Jesus to come and lay His hand on her. The request expresses trust in Jesus’ life-giving authority.", refs: ["Mark 5:22–23","Luke 8:41–42"] },
  "Matthew 9:19": { title: "Jesus Follows the Ruler", text: "Jesus rises and follows the ruler, and His disciples go with Him. He responds personally to the grieving father’s appeal.", refs: ["Mark 5:24","Luke 8:42"] },
  "Matthew 9:20": { title: "A Woman with an Issue of Blood", text: "A woman who has suffered for twelve years approaches from behind and touches the hem of Jesus’ garment. Her condition carried physical and ceremonial burdens, yet she reaches toward Him in faith.", refs: ["Leviticus 15:25–27","Mark 5:25–27"] },
  "Matthew 9:21": { title: "She Trusts Jesus Can Heal", text: "The woman reasons that touching Jesus’ garment will make her whole. Her confidence rests on Jesus’ power, not on the garment as a magical object.", refs: ["Mark 5:28","Luke 8:44"] },
  "Matthew 9:22": { title: "Jesus Turns, Heals, and Comforts Her", text: "Jesus turns and sees the woman, calls her “daughter,” and tells her to be of good comfort. He affirms her faith, and she is made whole that hour; He does not leave her an anonymous recipient in the crowd.", refs: ["Mark 5:30–34","Luke 8:48"] },
  "Matthew 9:23": { title: "Jesus Comes to the Ruler’s House", text: "Jesus arrives at the ruler’s house and sees the minstrels and noisy crowd. The narrative returns to the girl whose death prompted the ruler’s request.", refs: ["Mark 5:38","Luke 8:51"] },
  "Matthew 9:24": { title: "The Maid Is Asleep", text: "Jesus says the maid is not dead but sleeps, anticipating her restoration. The mourners’ laughter shows they do not understand what He is about to do.", refs: ["Mark 5:39–40","John 11:11–14"] },
  "Matthew 9:25": { title: "The Girl Is Raised", text: "After the crowd is put outside, Jesus takes the girl by the hand and she arises. The miracle displays His authority over death and brings comfort to her family.", refs: ["Mark 5:41–42","Luke 8:54–55"] },
  "Matthew 9:26": { title: "The Report Spreads", text: "The fame of this event spreads throughout the land. Matthew records the public impact of Jesus’ work without suggesting that every hearer responded with faith.", refs: ["Mark 5:42–43"] },
  "Matthew 9:27": { title: "Two Blind Men Call for Mercy", text: "Two blind men follow Jesus and call Him the Son of David, recognizing His messianic identity and asking for mercy.", refs: ["Isaiah 35:5–6","Matthew 12:22–23"] },
  "Matthew 9:28": { title: "Jesus Asks About Their Faith", text: "When the blind men come to Him, Jesus asks whether they believe He is able to do this. Their answer brings their trust into the open; faith is confidence in Him, not a method of controlling God.", refs: ["Mark 9:23–24","Hebrews 11:6"] },
  "Matthew 9:29": { title: "According to Your Faith", text: "Jesus touches their eyes and says it will be according to their faith. Faith receives from Jesus, while healing remains under God’s authority and wisdom.", refs: ["Matthew 8:13","James 5:15"] },
  "Matthew 9:30": { title: "Their Eyes Are Opened", text: "The men receive sight, a sign of the Messiah’s restoring work. Jesus strictly charges them not to publicize the miracle, but they spread His fame throughout the region.", refs: ["Isaiah 29:18","Isaiah 35:5–6","Mark 1:43–45"] },
  "Matthew 9:31": { title: "A Man Unable to Speak Is Brought", text: "As the two men leave, a demon-possessed man who cannot speak is brought to Jesus. The scene introduces another demonstration of His authority over demonic oppression.", refs: ["Matthew 12:22","Luke 11:14"] },
  "Matthew 9:32": { title: "The Man Speaks and the Crowds Marvel", text: "When the demon is cast out, the man speaks and the crowds marvel that such a thing has not been seen in Israel. Their amazement is followed by a hostile interpretation from the Pharisees.", refs: ["Matthew 12:22–23","Luke 11:14"] },
  "Matthew 9:33": { title: "The Pharisees Make an Accusation", text: "The Pharisees claim Jesus casts out devils by the prince of devils. Jesus later answers this accusation directly, exposing the inconsistency of attributing God’s liberating work to Satan.", refs: ["Matthew 12:24–28","Mark 3:22"] },
  "Matthew 9:34": { title: "Jesus Teaches and Heals Throughout the Region", text: "Jesus travels through cities and villages, teaching in synagogues, preaching the gospel of the kingdom, and healing sickness and disease. His ministry joins proclamation with compassionate action.", refs: ["Matthew 4:23","Acts 10:38"] },
  "Matthew 9:35": { title: "Jesus Has Compassion on the Multitudes", text: "Jesus sees the crowds as faint and scattered, like sheep without a shepherd. His response is compassion, not contempt for their confusion or need.", refs: ["Numbers 27:17","Ezekiel 34:5–6","Mark 6:34"] },
  "Matthew 9:36": { title: "The Harvest Is Plentiful", text: "Jesus says the harvest is plentiful but the labourers are few. Many people are ready to hear, yet there are too few workers to serve them.", refs: ["Luke 10:2","John 4:35"] },
  "Matthew 9:37": { title: "Pray for Labourers", text: "Jesus commands His disciples to pray to the Lord of the harvest to send workers into His harvest. Mission begins with dependence on God and a willingness to serve where He sends.", refs: ["Luke 10:2","Isaiah 6:8"] }
});
delete window.verseCommentary["Matthew 9:39"];
delete window.verseCommentary["Matthew 9:40"];

