Object.assign(window.verseCommentary, {
  "Matthew 6:3": { title: "Give Without Seeking Praise", text: "Jesus says generosity should be so sincere that the giver does not perform it for recognition. The image of the left hand not knowing what the right hand does emphasizes unshowy giving.", refs: ["Matthew 6:1–2","2 Corinthians 9:7"] },
  "Matthew 6:4": { title: "The Father Sees Secret Giving", text: "Giving done privately is seen by the Father. Jesus redirects the giver from human applause to sincere devotion before God.", refs: ["Matthew 6:1–4","Hebrews 4:13"] },
  "Matthew 6:5": { title: "Do Not Pray to Be Seen", text: "Jesus warns against praying for public admiration. Prayer is not wrong when others hear it; the condemned motive is performing devotion to gain status.", refs: ["Luke 18:10–14","Matthew 23:5"] },
  "Matthew 6:6": { title: "Pray to the Father in Secret", text: "Jesus teaches His disciples to seek God in private, away from an audience. The Father sees what is hidden, so prayer can be sincere rather than theatrical.", refs: ["Psalm 91:1","Matthew 6:6"] },
  "Matthew 6:7": { title: "Avoid Empty Repetition", text: "Jesus condemns empty, mechanical repetition as if many words could force God to answer. This does not forbid persistent prayer, which Scripture also commends.", refs: ["1 Kings 18:26–29","Luke 18:1–8"] },
  "Matthew 6:8": { title: "The Father Knows Your Needs", text: "God knows what His children need before they ask. Prayer is not informing an unaware God but expressing dependence, trust, and relationship.", refs: ["Psalm 139:1–4","Romans 8:26–27"] },
  "Matthew 6:9": { title: "Our Father in Heaven", text: "Jesus begins the model prayer by addressing God as Father. The Bible’s confession remains that God is one; Jesus teaches His disciples to approach the one God with reverence and trust.", refs: ["Deuteronomy 6:4","Isaiah 64:8"] },
  "Matthew 6:10": { title: "Hallowed Be Thy Name", text: "God’s name is holy and must be treated with reverence. Prayer begins by honoring God, not merely listing personal requests.", refs: ["Leviticus 22:32","Ezekiel 36:23"] },
  "Matthew 6:11": { title: "Thy Kingdom Come", text: "The disciple asks for God’s reign and purposes to be manifested. Prayer looks beyond personal interests toward God’s will on earth.", refs: ["Matthew 4:17","Revelation 11:15"] },
  "Matthew 6:12": { title: "Thy Will Be Done", text: "Jesus teaches surrender to the Father’s will. His own prayer in Gethsemane later demonstrates obedience even in the face of suffering.", refs: ["Matthew 26:39","1 John 5:14"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Jesus Calls the Twelve", text: "Jesus calls His twelve disciples and gives them a distinct assignment. Their number recalls Israel’s twelve tribes and signals a renewed mission to God’s people.", refs: ["Mark 3:13–19","Luke 6:12–16"] },
  "Matthew 10:2": { title: "The Names of the Twelve", text: "Matthew records the names of the apostles, including Peter, Andrew, James, John, and Judas Iscariot. They are real, diverse people entrusted with a mission, not a collection of flawless heroes.", refs: ["Luke 6:14–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Jesus Sends Them to Israel", text: "Jesus sends the twelve first to the lost sheep of Israel. This is a specific stage in the mission; after His resurrection the commission extends to all nations.", refs: ["Matthew 15:24","Matthew 28:19"] },
  "Matthew 10:4": { title: "Preach That the Kingdom Is Near", text: "The disciples are to announce that the kingdom of heaven is at hand. Their message continues Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:5": { title: "Heal and Deliver Freely", text: "Jesus gives the disciples authority for healing and deliverance and commands them to give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:6": { title: "Travel Without Stockpiling", text: "The disciples are instructed not to take extra provisions for this mission, depending on hospitality as they go. This specific commission should not be turned into a universal ban on prudent preparation.", refs: ["Luke 9:3","Luke 22:35–36"] },
  "Matthew 10:7": { title: "Seek Worthy Hospitality", text: "The disciples should seek a receptive household and remain there rather than use the mission to chase comfort. Their conduct is to be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:8": { title: "Bless the House of Peace", text: "The disciples are to greet the household with peace. Where that peace is received, it rests there; where rejected, the messengers move on without coercion.", refs: ["Luke 10:5–6"] },
  "Matthew 10:9": { title: "Shake Off the Dust", text: "If a town refuses their message, the disciples are to shake off its dust as a testimony. The act signifies accountability and does not authorize revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:10": { title: "Judgment for Rejection", text: "Jesus warns that rejecting the message brings serious accountability, comparing such a town with Sodom and Gomorrah. Greater revelation carries greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:11": { title: "Sheep among Wolves", text: "Jesus sends His disciples into danger and tells them to be wise as serpents and harmless as doves. Courage must be joined with prudence and integrity.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:12": { title: "Beware of Human Opposition", text: "Jesus warns that disciples will face courts and punishment. Their mission does not promise safety from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:13": { title: "The Spirit Helps in Testimony", text: "When brought before authorities, disciples should not be consumed with anxious rehearsal; the Spirit will help them speak. This promise concerns the specific setting of witness under persecution, not a rejection of preparation in every context.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:14": { title: "Families May Be Divided", text: "Jesus warns that loyalty to Him can divide households when some reject the gospel. The passage describes the painful cost of allegiance, not a command to seek family conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:15": { title: "Hated for His Name", text: "Disciples will be hated for Jesus’ name, but those who endure faithfully will be saved. Endurance is steadfast loyalty to God amid opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:16": { title: "Flee Persecution Wisely", text: "When persecuted in one city, the disciples may flee to another. Jesus does not require needless martyrdom; the mission continues through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:17": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:18": { title: "Called Beelzebub", text: "If people insult Jesus as Beelzebub, His household should not expect to escape slander. Disciples must remain faithful rather than be surprised by false accusations.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:19": { title: "Fear God Rather Than People", text: "What is hidden will be revealed, and Jesus tells His followers to fear God above human threats. Human beings can harm the body, but God is the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:20": { title: "Speak the Gospel Openly", text: "What Jesus teaches privately is to be proclaimed openly. The gospel is not meant to remain secret out of fear of opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:21": { title: "God Knows the Sparrows", text: "Not even a sparrow falls without the Father’s knowledge, and the disciples are more valuable than many sparrows. This gives courage without promising that believers will never suffer.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:22": { title: "Confess Jesus Before People", text: "Those who confess Jesus before people are acknowledged by Him before the Father. The call is to public faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:23": { title: "Denying Jesus Has Consequences", text: "Jesus warns that denying Him before people has consequences before the Father. The warning calls for steadfast confession, especially under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:24": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to take up violence; His gospel can expose loyalties and provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:25": { title: "Love Jesus Above All", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel the command to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:26": { title: "Take Up the Cross", text: "Following Jesus may require self-denial, suffering, and willingness to lose worldly security. The cross here is not merely a minor inconvenience but the cost of discipleship.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:27": { title: "Find Life by Losing It", text: "A person who makes self-preservation the highest goal may lose true life, while one who gives their life for Jesus finds it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:28": { title: "The Worth of a Soul", text: "The whole world cannot compensate for the loss of a soul. Jesus urges disciples to value eternal life above wealth and worldly gain.", refs: ["Psalm 49:6–8","Mark 8:36–37"] },
  "Matthew 10:29": { title: "The Son of Man Will Come in Glory", text: "Jesus speaks of the Son of man coming in the glory of His Father with angels to judge and reward. The language echoes Daniel’s vision and points to divine authority exercised through the Messiah.", refs: ["Daniel 7:13–14","Matthew 25:31–32"] },
  "Matthew 10:30": { title: "Some Will See the Kingdom’s Coming", text: "Jesus says some standing there will see the Son of man coming in His kingdom before they die. Interpreters relate this to the transfiguration and/or the kingdom’s powerful advance; the next chapter’s transfiguration provides an immediate narrative connection.", refs: ["Matthew 17:1–9","Mark 9:1"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Jesus Gives Authority to the Twelve", text: "Jesus gives the twelve authority over unclean spirits and to heal disease. Their mission is delegated authority under Jesus, not independent power or a license for personal gain.", refs: ["Mark 3:13–15","Luke 9:1"] },
  "Matthew 10:2": { title: "The Names of the Apostles", text: "Matthew names the twelve apostles, beginning with Simon Peter and Andrew, and James and John. The title apostle means one sent with a commission.", refs: ["Luke 6:13–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Philip, Bartholomew, Thomas, and Matthew", text: "The list continues with Philip, Bartholomew, Thomas, and Matthew the publican. Jesus calls people with different backgrounds into a shared mission.", refs: ["Mark 3:18","Luke 6:15"] },
  "Matthew 10:4": { title: "James, Lebbaeus, Simon, and Judas", text: "Matthew completes the list, including Simon the Canaanite and Judas Iscariot, who betrayed Jesus. The inclusion of Judas shows that outward proximity to Jesus does not guarantee faithful character.", refs: ["Luke 6:15–16","John 6:70–71"] },
  "Matthew 10:5": { title: "Jesus Sends the Twelve", text: "Jesus sends the twelve and gives specific instructions for this stage of their mission. These directions must be read in their immediate context and alongside the later commission to all nations.", refs: ["Matthew 28:19–20","Luke 9:2"] },
  "Matthew 10:6": { title: "Go to Israel’s Lost Sheep", text: "The disciples are first directed to Israel’s lost sheep. This is the initial focus of Jesus’ earthly ministry, not a permanent exclusion of the Gentiles.", refs: ["Matthew 15:24","Romans 1:16"] },
  "Matthew 10:7": { title: "Preach the Kingdom Is Near", text: "The disciples announce that the kingdom of heaven is at hand, continuing Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:8": { title: "Heal and Give Freely", text: "The disciples are commissioned to heal, cleanse, raise the dead, and cast out devils; they must give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:9": { title: "Take No Extra Provision", text: "For this particular mission, the disciples are told not to stockpile travel provisions. They are to depend on God and the hospitality provided; this is not a universal ban on prudent preparation.", refs: ["Luke 9:3","Luke 22:35–36"] },
  "Matthew 10:10": { title: "Seek Worthy Hospitality", text: "The disciples are to seek a worthy household and remain there rather than move from house to house seeking better comfort. Their conduct should be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:11": { title: "Greet the House with Peace", text: "The disciples are to greet the household with peace. If the household receives the greeting, peace rests there; if not, it returns to the messengers.", refs: ["Luke 10:5–6"] },
  "Matthew 10:12": { title: "Shake Off the Dust", text: "If a town refuses to receive them or hear their words, the disciples are to shake off its dust as a testimony. This is a sign of accountability, not permission for revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:13": { title: "Judgment for Rejecting the Message", text: "Jesus says the judgment will be more tolerable for Sodom and Gomorrah than for a town that rejects the disciples’ message. Greater revelation brings greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:14": { title: "Sheep among Wolves", text: "Jesus sends His disciples into danger and tells them to be wise as serpents and harmless as doves. Prudence must be joined with innocence and integrity.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:15": { title: "Beware of Human Courts", text: "Jesus warns that people will deliver His followers to councils and scourge them in synagogues. Discipleship does not promise freedom from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:16": { title: "Witness Before Rulers", text: "The disciples will be brought before governors and kings as witnesses to them and the Gentiles. Even persecution can become an occasion to testify to the gospel.", refs: ["Acts 24:10–21","Acts 26:1–3"] },
  "Matthew 10:17": { title: "The Spirit Helps Them Speak", text: "When brought before authorities, disciples should not be consumed by anxiety over their testimony; the Spirit will help them speak. This promise concerns witness under persecution, not a rejection of preparation in every setting.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:18": { title: "Family Division", text: "Jesus warns that family members may betray one another because of the conflict caused by the gospel. He describes the painful cost of allegiance, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:19": { title: "Hated for Jesus’ Name", text: "The disciples will be hated for Jesus’ name, but the one who endures to the end will be saved. Endurance means remaining faithful through opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:20": { title: "Flee to Another City", text: "When persecuted in one city, the disciples may flee to another. Jesus does not demand needless exposure to danger; the mission can continue through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:21": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:22": { title: "Called Beelzebub", text: "If people call the master of the house Beelzebub, they will slander His household even more. Disciples should not be surprised by false accusations when Jesus Himself was maligned.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:23": { title: "Fear God, Not People", text: "Jesus tells the disciples not to fear those who can kill the body but cannot kill the soul. Their ultimate reverence belongs to God, the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:24": { title: "Proclaim What Is Hidden", text: "What Jesus teaches privately is to be proclaimed openly. The gospel must not remain hidden merely because its messengers fear opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:25": { title: "Speak the Message Openly", text: "Jesus repeats that His disciples should declare openly what they have heard. Faithful witness requires courage and clarity.", refs: ["Acts 20:20","Acts 20:27"] },
  "Matthew 10:26": { title: "God Knows the Sparrows", text: "Sparrows are sold for little, yet none falls without the Father’s knowledge. Jesus uses this to assure the disciples of God’s care amid danger.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:27": { title: "The Hairs of Your Head Are Numbered", text: "God’s knowledge of the disciples is intimate and complete. They are more valuable than many sparrows, giving them reason to resist fear.", refs: ["Luke 12:7","Isaiah 43:1"] },
  "Matthew 10:28": { title: "Confess Jesus Before People", text: "Whoever confesses Jesus before people will be acknowledged by Him before the Father. Jesus calls for open faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:29": { title: "Denying Jesus Has Consequences", text: "Jesus warns that whoever denies Him before people will be denied before the Father. The warning calls for steadfast confession under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:30": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:31": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:32": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:33": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:34": { title: "Receive Jesus’ Representatives", text: "Receiving Jesus’ disciples because they belong to Him is a way of receiving Jesus Himself. The verse stresses the importance of hospitality toward faithful messengers.", refs: ["Matthew 25:40","John 13:20"] },
  "Matthew 10:35": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:36": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:37": { title: "Even a Cup of Cold Water", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:1": { title: "Authority over Unclean Spirits", text: "Jesus gives the twelve authority over unclean spirits and to heal disease. Their authority is delegated by Jesus, not independent power or permission for personal gain.", refs: ["Mark 3:13–15","Luke 9:1"] },
  "Matthew 10:2": { title: "The First Apostles Named", text: "Matthew names Simon Peter and Andrew, and James and John. These men are called to serve as commissioned witnesses of Jesus.", refs: ["Luke 6:13–16","Acts 1:13"] },
  "Matthew 10:3": { title: "Four More Apostles", text: "Philip, Bartholomew, Thomas, and Matthew the publican are named. Jesus calls people from varied backgrounds into a shared mission.", refs: ["Mark 3:18","Luke 6:15"] },
  "Matthew 10:4": { title: "The Last Four Named", text: "James the son of Alphaeus, Lebbaeus, Simon the Canaanite, and Judas Iscariot complete the list. Judas’ inclusion warns that outward closeness to Jesus does not guarantee faithfulness.", refs: ["Luke 6:15–16","John 6:70–71"] },
  "Matthew 10:5": { title: "The Twelve Are Sent", text: "Jesus sends the twelve with specific instructions for this stage of their mission. These directions belong to the immediate context and must be read alongside the later commission to all nations.", refs: ["Matthew 28:19–20","Luke 9:2"] },
  "Matthew 10:6": { title: "Israel’s Lost Sheep", text: "The disciples are first directed to Israel’s lost sheep. This is the initial focus of Jesus’ earthly ministry, not a permanent exclusion of the Gentiles.", refs: ["Matthew 15:24","Romans 1:16"] },
  "Matthew 10:7": { title: "Preach the Kingdom", text: "The disciples announce that the kingdom of heaven is at hand, continuing Jesus’ call to repentance and readiness for God’s reign.", refs: ["Matthew 4:17","Luke 9:2"] },
  "Matthew 10:8": { title: "Heal and Give Freely", text: "The disciples are commissioned to heal, cleanse, raise the dead, and cast out devils; they must give freely because they received freely. God’s gifts must not be exploited for profit.", refs: ["Acts 8:18–23","2 Kings 5:15–16"] },
  "Matthew 10:9": { title: "Take No Gold or Silver", text: "For this particular mission, the disciples are told not to carry gold, silver, or brass in their purses. They are to depend on God and the hospitality provided, not turn ministry into a business.", refs: ["Luke 9:3","1 Timothy 6:5"] },
  "Matthew 10:10": { title: "Take No Extra Travel Supplies", text: "Jesus instructs them not to stockpile provisions for this journey. This specific commission should not be turned into a universal ban on prudent preparation, as later instructions differ.", refs: ["Luke 22:35–36","Mark 6:8–9"] },
  "Matthew 10:11": { title: "Seek a Worthy Household", text: "The disciples should seek a worthy household and remain there rather than move from house to house seeking better comfort. Their conduct should be stable and honorable.", refs: ["Luke 10:5–8","1 Timothy 5:18"] },
  "Matthew 10:12": { title: "Greet the House", text: "The disciples are to greet the household with peace. Their arrival should be marked by a sincere desire for peace, not conflict.", refs: ["Luke 10:5–6"] },
  "Matthew 10:13": { title: "Peace Rests on the House", text: "If the household is worthy, the disciples’ peace will rest upon it; if not, the peace returns to them. The mission’s welcome cannot be forced.", refs: ["Luke 10:6"] },
  "Matthew 10:14": { title: "Shake Off the Dust", text: "If a town refuses to receive them or hear their words, the disciples are to shake off its dust as a testimony. This is a sign of accountability, not permission for revenge.", refs: ["Acts 13:50–51","Luke 9:5"] },
  "Matthew 10:15": { title: "Judgment for Rejection", text: "Jesus says judgment will be more tolerable for Sodom and Gomorrah than for a town that rejects the disciples’ message. Greater revelation brings greater responsibility.", refs: ["Genesis 19:24–28","Luke 10:12–15"] },
  "Matthew 10:16": { title: "Wise as Serpents, Harmless as Doves", text: "Jesus sends His disciples as sheep among wolves and calls them to combine prudence with innocence. Wisdom must not become deceit, and harmlessness must not become foolishness.", refs: ["Luke 10:3","Romans 16:19"] },
  "Matthew 10:17": { title: "Beware of Men", text: "Jesus warns that people will deliver His followers to councils and scourge them in synagogues. Discipleship does not promise freedom from persecution.", refs: ["John 16:2","Acts 5:40"] },
  "Matthew 10:18": { title: "Witness Before Rulers", text: "The disciples will be brought before governors and kings as witnesses to them and the Gentiles. Even persecution can become an occasion to testify to the gospel.", refs: ["Acts 24:10–21","Acts 26:1–3"] },
  "Matthew 10:19": { title: "Do Not Be Anxious About Your Words", text: "When brought before authorities, disciples should not be consumed by anxiety over how to answer. Jesus gives this assurance for that moment of testimony, not as a rejection of preparation in every setting.", refs: ["Luke 12:11–12","Acts 4:8"] },
  "Matthew 10:20": { title: "The Spirit Will Help You Speak", text: "Jesus says the Spirit of the Father will speak through them in that hour. The promise encourages faithful witness under pressure and dependence on God.", refs: ["Mark 13:11","Acts 6:10"] },
  "Matthew 10:21": { title: "Family Members May Betray One Another", text: "Jesus warns that the gospel may bring division even within families, and that some will betray relatives to death. He describes the painful cost of allegiance, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:51–53"] },
  "Matthew 10:22": { title: "Hated for Jesus’ Name", text: "The disciples will be hated for Jesus’ name, but the one who endures to the end will be saved. Endurance means remaining faithful through opposition.", refs: ["Daniel 12:12","Matthew 24:13"] },
  "Matthew 10:23": { title: "Flee to Another City", text: "When persecuted in one city, the disciples may flee to another. Jesus does not demand needless exposure to danger; the mission can continue through prudent movement.", refs: ["Acts 8:1–4","Acts 14:5–7"] },
  "Matthew 10:24": { title: "The Disciple Is Not Above the Master", text: "Jesus says His followers should not expect better treatment than He receives. If the Master is opposed, His servants may also face hostility.", refs: ["John 13:16","John 15:20"] },
  "Matthew 10:25": { title: "Called Beelzebub", text: "If people call the master of the house Beelzebub, they will slander His household even more. Disciples should not be surprised by false accusations when Jesus Himself was maligned.", refs: ["Matthew 12:24","John 8:48"] },
  "Matthew 10:26": { title: "Fear God, Not People", text: "Jesus says not to fear those who can kill the body but cannot kill the soul. Ultimate reverence belongs to God, the final judge.", refs: ["Luke 12:4–5","Ecclesiastes 12:13–14"] },
  "Matthew 10:27": { title: "Proclaim What Is Hidden", text: "What Jesus teaches privately is to be proclaimed openly. The gospel must not remain hidden merely because its messengers fear opposition.", refs: ["Acts 4:19–20","Ephesians 6:19–20"] },
  "Matthew 10:28": { title: "Speak the Message Openly", text: "Jesus repeats that His disciples should declare openly what they have heard. Faithful witness requires courage and clarity.", refs: ["Acts 20:20","Acts 20:27"] },
  "Matthew 10:29": { title: "God Knows the Sparrows", text: "Not even a sparrow falls without the Father’s knowledge. Jesus uses this to assure the disciples of God’s care amid danger.", refs: ["Luke 12:6–7","Psalm 56:8"] },
  "Matthew 10:30": { title: "The Hairs of Your Head Are Numbered", text: "God’s knowledge of the disciples is intimate and complete. They are more valuable than many sparrows, giving them reason to resist fear.", refs: ["Luke 12:7","Isaiah 43:1"] },
  "Matthew 10:31": { title: "You Are of More Value Than Sparrows", text: "Jesus repeats that the disciples are precious to God. This assurance does not mean they will never suffer, but that they are never forgotten by the Father.", refs: ["Luke 12:6–7","Psalm 8:4–5"] },
  "Matthew 10:32": { title: "Confess Jesus Before People", text: "Whoever confesses Jesus before people will be acknowledged by Him before the Father. Jesus calls for open faithfulness, not merely private admiration.", refs: ["Romans 10:9–10","Revelation 3:5"] },
  "Matthew 10:33": { title: "Denying Jesus Has Consequences", text: "Jesus warns that whoever denies Him before people will be denied before the Father. The warning calls for steadfast confession under pressure.", refs: ["2 Timothy 2:12","Luke 12:9"] },
  "Matthew 10:34": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:35": { title: "Family Division Through the Gospel", text: "Jesus quotes the prophet to show that a person’s own household may become opponents. The division is a tragic response to the message, not a reason to hate family members.", refs: ["Micah 7:6","Luke 12:53"] },
  "Matthew 10:36": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:37": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:38": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:39": { title: "Receive Jesus’ Representatives", text: "Receiving Jesus’ disciples because they belong to Him is a way of receiving Jesus Himself. The verse stresses the importance of hospitality toward faithful messengers.", refs: ["Matthew 25:40","John 13:20"] },
  "Matthew 10:40": { title: "Receive the One Who Sent Jesus", text: "Receiving Jesus means receiving the Father who sent Him. In a Oneness reading, the Father’s saving mission is revealed through the Son; Jesus is the visible manifestation of the invisible God.", refs: ["John 12:44–45","John 14:9–10","2 Corinthians 5:19"] },
  "Matthew 10:41": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:42": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:43": { title: "A Cup of Cold Water Is Remembered", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 10:34": { title: "Not Peace but a Sword", text: "Jesus describes the division His message can bring, using the sword as an image of conflict. He is not commanding His followers to commit violence; the gospel exposes loyalties and can provoke opposition.", refs: ["Luke 12:51","John 18:36"] },
  "Matthew 10:35": { title: "Family Division Through the Gospel", text: "Jesus says His coming will expose deep divisions, even between close family members. This is a description of painful responses to His message, not a command to create conflict.", refs: ["Micah 7:6","Luke 12:52–53"] },
  "Matthew 10:36": { title: "A Person’s Enemies May Be in Their Own House", text: "Jesus quotes the prophet to warn that even household members may oppose a disciple. Faithfulness can bring painful rejection, but disciples are still commanded to act in love.", refs: ["Micah 7:6","Matthew 5:44"] },
  "Matthew 10:37": { title: "Love Jesus Above Family", text: "Disciples must love Jesus more than even their closest family ties when loyalties conflict. This does not cancel biblical duties to honor and care for family; it establishes the highest allegiance.", refs: ["Deuteronomy 6:5","Luke 14:26","1 Timothy 5:8"] },
  "Matthew 10:38": { title: "Take Up the Cross", text: "Whoever does not take up their cross and follow Jesus is not worthy of Him. Discipleship includes self-denial and willingness to suffer rather than abandon Christ.", refs: ["Matthew 16:24","Galatians 2:20"] },
  "Matthew 10:39": { title: "Lose Life to Find It", text: "The person who preserves life at any cost will lose it, while the one who loses life for Jesus’ sake will find it. Jesus reverses worldly measures of success.", refs: ["John 12:25","Philippians 3:7–8"] },
  "Matthew 10:40": { title: "Receive Jesus’ Disciples and the One Who Sent Him", text: "Jesus says receiving His disciples is receiving Him, and receiving Him is receiving the One who sent Him. In a Oneness reading, the Father’s saving mission is revealed through the Son; Jesus makes the invisible God known.", refs: ["Matthew 25:40","John 12:44–45","John 14:9–10","2 Corinthians 5:19"] },
  "Matthew 10:41": { title: "Receive a Prophet as a Prophet", text: "Whoever receives a prophet because he is a prophet will receive a prophet’s reward. God values support for those who faithfully speak His word.", refs: ["1 Kings 17:9–16","2 Kings 4:8–10"] },
  "Matthew 10:42": { title: "Receive a Righteous Person", text: "Whoever receives a righteous person because he is righteous will receive a righteous person’s reward. The verse encourages honor and practical support for those who live faithfully.", refs: ["Psalm 41:1","Hebrews 6:10"] },
  "Matthew 10:43": { title: "A Cup of Cold Water Is Remembered", text: "Even a cup of cold water given to one of Jesus’ little ones because they are His disciple will not lose its reward. God notices small acts of genuine kindness and service.", refs: ["Mark 9:41","Hebrews 6:10"] }
});
delete window.verseCommentary["Matthew 10:43"];

Object.assign(window.verseCommentary, {
  "Matthew 11:1": { title: "Jesus Finishes Instructing the Twelve", text: "After giving the twelve their mission instructions, Jesus continues teaching and preaching in the cities. The work of the kingdom continues beyond the disciples’ first assignment.", refs: ["Matthew 10:5–15","Luke 9:1–6"] },
  "Matthew 11:2": { title: "John Hears of Christ’s Works", text: "John the Baptist, now in prison, hears about Jesus’ works and sends disciples to ask Him a question. His confinement does not end his concern for God’s promised deliverance.", refs: ["Matthew 14:3–5","Luke 7:18–20"] },
  "Matthew 11:3": { title: "Are You the Coming One?", text: "John’s disciples ask whether Jesus is the expected One or whether they should look for another. The question invites Jesus to identify His mission through Scripture-fulfilling works.", refs: ["Malachi 3:1","Luke 7:19"] },
  "Matthew 11:4": { title: "Jesus Points to His Works", text: "Jesus tells them to report what they see and hear: the blind see, the lame walk, lepers are cleansed, the deaf hear, the dead are raised, and the poor receive the gospel. These works fulfill prophetic signs of restoration.", refs: ["Isaiah 35:5–6","Isaiah 61:1","Luke 4:18"] },
  "Matthew 11:5": { title: "Blessed Is the One Not Offended in Jesus", text: "Jesus blesses the person who is not offended by Him. His mission may differ from expectations, but His works reveal God’s promised salvation.", refs: ["Isaiah 8:14","1 Peter 2:6–8"] },
  "Matthew 11:6": { title: "Jesus Asks About John", text: "As John’s messengers leave, Jesus asks the crowd what they went into the wilderness to see. He leads them to recognize John’s prophetic role.", refs: ["Luke 7:24–26"] },
  "Matthew 11:7": { title: "Not a Reed Shaken by Wind", text: "John was not a weak or easily swayed person. His prophetic message was firm, even though it led to imprisonment.", refs: ["Matthew 3:1–4","Ephesians 4:14"] },
  "Matthew 11:8": { title: "Not a Man in Soft Clothing", text: "John was not a courtly figure dressed in luxury; those who wear such clothing live in kings’ houses. His prophetic authority did not come from worldly status.", refs: ["Matthew 3:4","Mark 1:6"] },
  "Matthew 11:9": { title: "More Than a Prophet", text: "Jesus declares John more than a prophet because he is the messenger who prepares the way. John has a unique place in the unfolding plan of God.", refs: ["Malachi 3:1","Luke 1:76"] },
  "Matthew 11:10": { title: "The Messenger Who Prepares the Way", text: "Jesus applies the prophecy of the messenger to John. John prepares the people for the Lord’s coming, and the New Testament presents Jesus as the center of that arrival.", refs: ["Isaiah 40:3","Malachi 3:1","Matthew 3:3"] },
  "Matthew 11:11": { title: "None Greater Among Those Born of Women", text: "Jesus honors John as the greatest among those born of women, yet says the least in the kingdom of heaven is greater. The contrast concerns the privilege of the kingdom age, not a denial of John’s faithfulness.", refs: ["Luke 7:28","Hebrews 11:39–40"] },
  "Matthew 11:12": { title: "The Kingdom Suffers Violence", text: "The wording describes violent opposition or forceful struggle surrounding the kingdom; the precise nuance is debated. The context emphasizes the intense conflict accompanying God’s kingdom proclamation.", refs: ["Luke 16:16","Ephesians 6:12"] },
  "Matthew 11:13": { title: "The Law and Prophets Until John", text: "The Law and the Prophets prophesied until John, whose ministry marks a transition toward the announced kingdom. Jesus does not dismiss Scripture; He brings its promises toward fulfillment.", refs: ["Luke 16:16","Matthew 5:17"] },
  "Matthew 11:14": { title: "John as Elijah Who Was to Come", text: "If the hearers are willing to receive it, John fulfills the promised Elijah-like forerunner. This is a prophetic role and ministry, not a claim that John is literally the ancient Elijah returned as the same person.", refs: ["Malachi 4:5–6","Luke 1:17","John 1:21"] },
  "Matthew 11:15": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls the hearers to understand the spiritual significance of what He has said. Hearing physically is not the same as receiving the message with faith.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 11:16": { title: "This Generation Like Children in the Marketplace", text: "Jesus compares the generation to children who complain when others will not play their chosen game. The image exposes people who reject both John’s seriousness and Jesus’ gracious approach.", refs: ["Luke 7:31–32"] },
  "Matthew 11:17": { title: "John Is Accused of Having a Devil", text: "John’s austere life is criticized as demonic. The charge shows how people can discredit a messenger rather than honestly consider the message.", refs: ["Matthew 3:4","Luke 7:33"] },
  "Matthew 11:18": { title: "The Son of Man Is Called a Glutton", text: "Jesus’ ordinary fellowship with people is misrepresented as excess and moral compromise. People who refuse God’s call can find fault with opposite styles of ministry.", refs: ["Luke 7:34","Matthew 9:10–13"] },
  "Matthew 11:19": { title: "Wisdom Is Justified by Her Children", text: "God’s wisdom is shown to be right by its results and fruit. The responses to John and Jesus do not invalidate the wisdom of God’s different ministries.", refs: ["Luke 7:35","Proverbs 8:1–8"] },
  "Matthew 11:20": { title: "Woe to Chorazin and Bethsaida", text: "Jesus pronounces woe on cities that saw mighty works but did not repent. Greater exposure to God’s work increases responsibility to respond.", refs: ["Luke 10:13–14","Jonah 3:5–10"] },
  "Matthew 11:21": { title: "Capernaum Will Be Brought Down", text: "Capernaum’s exalted position will not protect it from judgment because it failed to repent. Privilege without response brings accountability.", refs: ["Isaiah 14:13–15","Luke 10:15"] },
  "Matthew 11:22": { title: "Judgment More Tolerable for Sodom", text: "Jesus says judgment will be more tolerable for Sodom than for a city that rejected His works. The warning emphasizes the seriousness of refusing clear revelation.", refs: ["Genesis 19:24–28","Matthew 10:15"] },
  "Matthew 11:23": { title: "Jesus Thanks the Father", text: "Jesus thanks the Father, Lord of heaven and earth, for revealing truth to the humble rather than those who trust in their own wisdom. The passage emphasizes God’s sovereign revelation.", refs: ["Luke 10:21","1 Corinthians 1:26–29"] },
  "Matthew 11:24": { title: "The Father and the Son", text: "Jesus says all things are delivered to Him by the Father, and that the Father is known through the Son. In a Oneness reading, God is made known in Christ; the passage describes their relationship in the saving mission without requiring two separate Gods.", refs: ["John 1:18","John 14:9–10","Colossians 2:9"] },
  "Matthew 11:25": { title: "The Son Reveals the Father", text: "No one fully knows the Father except the Son and those to whom the Son reveals Him. Jesus is the definitive revelation of the invisible God.", refs: ["John 1:18","Hebrews 1:1–3"] },
  "Matthew 11:26": { title: "Come to Me, All Who Labour", text: "Jesus invites the weary and burdened to come to Him for rest. His invitation is personal and compassionate, reaching those exhausted by burdens they cannot carry alone.", refs: ["Isaiah 55:1–3","John 7:37"] },
  "Matthew 11:27": { title: "I Will Give You Rest", text: "Jesus promises rest to those who come to Him. This rest includes relief for the soul and a new relationship with God, not a guarantee of a trouble-free life.", refs: ["Jeremiah 6:16","Hebrews 4:9–11"] },
  "Matthew 11:28": { title: "Take My Yoke upon You", text: "Jesus calls disciples to take His yoke and learn from Him. A yoke implies guidance and service; His way is shaped by His own meekness and humility.", refs: ["Jeremiah 6:16","John 13:15"] },
  "Matthew 11:29": { title: "Learn of Me, for I Am Meek", text: "Jesus describes Himself as meek and lowly in heart. His authority is not harsh domination; He leads with humility and compassion.", refs: ["Zechariah 9:9","Philippians 2:5–8"] },
  "Matthew 11:30": { title: "His Yoke Is Easy and His Burden Light", text: "Jesus’ yoke is easy and His burden light compared with crushing burdens. He does not promise the absence of sacrifice, but offers a faithful way of life under His gracious leadership.", refs: ["1 John 5:3","Matthew 23:4"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 12:1": { title: "Disciples Pluck Grain on the Sabbath", text: "Jesus’ disciples pluck grain because they are hungry as they walk through the fields on the Sabbath. Their action raises a dispute about how Sabbath law should be applied.", refs: ["Mark 2:23–24","Luke 6:1–2"] },
  "Matthew 12:2": { title: "The Pharisees Object", text: "The Pharisees accuse the disciples of doing what is not lawful on the Sabbath. Their interpretation focuses on the action without considering need and the scriptural precedents Jesus will cite.", refs: ["Exodus 20:8–10","Deuteronomy 23:25"] },
  "Matthew 12:3": { title: "David Eats the Shewbread", text: "Jesus reminds them that David and his companions ate the consecrated bread when they were hungry. Scripture itself records an exceptional act in a time of need.", refs: ["1 Samuel 21:1–6","Mark 2:25–26"] },
  "Matthew 12:4": { title: "The Priests and Sabbath Service", text: "Jesus notes that priests perform temple duties on the Sabbath and are blameless. The law itself makes room for service and need, so the Pharisees’ accusation is incomplete.", refs: ["Numbers 28:9–10","John 7:22–23"] },
  "Matthew 12:5": { title: "One Greater Than the Temple", text: "Jesus declares that something greater than the temple is present. His authority and mission exceed the temple’s symbolic role in Israel’s worship.", refs: ["Matthew 12:41–42","Colossians 2:9"] },
  "Matthew 12:6": { title: "Mercy, Not Sacrifice", text: "Jesus quotes Hosea to teach that God desires mercy rather than empty ritual. The disciples’ hunger should be met with compassion, not condemned through a harsh interpretation.", refs: ["Hosea 6:6","Matthew 9:13"] },
  "Matthew 12:7": { title: "The Son of Man Is Lord of the Sabbath", text: "Jesus declares the Son of man Lord even of the Sabbath. His authority determines the right understanding of Sabbath purpose; the Sabbath was not intended as a weapon against mercy.", refs: ["Mark 2:27–28","Luke 6:5"] },
  "Matthew 12:8": { title: "Jesus Enters the Synagogue", text: "Jesus enters a synagogue where a man with a withered hand is present. The setting creates a second Sabbath controversy about doing good.", refs: ["Mark 3:1","Luke 6:6"] },
  "Matthew 12:9": { title: "They Ask to Accuse Him", text: "The question about healing on the Sabbath is asked to find grounds for accusation, not sincerely to learn. The passage warns against using religious debate as a trap.", refs: ["Mark 3:2","Luke 14:1"] },
  "Matthew 12:10": { title: "A Sheep in a Pit", text: "Jesus asks who would not rescue a sheep that fell into a pit on the Sabbath. Their ordinary compassion for an animal exposes the inconsistency of opposing mercy to a suffering person.", refs: ["Luke 14:5","Deuteronomy 22:4"] },
  "Matthew 12:11": { title: "A Man Is Worth More Than a Sheep", text: "Jesus concludes that it is lawful to do well on the Sabbath. Human need matters, and Sabbath observance should be consistent with God’s mercy.", refs: ["Mark 3:4","Luke 6:9"] },
  "Matthew 12:12": { title: "Jesus Heals the Withered Hand", text: "Jesus tells the man to stretch out his hand, and it is restored whole. The healing demonstrates Jesus’ authority and the goodness of doing good on the Sabbath.", refs: ["Mark 3:5","Luke 6:10"] },
  "Matthew 12:13": { title: "The Pharisees Plot Against Jesus", text: "The Pharisees leave and take counsel to destroy Jesus. Their response to a healing exposes how religious hostility can become more committed to power than to mercy.", refs: ["Mark 3:6","John 11:53"] },
  "Matthew 12:14": { title: "Jesus Withdraws from Them", text: "Jesus knows of the plot and withdraws, while many people follow Him. His withdrawal is prudent, and His ministry of healing continues.", refs: ["Matthew 10:23","Mark 3:7–10"] },
  "Matthew 12:15": { title: "Jesus Heals and Warns Them", text: "Jesus heals the people and charges them not to make Him known. His mission is not driven by sensational publicity; Matthew sees this restraint as prophetic fulfillment.", refs: ["Mark 1:43–45","Matthew 8:4"] },
  "Matthew 12:16": { title: "The Servant Chosen by God", text: "Matthew quotes Isaiah’s description of God’s chosen servant, beloved and pleasing to Him. The passage presents Jesus’ Spirit-empowered mission and gentle manner.", refs: ["Isaiah 42:1","Matthew 3:17"] },
  "Matthew 12:17": { title: "He Will Declare Judgment to the Gentiles", text: "Jesus’ mission carries God’s judgment and justice beyond Israel to the nations. The Messiah’s work has a global horizon.", refs: ["Isaiah 42:1","Matthew 28:19"] },
  "Matthew 12:18": { title: "He Will Not Strive or Cry Out", text: "The servant does not advance by loud self-promotion or violent struggle. Jesus’ gentleness contrasts with worldly displays of power.", refs: ["Isaiah 42:2","1 Peter 2:23"] },
  "Matthew 12:19": { title: "A Bruised Reed He Will Not Break", text: "Jesus treats the weak with patience rather than crushing them. The image portrays compassionate care for people who are wounded or nearly overwhelmed.", refs: ["Isaiah 42:3","Matthew 11:28–30"] },
  "Matthew 12:20": { title: "Until He Sends Forth Judgment to Victory", text: "Jesus persists until God’s justice is brought to victory. His gentleness is not weakness; He faithfully completes the mission God gave Him.", refs: ["Isaiah 42:3–4","Revelation 19:11"] },
  "Matthew 12:21": { title: "In His Name the Gentiles Trust", text: "The nations will place their hope in Jesus. Matthew’s quotation points beyond Israel to the worldwide reach of God’s saving purpose.", refs: ["Isaiah 42:4","Romans 15:12"] },
  "Matthew 12:22": { title: "A Blind and Dumb Man Is Healed", text: "A demon-possessed man who is blind and unable to speak is brought to Jesus, and Jesus heals him. The miracle displays authority over both affliction and demonic oppression.", refs: ["Matthew 9:32–33","Luke 11:14"] },
  "Matthew 12:23": { title: "The People Ask If He Is the Son of David", text: "The crowds wonder whether Jesus is the promised Son of David. His works lead them to consider His messianic identity.", refs: ["Matthew 9:27","John 7:31"] },
  "Matthew 12:24": { title: "The Pharisees Attribute His Power to Beelzebub", text: "The Pharisees claim Jesus casts out devils by Beelzebub, the prince of devils. They try to explain away the evidence rather than receive it as God’s work.", refs: ["Matthew 9:34","Mark 3:22"] },
  "Matthew 12:25": { title: "A Kingdom Divided Cannot Stand", text: "Jesus argues that Satan would be undermining his own kingdom if Satan were casting out Satan. The accusation is internally inconsistent.", refs: ["Mark 3:23–26","Luke 11:17–18"] },
  "Matthew 12:26": { title: "Satan’s House Divided", text: "Jesus continues that a divided kingdom or house cannot stand. His reasoning exposes the absurdity of attributing deliverance from Satan to Satan’s own power.", refs: ["Luke 11:17–18"] },
  "Matthew 12:27": { title: "By Whom Do Your Children Cast Them Out?", text: "Jesus asks by whose power the accusers’ own followers cast out devils; they will be their judges. Their double standard exposes the weakness of their charge.", refs: ["Acts 19:13–16","Luke 11:19"] },
  "Matthew 12:28": { title: "The Spirit of God Casts Out Devils", text: "Jesus says that if He casts out devils by the Spirit of God, then God’s kingdom has come upon them. The deliverance is evidence that God’s reign is breaking in through Jesus.", refs: ["Luke 11:20","Acts 10:38"] },
  "Matthew 12:29": { title: "The Strong Man Is Bound", text: "A person must bind a strong man before plundering his house. Jesus’ deliverance of the oppressed shows that He is overcoming the power that held them captive.", refs: ["Isaiah 49:24–25","Luke 11:21–22"] },
  "Matthew 12:30": { title: "The Strong Man’s House Is Spoiled", text: "Jesus depicts Himself as stronger than the oppressor, able to rescue those held in bondage. The image supports His claim that God’s kingdom is active in His ministry.", refs: ["Luke 11:22","1 John 3:8"] },
  "Matthew 12:31": { title: "Whoever Is Not with Me", text: "Jesus says those who are not with Him are against Him, and those who do not gather with Him scatter. His mission demands a response; neutrality toward His saving work is not lasting discipleship.", refs: ["Luke 11:23","Joshua 24:15"] },
  "Matthew 12:32": { title: "Blasphemy Against the Holy Ghost", text: "Jesus warns that blasphemy against the Holy Ghost will not be forgiven. In context, the warning concerns knowingly attributing God’s liberating work to an evil source; it should not be used to torment tender consciences over unwanted thoughts.", refs: ["Mark 3:28–30","Luke 12:10"] },
  "Matthew 12:33": { title: "A Word Against the Son of Man", text: "Jesus distinguishes speaking against the Son of man from blasphemy against the Holy Ghost. The verse recognizes that people may misunderstand Jesus’ humble human appearance, while deliberate rejection of God’s Spirit-work is far more serious.", refs: ["Luke 12:10","John 7:12"] },
  "Matthew 12:34": { title: "Blasphemy Against the Holy Ghost Will Not Be Forgiven", text: "Jesus repeats the warning that blasphemy against the Holy Ghost will not be forgiven in this age or the age to come. The context is a hardened accusation against the Spirit’s work, not a casual mistake or a fearful intrusive thought.", refs: ["Mark 3:29–30","Hebrews 10:26–29"] },
  "Matthew 12:35": { title: "A Tree Is Known by Its Fruit", text: "Jesus says a tree is known by its fruit. The Pharisees’ words reveal their hearts, just as a tree’s fruit reveals its nature.", refs: ["Matthew 7:16–20","Luke 6:43–45"] },
  "Matthew 12:36": { title: "Out of the Heart the Mouth Speaks", text: "Words reveal what fills the heart. Jesus calls people to examine not only outward behavior but also the inner source of speech.", refs: ["Luke 6:45","James 3:8–12"] },
  "Matthew 12:37": { title: "Words Will Be Judged", text: "People will give account for careless words on the day of judgment. Speech matters because it reveals the heart and can harm or help others.", refs: ["Ecclesiastes 12:14","James 3:1–10"] },
  "Matthew 12:38": { title: "By Your Words You Are Justified", text: "Words can testify to faithfulness or expose guilt. Jesus does not teach salvation by speech alone; He warns that our words are evidence of the heart’s condition.", refs: ["Romans 10:9–10","James 2:17–18"] },
  "Matthew 12:39": { title: "The Scribes and Pharisees Ask for a Sign", text: "The religious leaders ask Jesus for a sign even after witnessing His works. Their demand reflects unbelief rather than an honest lack of evidence.", refs: ["Matthew 16:1–4","John 2:18"] },
  "Matthew 12:40": { title: "The Sign of the Prophet Jonah", text: "Jesus says the sign of Jonah will be given. Jonah’s three days in the great fish foreshadow Jesus’ death and resurrection.", refs: ["Jonah 1:17","Matthew 16:4"] },
  "Matthew 12:41": { title: "The Son of Man Three Days and Nights", text: "Jesus compares His coming burial and resurrection to Jonah’s time in the fish. The expression is a Jewish way of describing the period and should be read with the Gospel’s chronology.", refs: ["Jonah 1:17","1 Corinthians 15:4"] },
  "Matthew 12:42": { title: "Nineveh Will Rise in Judgment", text: "The people of Nineveh repented at Jonah’s preaching, while Jesus’ hearers rejected one greater than Jonah. Greater light brings greater accountability.", refs: ["Jonah 3:5–10","Luke 11:32"] },
  "Matthew 12:43": { title: "The Queen of the South Will Rise", text: "The queen of the south travelled to hear Solomon’s wisdom, yet Jesus is greater than Solomon. Her example exposes the refusal of people who have a greater revelation before them.", refs: ["1 Kings 10:1–10","2 Chronicles 9:1–8"] },
  "Matthew 12:44": { title: "Something Greater Than Solomon Is Here", text: "Jesus declares that one greater than Solomon is present. His wisdom and messianic authority surpass Israel’s greatest royal sage.", refs: ["1 Kings 3:12","Colossians 2:3"] },
  "Matthew 12:45": { title: "The Unclean Spirit Returns", text: "Jesus describes an unclean spirit leaving a person and later returning with others when the person is left spiritually empty. The warning emphasizes the need for genuine, lasting transformation.", refs: ["Luke 11:24–26","2 Peter 2:20"] },
  "Matthew 12:46": { title: "An Empty House Is Not Enough", text: "The spirit finds the house empty, swept, and garnished. External reform without a new allegiance to God leaves a person vulnerable to a worse condition.", refs: ["John 5:14","Romans 6:11–14"] },
  "Matthew 12:47": { title: "The Last State Is Worse", text: "The final state of the person becomes worse than the first. Jesus warns against temporary reform that does not lead to a lasting response to God.", refs: ["2 Peter 2:20–22","Hebrews 6:4–6"] },
  "Matthew 12:48": { title: "A Woman Calls Mary Blessed", text: "A woman in the crowd blesses the womb that bore Jesus and the breasts that nursed Him. Jesus responds by emphasizing obedience to God’s word rather than biological relationship alone.", refs: ["Luke 11:27–28"] },
  "Matthew 12:49": { title: "Hear and Keep God’s Word", text: "Jesus says those who hear and keep God’s word are blessed. The emphasis is not disrespect for His mother but on faithful obedience as the mark of true discipleship.", refs: ["Luke 8:21","James 1:22–25"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 12:46": { title: "Jesus’ Mother and Brethren Stand Outside", text: "While Jesus speaks to the multitude, His mother and brethren stand outside and seek to speak with Him. The scene sets up Jesus’ teaching about spiritual kinship.", refs: ["Mark 3:31–32","Luke 8:19"] },
  "Matthew 12:47": { title: "Someone Tells Jesus His Family Is Waiting", text: "A person informs Jesus that His mother and brethren are outside wishing to speak with Him. Jesus uses the moment to teach rather than dismiss the importance of family care.", refs: ["Mark 3:32","Luke 8:20"] },
  "Matthew 12:48": { title: "Who Is My Mother?", text: "Jesus asks who His mother and brethren are, preparing to identify His spiritual family. His question does not deny His human family; it highlights a deeper relationship formed by obedience to God.", refs: ["Mark 3:33","John 2:4"] },
  "Matthew 12:49": { title: "Jesus Points to His Disciples", text: "Jesus stretches His hand toward His disciples and identifies them as His family in this spiritual sense. Those who follow Him belong to a community defined by doing God’s will.", refs: ["Mark 3:34","Hebrews 2:11–12"] },
  "Matthew 12:50": { title: "Whoever Does the Father’s Will Is Family", text: "Jesus says whoever does the will of His Father in heaven is His brother, sister, and mother. True spiritual kinship is marked by obedience to God, not merely by biological connection.", refs: ["Luke 8:21","John 14:15","James 1:22"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 13:1": { title: "The Sower Goes Out", text: "Jesus begins a parable about a sower scattering seed. The seed will encounter different conditions, illustrating varied responses to God’s word.", refs: ["Mark 4:1–9","Luke 8:4–8"] },
  "Matthew 13:2": { title: "The Crowds Gather", text: "A great multitude gathers, so Jesus enters a ship while the people stand on the shore. He teaches through parables that invite listeners to consider the condition of their hearts.", refs: ["Mark 4:1–2"] },
  "Matthew 13:3": { title: "Seed by the Wayside", text: "Some seed falls by the wayside, where birds devour it. The image begins to show how the word may be heard without taking root.", refs: ["Luke 8:5, 12"] },
  "Matthew 13:4": { title: "Seed on Stony Places", text: "Some seed falls on shallow, stony ground and springs up quickly because the soil is thin. Initial enthusiasm without depth cannot endure hardship.", refs: ["Mark 4:5–6","Luke 8:6"] },
  "Matthew 13:5": { title: "Seed among Thorns", text: "Some seed falls among thorns, which grow up and choke it. Competing desires can prevent God’s word from bearing fruit.", refs: ["Luke 8:7, 14"] },
  "Matthew 13:6": { title: "Good Ground Bears Fruit", text: "Other seed falls on good ground and produces a harvest. The parable emphasizes receptive hearts that hear and respond fruitfully.", refs: ["Luke 8:8, 15"] },
  "Matthew 13:7": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls listeners to pay close attention. Parables require more than hearing the story; they call for spiritual understanding and response.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:8": { title: "The Disciples Ask Why Parables", text: "The disciples ask why Jesus speaks to the multitude in parables. Jesus explains that understanding is granted to receptive disciples, while others remain unmoved by what they hear.", refs: ["Mark 4:10–12"] },
  "Matthew 13:9": { title: "Knowledge of the Kingdom Given", text: "Jesus tells His disciples that they are given to know the mysteries of the kingdom. This knowledge is a gift that brings responsibility to respond faithfully.", refs: ["1 Corinthians 2:10–12","Ephesians 1:9"] },
  "Matthew 13:10": { title: "More Will Be Given to the Receptive", text: "Those who receive and use the truth they have will be given more understanding; those who reject it lose even what they think they have. The principle concerns spiritual responsiveness.", refs: ["Luke 8:18","Mark 4:24–25"] },
  "Matthew 13:11": { title: "Seeing Without Perceiving", text: "Jesus explains that some see the works and hear the teaching without truly perceiving their meaning. Spiritual blindness is not merely a lack of information.", refs: ["Isaiah 6:9–10","John 12:40"] },
  "Matthew 13:12": { title: "The Heart Has Grown Dull", text: "Jesus quotes Isaiah about people whose hearts are dull and whose ears are slow to hear. Persistent refusal can harden a person against truth.", refs: ["Isaiah 6:10","Acts 28:26–27"] },
  "Matthew 13:13": { title: "Turning and Being Healed", text: "The prophecy speaks of people who might turn and be healed. God’s truth calls for repentance and restoration, but the hearer must not harden the heart against it.", refs: ["Isaiah 6:10","James 5:19–20"] },
  "Matthew 13:14": { title: "Blessed Are Your Eyes", text: "Jesus tells the disciples their eyes are blessed because they see what prophets and righteous people longed to see. They witness the Messiah’s ministry and the kingdom’s arrival.", refs: ["Luke 10:23–24","Hebrews 11:13"] },
  "Matthew 13:15": { title: "Prophets Desired to See This Day", text: "The prophets and righteous people desired to see and hear what the disciples experience. Their privilege calls for gratitude and faithful response.", refs: ["1 Peter 1:10–12","Hebrews 11:39–40"] },
  "Matthew 13:16": { title: "The Sower Parable Explained", text: "Jesus explains that the seed is the word of the kingdom. The wayside hearer does not understand, and the evil one takes away what was sown in the heart.", refs: ["Luke 8:11–12","Mark 4:14–15"] },
  "Matthew 13:17": { title: "The Stony-Ground Hearer", text: "The stony-ground hearer receives the word quickly and joyfully but has no root. When tribulation or persecution comes because of the word, the person falls away.", refs: ["Mark 4:16–17","James 1:2–4"] },
  "Matthew 13:18": { title: "The Thorny-Ground Hearer", text: "The thorny-ground hearer hears the word, but worldly care and the deceitfulness of riches choke it. A crowded heart cannot produce mature spiritual fruit.", refs: ["Luke 8:14","1 Timothy 6:9–10"] },
  "Matthew 13:19": { title: "The Good-Ground Hearer", text: "The good-ground hearer understands and bears fruit, some thirtyfold, some sixtyfold, and some an hundredfold. Fruitfulness varies, but genuine reception produces a harvest.", refs: ["Luke 8:15","John 15:5"] },
  "Matthew 13:20": { title: "The Wheat and Tares", text: "Jesus gives another parable: a man sows good seed, but an enemy later sows tares among the wheat. Good and evil appear together in the present world until the harvest.", refs: ["Matthew 13:36–43"] },
  "Matthew 13:21": { title: "The Enemy Sows Tares", text: "The enemy sows tares while people sleep and departs. The parable portrays opposition to God’s work without suggesting that servants can always identify evil perfectly at first.", refs: ["Matthew 13:38–39","2 Corinthians 11:13–15"] },
  "Matthew 13:22": { title: "The Wheat Appears with Tares", text: "When the plants grow, the tares also become visible. The coexistence of good and evil creates a question about how the servants should respond.", refs: ["Matthew 13:27–28"] },
  "Matthew 13:23": { title: "The Servants Ask About the Tares", text: "The servants ask whether the enemy’s weeds should be pulled out. Their question represents the desire to remove evil immediately, but Jesus will warn of the danger of harming the wheat.", refs: ["Matthew 13:28–29"] },
  "Matthew 13:24": { title: "The Enemy Has Done This", text: "The householder identifies an enemy as the source of the tares. Jesus recognizes opposition to the kingdom while directing His servants away from rash judgment.", refs: ["Matthew 13:39","John 8:44"] },
  "Matthew 13:25": { title: "Let Both Grow Until Harvest", text: "The householder says to let both grow until harvest, lest pulling up tares damage the wheat. Final separation belongs to God’s appointed judgment, not human vengeance.", refs: ["Matthew 13:30","Romans 12:19"] },
  "Matthew 13:26": { title: "The Mustard Seed", text: "Jesus compares the kingdom of heaven to a mustard seed that is very small when sown but grows into a large plant. God’s kingdom may begin in an unimpressive way yet grow greatly.", refs: ["Mark 4:30–32","Luke 13:18–19"] },
  "Matthew 13:27": { title: "The Kingdom Grows from Small Beginnings", text: "The mustard seed’s growth illustrates the surprising expansion of God’s kingdom. The parable encourages trust in God’s work even when its beginning seems small.", refs: ["Zechariah 4:10","Acts 1:8"] },
  "Matthew 13:28": { title: "The Leaven in the Meal", text: "Jesus compares the kingdom to leaven that a woman hides in flour until all is leavened. The image emphasizes pervasive influence working through the whole measure.", refs: ["Luke 13:20–21","1 Corinthians 5:6"] },
  "Matthew 13:29": { title: "Jesus Teaches in Parables", text: "Jesus speaks to the multitude in parables, fulfilling the prophetic pattern of revealing truth through figures. His teaching both reveals and calls for attentive understanding.", refs: ["Psalm 78:2","Mark 4:33–34"] },
  "Matthew 13:30": { title: "The Prophetic Use of Parables", text: "Matthew connects Jesus’ parables with the prophetic Scriptures. The kingdom’s truth is communicated in a form that calls hearers to seek and understand.", refs: ["Psalm 78:2","Romans 15:4"] },
  "Matthew 13:31": { title: "Jesus Sends the Crowd Away", text: "Jesus sends the multitude away and enters the house. The disciples then ask for a fuller explanation of the parable of the tares.", refs: ["Matthew 13:36"] },
  "Matthew 13:32": { title: "Explain the Tares", text: "The disciples ask Jesus to explain the parable of the tares. Their request models seeking understanding rather than pretending to know.", refs: ["Proverbs 2:3–5","James 1:5"] },
  "Matthew 13:33": { title: "The Sower of Good Seed Is the Son of Man", text: "Jesus identifies the one who sows good seed as the Son of man. The parable centers on His authority and the kingdom work He carries out.", refs: ["Matthew 8:20","Matthew 16:13"] },
  "Matthew 13:34": { title: "The Field Is the World", text: "Jesus identifies the field as the world. The parable’s scope reaches beyond a local congregation to the world in which the kingdom’s people live.", refs: ["Matthew 28:19","John 3:16"] },
  "Matthew 13:35": { title: "The Good Seed Are the Children of the Kingdom", text: "The good seed represents the children of the kingdom. Their identity should be seen in relation to God’s reign and the fruit of faithful living.", refs: ["Matthew 5:14–16","Romans 8:14"] },
  "Matthew 13:36": { title: "The Tares Are the Children of the Wicked One", text: "The tares represent those aligned with evil. Jesus’ imagery is about spiritual allegiance and final judgment, not permission to label disliked people as enemies.", refs: ["John 8:44","1 John 3:10"] },
  "Matthew 13:37": { title: "The Enemy Is the Devil", text: "Jesus identifies the enemy who sows tares as the devil. Scripture presents evil as opposing God’s work, while affirming that God will finally judge it.", refs: ["Genesis 3:1–15","1 Peter 5:8"] },
  "Matthew 13:38": { title: "The Harvest Is the End of the World", text: "The harvest represents the end of the age, when the present mixture will be brought to judgment. The parable directs hope toward God’s final justice.", refs: ["Matthew 24:3","Revelation 14:14–16"] },
  "Matthew 13:39": { title: "The Reapers Are the Angels", text: "Jesus identifies the reapers as angels. The final separation is assigned to God’s agents, not to human attempts at violent purification.", refs: ["Matthew 24:31","Hebrews 1:14"] },
  "Matthew 13:40": { title: "The Tares Are Gathered for Burning", text: "As tares are gathered and burned, so evil will face judgment at the end of the age. The image is a serious warning against continuing in lawlessness.", refs: ["Matthew 13:40–42","Revelation 20:11–15"] },
  "Matthew 13:41": { title: "The Son of Man Sends His Angels", text: "Jesus describes the Son of man sending angels to gather out of His kingdom those who cause sin and practice lawlessness. The passage portrays the Messiah’s authority in final judgment.", refs: ["Matthew 24:30–31","2 Thessalonians 1:7–9"] },
  "Matthew 13:42": { title: "A Furnace of Fire", text: "The image of a furnace of fire conveys the severity of final judgment and the anguish of those rejected. Jesus calls hearers to take righteousness and repentance seriously.", refs: ["Matthew 25:41","Revelation 20:15"] },
  "Matthew 13:43": { title: "The Righteous Shine Forth", text: "The righteous shine as the sun in their Father’s kingdom. After judgment, God’s people share in the glory of His righteous reign.", refs: ["Daniel 12:3","Philippians 2:15"] },
  "Matthew 13:44": { title: "He That Has Ears, Let Him Hear", text: "Jesus again calls for careful hearing. The teaching about judgment is meant to awaken faithful response, not mere curiosity about the future.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:45": { title: "Treasure Hidden in a Field", text: "The kingdom is like treasure hidden in a field, which a man finds and hides again before joyfully selling all he has to buy the field. The parable stresses the kingdom’s surpassing worth.", refs: ["Philippians 3:7–8","Matthew 19:21"] },
  "Matthew 13:46": { title: "The Joy of Finding the Kingdom", text: "The man’s joy leads him to give up everything for the treasure. Following God’s kingdom is not merely loss; it is a joyful response to a value greater than all else.", refs: ["Psalm 16:11","Luke 14:33"] },
  "Matthew 13:47": { title: "The Pearl of Great Price", text: "A merchant seeking fine pearls finds one of great value and sells all to obtain it. The kingdom is worth more than any competing possession or ambition.", refs: ["Proverbs 3:13–15","Philippians 3:8"] },
  "Matthew 13:48": { title: "The Merchant Gives All for the Pearl", text: "The merchant’s decisive action shows that the kingdom requires wholehearted commitment. The point is not purchasing salvation with money but recognizing the kingdom’s supreme worth.", refs: ["Luke 14:28–33","Ephesians 2:8–10"] },
  "Matthew 13:49": { title: "The Net Cast into the Sea", text: "The kingdom is like a net gathering fish of every kind. The image anticipates a final separation among those gathered in the present age.", refs: ["Matthew 22:10","Luke 5:4–7"] },
  "Matthew 13:50": { title: "The Net Is Drawn to Shore", text: "When the net is full, the fish are brought ashore and sorted. The parable teaches that gathering now does not mean every person will receive the same final outcome.", refs: ["Matthew 25:31–32"] },
  "Matthew 13:51": { title: "The Good Are Gathered", text: "The good fish are gathered into vessels. The image points to preservation and blessing for those who belong to God’s kingdom.", refs: ["Matthew 25:34","John 5:29"] },
  "Matthew 13:52": { title: "The Bad Are Cast Away", text: "The bad fish are cast away, illustrating the coming separation of the wicked from the righteous. Jesus calls hearers to respond before the final judgment.", refs: ["Matthew 13:49–50","John 5:29"] },
  "Matthew 13:53": { title: "The End of the Age", text: "Jesus explains that at the end of the age angels will separate the wicked from among the just. Final judgment belongs to God and will be righteous.", refs: ["Matthew 25:31–32","Revelation 20:11–15"] },
  "Matthew 13:54": { title: "The Wicked Are Cast into the Furnace", text: "The passage warns that the wicked face judgment and anguish. Jesus’ warning should be taken seriously as a call to repentance and faithful living.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:55": { title: "The Disciples Understand", text: "Jesus asks whether the disciples understand these things, and they answer yes. Understanding the kingdom’s teaching brings responsibility to live by it.", refs: ["James 1:22","Matthew 7:24"] },
  "Matthew 13:56": { title: "A Scribe Trained for the Kingdom", text: "Jesus compares a scribe instructed in the kingdom to a householder who brings out treasures new and old. A faithful teacher draws from Scripture while recognizing the new revelation of the kingdom in Jesus.", refs: ["Matthew 5:17","2 Timothy 3:16–17"] },
  "Matthew 13:57": { title: "Jesus Leaves That Place", text: "After teaching these parables, Jesus departs. The narrative moves from instruction to the response of people in His hometown.", refs: ["Mark 6:1"] },
  "Matthew 13:58": { title: "Jesus Teaches in His Hometown", text: "Jesus comes to His own country and teaches in the synagogue. The people are astonished, but familiarity soon becomes an obstacle to faith.", refs: ["Mark 6:2","Luke 4:16–22"] },
  "Matthew 13:59": { title: "Where Did He Get This Wisdom?", text: "The people wonder where Jesus received His wisdom and mighty works. Their question acknowledges His extraordinary teaching but turns toward doubt.", refs: ["John 7:15","Mark 6:2"] },
  "Matthew 13:60": { title: "Is This Not the Carpenter’s Son?", text: "The people identify Jesus by His family and ordinary background. Familiarity with His earthly circumstances leads them to underestimate His divine mission.", refs: ["Mark 6:3","John 1:10–11"] },
  "Matthew 13:61": { title: "His Family Is Known to Them", text: "The people name Jesus’ mother, brethren, and sisters, stumbling over what they think they know about Him. Their familiarity becomes a barrier to recognizing God’s work through Him.", refs: ["Mark 6:3","Galatians 4:4"] },
  "Matthew 13:62": { title: "A Prophet Without Honour", text: "Jesus says a prophet is not without honour except in his own country and house. Those closest to a messenger may fail to recognize the truth because of familiarity or prejudice.", refs: ["Luke 4:24","John 4:44"] },
  "Matthew 13:63": { title: "Their Unbelief Limits the Works Seen", text: "Jesus does not many mighty works there because of their unbelief, though He heals a few sick people. The passage emphasizes their resistance, not a lack of power in Jesus.", refs: ["Mark 6:5–6","Hebrews 3:12"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 13:1": { title: "The Sower Goes Out", text: "Jesus begins a parable about a sower scattering seed. The seed encounters different conditions, illustrating varied responses to God’s word.", refs: ["Mark 4:1–9","Luke 8:4–8"] },
  "Matthew 13:2": { title: "Jesus Teaches from a Ship", text: "A great multitude gathers, so Jesus enters a ship while the people stand on the shore. He teaches through parables that invite hearers to examine their hearts.", refs: ["Mark 4:1–2"] },
  "Matthew 13:3": { title: "Seed by the Wayside", text: "Some seed falls by the wayside, where birds devour it. The image shows how the word may be heard without taking root.", refs: ["Luke 8:5, 12"] },
  "Matthew 13:4": { title: "Seed on Stony Ground", text: "Some seed falls on shallow, stony ground and springs up quickly because the soil is thin. Initial enthusiasm without depth cannot endure hardship.", refs: ["Mark 4:5–6","Luke 8:6"] },
  "Matthew 13:5": { title: "Seed among Thorns", text: "Some seed falls among thorns, which grow up and choke it. Competing desires can prevent God’s word from bearing fruit.", refs: ["Luke 8:7, 14"] },
  "Matthew 13:6": { title: "Seed on Good Ground", text: "Other seed falls on good ground and produces a harvest. The parable emphasizes receptive hearts that hear and respond fruitfully.", refs: ["Luke 8:8, 15"] },
  "Matthew 13:7": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls listeners to pay close attention. Hearing the story is not enough; they must receive its spiritual meaning.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:8": { title: "The Disciples Ask About Parables", text: "The disciples ask why Jesus speaks to the multitude in parables. Jesus explains that understanding is granted to receptive disciples, while others remain unmoved.", refs: ["Mark 4:10–12"] },
  "Matthew 13:9": { title: "Knowledge of the Kingdom Is Given", text: "Jesus tells His disciples they are given to know the mysteries of the kingdom. This knowledge is a gift and brings responsibility to respond faithfully.", refs: ["1 Corinthians 2:10–12","Ephesians 1:9"] },
  "Matthew 13:10": { title: "More Is Given to the Receptive", text: "Those who receive and use the truth they have will be given more understanding; those who reject it lose even what they think they have. The principle concerns spiritual responsiveness.", refs: ["Luke 8:18","Mark 4:24–25"] },
  "Matthew 13:11": { title: "Seeing Without Perceiving", text: "Some see Jesus’ works and hear His teaching without truly perceiving their meaning. Spiritual blindness is not merely a lack of information.", refs: ["Isaiah 6:9–10","John 12:40"] },
  "Matthew 13:12": { title: "The Heart Has Grown Dull", text: "Jesus quotes Isaiah about people whose hearts are dull and whose ears are slow to hear. Persistent refusal can harden a person against truth.", refs: ["Isaiah 6:10","Acts 28:26–27"] },
  "Matthew 13:13": { title: "Turning and Being Healed", text: "The prophecy speaks of people who might turn and be healed. God’s truth calls for repentance and restoration, but the hearer must not harden the heart against it.", refs: ["Isaiah 6:10","James 5:19–20"] },
  "Matthew 13:14": { title: "Blessed Are Your Eyes", text: "Jesus tells the disciples their eyes are blessed because they see what prophets and righteous people longed to see. They witness the Messiah’s ministry and the kingdom’s arrival.", refs: ["Luke 10:23–24","Hebrews 11:13"] },
  "Matthew 13:15": { title: "Prophets Desired to See This Day", text: "The prophets and righteous people desired to see and hear what the disciples experience. Their privilege calls for gratitude and faithful response.", refs: ["1 Peter 1:10–12","Hebrews 11:39–40"] },
  "Matthew 13:16": { title: "The Sower Parable Explained", text: "Jesus explains that the seed is the word of the kingdom. The wayside hearer does not understand, and the evil one takes away what was sown in the heart.", refs: ["Luke 8:11–12","Mark 4:14–15"] },
  "Matthew 13:17": { title: "The Stony-Ground Hearer", text: "The stony-ground hearer receives the word quickly and joyfully but has no root. When tribulation or persecution comes because of the word, the person falls away.", refs: ["Mark 4:16–17","James 1:2–4"] },
  "Matthew 13:18": { title: "The Thorny-Ground Hearer", text: "The thorny-ground hearer hears the word, but worldly care and the deceitfulness of riches choke it. A crowded heart cannot produce mature spiritual fruit.", refs: ["Luke 8:14","1 Timothy 6:9–10"] },
  "Matthew 13:19": { title: "The Good-Ground Hearer", text: "The good-ground hearer understands and bears fruit, some thirtyfold, some sixtyfold, and some an hundredfold. Fruitfulness varies, but genuine reception produces a harvest.", refs: ["Luke 8:15","John 15:5"] },
  "Matthew 13:20": { title: "The Wheat and Tares", text: "Jesus compares the kingdom to a man who sows good seed in his field. This parable considers the coexistence of faithful and wicked people until the harvest.", refs: ["Matthew 13:36–43"] },
  "Matthew 13:21": { title: "The Enemy Sows Tares", text: "An enemy sows tares among the wheat while people sleep. The parable portrays opposition to God’s work, even when evil is not immediately obvious.", refs: ["Matthew 13:38–39","2 Corinthians 11:13–15"] },
  "Matthew 13:22": { title: "Both Grow Together", text: "When the plants appear, the tares also become visible. The coexistence of good and evil creates the question of how servants should respond.", refs: ["Matthew 13:27–28"] },
  "Matthew 13:23": { title: "The Servants Ask About the Weeds", text: "The servants ask whether they should pull out the tares. Their question represents the desire to remove evil immediately, but Jesus will warn of the danger of harming the wheat.", refs: ["Matthew 13:28–29"] },
  "Matthew 13:24": { title: "The Enemy Has Done This", text: "The householder identifies an enemy as the source of the tares. Jesus recognizes opposition to the kingdom while directing His servants away from rash judgment.", refs: ["Matthew 13:39","John 8:44"] },
  "Matthew 13:25": { title: "Let Both Grow Until Harvest", text: "The householder says to let both grow until harvest, lest pulling up tares damage the wheat. Final separation belongs to God’s appointed judgment, not human vengeance.", refs: ["Matthew 13:30","Romans 12:19"] },
  "Matthew 13:26": { title: "The Mustard Seed", text: "Jesus compares the kingdom to a mustard seed that is very small when sown but grows into a large plant. God’s kingdom may begin in an unimpressive way yet grow greatly.", refs: ["Mark 4:30–32","Luke 13:18–19"] },
  "Matthew 13:27": { title: "The Leaven", text: "Jesus compares the kingdom to leaven hidden in flour until all is leavened. The image emphasizes a pervasive influence working through the whole measure.", refs: ["Luke 13:20–21","1 Corinthians 5:6"] },
  "Matthew 13:28": { title: "Jesus Teaches in Parables", text: "Jesus speaks to the multitude in parables, fulfilling the prophetic pattern of revealing truth through figures. His teaching calls hearers to seek and understand.", refs: ["Psalm 78:2","Mark 4:33–34"] },
  "Matthew 13:29": { title: "The Prophetic Use of Parables", text: "Matthew connects Jesus’ parables with the prophetic Scriptures. The kingdom’s truth is communicated in a form that calls hearers to attentive understanding.", refs: ["Psalm 78:2","Romans 15:4"] },
  "Matthew 13:30": { title: "Jesus Sends the Crowd Away", text: "Jesus sends the multitude away and enters the house. The disciples then ask for a fuller explanation of the tares parable.", refs: ["Matthew 13:36"] },
  "Matthew 13:31": { title: "Explain the Tares", text: "The disciples ask Jesus to explain the parable of the tares. Their request models seeking understanding rather than pretending to know.", refs: ["Proverbs 2:3–5","James 1:5"] },
  "Matthew 13:32": { title: "The Sower of Good Seed", text: "Jesus identifies the sower of good seed as the Son of man. The parable centers on His authority and kingdom work.", refs: ["Matthew 8:20","Matthew 16:13"] },
  "Matthew 13:33": { title: "The Field Is the World", text: "Jesus identifies the field as the world. The parable’s scope reaches beyond a local congregation to the world in which God’s people live.", refs: ["Matthew 28:19","John 3:16"] },
  "Matthew 13:34": { title: "The Good Seed", text: "The good seed represents the children of the kingdom. Their identity should be seen in relation to God’s reign and the fruit of faithful living.", refs: ["Matthew 5:14–16","Romans 8:14"] },
  "Matthew 13:35": { title: "The Tares", text: "The tares represent the children of the wicked one. The image concerns spiritual allegiance and final judgment, not permission to label disliked people as enemies.", refs: ["John 8:44","1 John 3:10"] },
  "Matthew 13:36": { title: "The Enemy Is the Devil", text: "Jesus identifies the enemy who sows tares as the devil. Scripture presents evil as opposing God’s work, while affirming that God will finally judge it.", refs: ["Genesis 3:1–15","1 Peter 5:8"] },
  "Matthew 13:37": { title: "The Harvest Is the End of the Age", text: "The harvest represents the end of the age, when the present mixture will be brought to judgment. The parable directs hope toward God’s final justice.", refs: ["Matthew 24:3","Revelation 14:14–16"] },
  "Matthew 13:38": { title: "The Reapers Are Angels", text: "Jesus identifies the reapers as angels. The final separation is assigned to God’s agents, not to human attempts at violent purification.", refs: ["Matthew 24:31","Hebrews 1:14"] },
  "Matthew 13:39": { title: "The Tares Are Gathered for Burning", text: "As tares are gathered and burned, so evil will face judgment at the end of the age. The image warns against continuing in lawlessness.", refs: ["Matthew 13:40–42","Revelation 20:11–15"] },
  "Matthew 13:40": { title: "The Son of Man Sends His Angels", text: "Jesus describes the Son of man sending angels to gather out of His kingdom those who cause sin and practice lawlessness. The passage portrays the Messiah’s authority in final judgment.", refs: ["Matthew 24:30–31","2 Thessalonians 1:7–9"] },
  "Matthew 13:41": { title: "A Furnace of Fire", text: "The image of a furnace of fire conveys the severity of final judgment and the anguish of those rejected. Jesus calls hearers to take righteousness and repentance seriously.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:42": { title: "The Righteous Shine Forth", text: "The righteous shine as the sun in their Father’s kingdom. After judgment, God’s people share in the glory of His righteous reign.", refs: ["Daniel 12:3","Philippians 2:15"] },
  "Matthew 13:43": { title: "He That Has Ears, Let Him Hear", text: "Jesus calls for careful hearing. The teaching about judgment is meant to awaken faithful response, not mere curiosity about the future.", refs: ["Mark 4:9","Revelation 2:7"] },
  "Matthew 13:44": { title: "Treasure Hidden in a Field", text: "The kingdom is like treasure hidden in a field, which a man finds and joyfully sells all he has to buy the field. The parable stresses the kingdom’s surpassing worth.", refs: ["Philippians 3:7–8","Matthew 19:21"] },
  "Matthew 13:45": { title: "The Pearl of Great Price", text: "A merchant seeking fine pearls finds one of great value and sells all to obtain it. The kingdom is worth more than any competing possession or ambition.", refs: ["Proverbs 3:13–15","Philippians 3:8"] },
  "Matthew 13:46": { title: "The Net Cast into the Sea", text: "The kingdom is like a net gathering fish of every kind. The image anticipates a final separation among those gathered in the present age.", refs: ["Matthew 22:10","Luke 5:4–7"] },
  "Matthew 13:47": { title: "The Net Is Drawn to Shore", text: "When the net is full, it is brought ashore and the fish are sorted. The parable teaches that gathering now does not mean every person will receive the same final outcome.", refs: ["Matthew 25:31–32"] },
  "Matthew 13:48": { title: "The Good Fish Are Gathered", text: "The good fish are gathered into vessels. The image points to preservation and blessing for those who belong to God’s kingdom.", refs: ["Matthew 25:34","John 5:29"] },
  "Matthew 13:49": { title: "The Bad Fish Are Cast Away", text: "The bad fish are cast away, illustrating the coming separation of the wicked from the righteous. Jesus calls hearers to respond before the final judgment.", refs: ["Matthew 13:49–50","John 5:29"] },
  "Matthew 13:50": { title: "The End of the Age", text: "At the end of the age, angels will separate the wicked from among the just. Final judgment belongs to God and will be righteous.", refs: ["Matthew 25:31–32","Revelation 20:11–15"] },
  "Matthew 13:51": { title: "The Wicked Face Judgment", text: "The passage warns that the wicked face judgment and anguish. Jesus’ warning is a call to repentance and faithful living.", refs: ["Matthew 13:42","Revelation 20:15"] },
  "Matthew 13:52": { title: "Do the Disciples Understand?", text: "Jesus asks whether the disciples understand these things, and they answer yes. Understanding the kingdom’s teaching brings responsibility to live by it.", refs: ["James 1:22","Matthew 7:24"] },
  "Matthew 13:53": { title: "A Scribe Trained for the Kingdom", text: "Jesus compares a scribe instructed in the kingdom to a householder who brings out treasures new and old. A faithful teacher draws from Scripture while recognizing God’s work revealed in Jesus.", refs: ["Matthew 5:17","2 Timothy 3:16–17"] },
  "Matthew 13:54": { title: "Jesus Leaves That Place", text: "After teaching these parables, Jesus departs. The narrative moves from instruction to the response of people in His hometown.", refs: ["Mark 6:1"] },
  "Matthew 13:55": { title: "Jesus Teaches in His Hometown", text: "Jesus comes to His own country and teaches in the synagogue. The people are astonished, but familiarity soon becomes an obstacle to faith.", refs: ["Mark 6:2","Luke 4:16–22"] },
  "Matthew 13:56": { title: "Where Did He Get This Wisdom?", text: "The people wonder where Jesus received His wisdom and mighty works. Their question acknowledges His extraordinary teaching but turns toward doubt.", refs: ["John 7:15","Mark 6:2"] },
  "Matthew 13:57": { title: "Is This Not the Carpenter’s Son?", text: "The people identify Jesus by His family and ordinary background. Familiarity with His earthly circumstances leads them to underestimate His divine mission.", refs: ["Mark 6:3","John 1:10–11"] },
  "Matthew 13:58": { title: "His Family Is Known to Them", text: "The people name Jesus’ mother, brethren, and sisters, stumbling over what they think they know about Him. Their familiarity becomes a barrier to recognizing God’s work through Him.", refs: ["Mark 6:3","Galatians 4:4"] },
  "Matthew 13:59": { title: "A Prophet Without Honour", text: "Jesus says a prophet is not without honour except in his own country and house. Those closest to a messenger may fail to recognize the truth because of familiarity or prejudice.", refs: ["Luke 4:24","John 4:44"] },
  "Matthew 13:60": { title: "Unbelief in Nazareth", text: "Jesus does not many mighty works there because of their unbelief, though He heals a few sick people. The passage emphasizes their resistance, not a lack of power in Jesus.", refs: ["Mark 6:5–6","Hebrews 3:12"] }
});
delete window.verseCommentary["Matthew 13:59"];
delete window.verseCommentary["Matthew 13:60"];
delete window.verseCommentary["Matthew 13:61"];
delete window.verseCommentary["Matthew 13:62"];
delete window.verseCommentary["Matthew 13:63"];

Object.assign(window.verseCommentary, {
  "Matthew 14:1": { title: "Herod Hears of Jesus", text: "Herod the tetrarch hears reports about Jesus and becomes troubled by what people are saying. The account shows that Jesus’ ministry had become widely known.", refs: ["Matthew 4:24","Luke 9:7–9"] },
  "Matthew 14:2": { title: "Herod’s Fearful Conclusion", text: "Herod supposes that John the Baptist has risen from the dead and that miraculous power is working in him. His conclusion reflects guilt and fear after John’s execution.", refs: ["Matthew 16:14","Mark 6:14–16"] },
  "Matthew 14:3": { title: "John Imprisoned", text: "Matthew explains that Herod had arrested John because of Herodias, his unlawful relationship with his brother Philip’s wife. John’s imprisonment followed his bold witness to righteousness.", refs: ["Matthew 11:2","Mark 6:17–18"] },
  "Matthew 14:4": { title: "John Rebukes Herod", text: "John plainly tells Herod that his relationship with Herodias is unlawful. A servant of God must not change the truth merely to please a ruler.", refs: ["Leviticus 18:16","Leviticus 20:21","Ephesians 5:11"] },
  "Matthew 14:5": { title: "Herod Fears the People", text: "Herod wants John dead but fears the crowd, which regards John as a prophet. Political pressure restrains him for a time, but it does not produce repentance.", refs: ["Matthew 21:26","Mark 6:20"] },
  "Matthew 14:6": { title: "A Birthday Celebration", text: "At Herod’s birthday celebration, Herodias’s daughter dances before the guests. The setting prepares for a rash promise that will lead to a righteous man’s death.", refs: ["Mark 6:21–22","Proverbs 29:11"] },
  "Matthew 14:7": { title: "A Rash Oath", text: "Herod promises with an oath to give the girl whatever she asks. Scripture warns against careless speech and vows made without wisdom.", refs: ["Ecclesiastes 5:2","Matthew 5:33–37"] },
  "Matthew 14:8": { title: "Herodias’s Request", text: "Prompted by her mother, the girl asks for John’s head on a platter. The demand reveals Herodias’s hostility toward the prophet who exposed her sin.", refs: ["Mark 6:24–25","1 Kings 19:2"] },
  "Matthew 14:9": { title: "Herod’s Sorrow", text: "Herod is sorry, yet his concern for his oath and his guests outweighs the right course of action. Sorrow that refuses to obey truth cannot undo wrongdoing.", refs: ["Mark 6:26","2 Corinthians 7:10"] },
  "Matthew 14:10": { title: "John Is Beheaded", text: "Herod orders John’s execution in prison. John’s death shows the cost of faithful witness in a sinful and powerful world, not the failure of God’s word.", refs: ["Matthew 11:11","Revelation 6:9–11"] },
  "Matthew 14:11": { title: "John’s Head Is Delivered", text: "John’s head is brought on a platter and given to the girl, who carries it to her mother. The grim account exposes the cruelty that can follow pride, resentment, and reckless promises.", refs: ["Mark 6:27–28","Proverbs 27:4"] },
  "Matthew 14:12": { title: "John’s Disciples Bury Him", text: "John’s disciples take his body, bury it, and tell Jesus. They honor their teacher, and their report connects John’s death with Jesus’ continuing ministry.", refs: ["Matthew 11:2–6","Mark 6:29"] },
  "Matthew 14:13": { title: "Jesus Withdraws to a Desert Place", text: "Jesus withdraws by boat to a solitary place after hearing the news. When the crowds follow, He does not turn them away; His compassion directs what happens next.", refs: ["Matthew 9:36","Mark 6:31–32"] },
  "Matthew 14:14": { title: "Jesus Has Compassion", text: "Jesus sees the great multitude, is moved with compassion, and heals their sick. His authority is joined with mercy; God’s work through Jesus brings help to people in need.", refs: ["Matthew 9:35–36","Isaiah 35:5–6"] },
  "Matthew 14:15": { title: "The Disciples See the Need", text: "As evening comes, the disciples ask Jesus to send the crowd away to buy food. They recognize the practical problem but have not yet grasped what Jesus will provide.", refs: ["Mark 6:35–36","John 6:5–6"] },
  "Matthew 14:16": { title: "Give Them to Eat", text: "Jesus tells the disciples that the people need not depart and commands them to give the crowd food. The command invites them to bring their limited resources under His direction.", refs: ["2 Kings 4:42–44","John 6:8–11"] },
  "Matthew 14:17": { title: "Five Loaves and Two Fishes", text: "The disciples report that they have only five loaves and two fish. Their small supply emphasizes that the coming provision will be the work of Jesus, not human abundance.", refs: ["Matthew 16:9","John 6:9"] },
  "Matthew 14:18": { title: "Bring the Food to Jesus", text: "Jesus tells them to bring the food to Him. In ministry, what seems insufficient can still be placed in the Lord’s hands and used according to His purpose.", refs: ["Matthew 14:19","2 Corinthians 12:9"] },
  "Matthew 14:19": { title: "Jesus Blesses and Breaks the Loaves", text: "Jesus seats the people, takes the loaves and fish, looks to heaven, blesses, breaks, and gives the food to the disciples to distribute. The miracle displays divine provision through Jesus and thankful dependence upon God.", refs: ["Matthew 15:36","John 6:11"] },
  "Matthew 14:20": { title: "All Are Filled", text: "Everyone eats and is satisfied, and the disciples gather twelve baskets of leftovers. The abundance shows that Jesus’ provision fully meets the need rather than barely supplying it.", refs: ["2 Kings 4:43–44","John 6:12–13"] },
  "Matthew 14:21": { title: "Five Thousand Men Fed", text: "About five thousand men eat, besides women and children. The crowd’s size underlines the scale of the miracle and the sufficiency of Jesus’ provision.", refs: ["Matthew 16:9–10","Mark 6:44"] },
  "Matthew 14:22": { title: "Jesus Sends the Disciples Ahead", text: "Jesus directs the disciples to cross the sea while He dismisses the crowd. His actions are deliberate: He remains in control even as the disciples face a difficult crossing.", refs: ["Mark 6:45–46","John 6:15–17"] },
  "Matthew 14:23": { title: "Jesus Prays Alone", text: "Jesus goes up a mountain by Himself to pray. His solitary prayer shows His genuine human life and dependence in prayer; it does not require the conclusion that He is a second God.", refs: ["Luke 5:16","John 17:1–5"] },
  "Matthew 14:24": { title: "The Boat Is Tossed by Waves", text: "The boat is far from land and battered by contrary wind. The disciples are in real danger, but the storm does not place them beyond Jesus’ reach.", refs: ["Mark 6:47–48","Psalm 107:23–30"] },
  "Matthew 14:25": { title: "Jesus Walks on the Sea", text: "In the fourth watch of the night, Jesus comes to the disciples walking on the sea. The act displays authority over creation, a power Scripture associates with the Lord.", refs: ["Job 9:8","Psalm 77:19","John 6:19"] },
  "Matthew 14:26": { title: "The Disciples Are Afraid", text: "The disciples mistake Jesus for a spirit and cry out in fear. Their reaction is understandable in the darkness and storm, but they do not yet recognize the One approaching them.", refs: ["Mark 6:49–50","Luke 24:37"] },
  "Matthew 14:27": { title: "Be of Good Cheer", text: "Jesus immediately tells them to be of good courage, identifies Himself, and commands them not to fear. His presence answers their terror before the storm has passed.", refs: ["Isaiah 41:10","John 6:20"] },
  "Matthew 14:28": { title: "Peter Asks to Come", text: "Peter asks Jesus to command him to come across the water. He looks to Jesus for the word that would make the impossible step possible.", refs: ["Matthew 14:29","John 21:7"] },
  "Matthew 14:29": { title: "Peter Walks on the Water", text: "At Jesus’ command, Peter leaves the boat and walks on the water toward Him. His action is possible only because Jesus calls him; courage is not independence from the Lord.", refs: ["Matthew 14:28","Hebrews 11:29"] },
  "Matthew 14:30": { title: "Peter Begins to Sink", text: "Seeing the wind, Peter becomes afraid and begins to sink, crying for the Lord to save him. The scene shows how fear can overwhelm faith and how prayer turns urgently to Jesus.", refs: ["Psalm 69:1–2","Matthew 8:25"] },
  "Matthew 14:31": { title: "Jesus Immediately Helps Peter", text: "Jesus catches Peter and rebukes his little faith and doubt. The Lord both rescues and teaches him, revealing compassion without pretending that doubt is harmless.", refs: ["Matthew 6:30","Jude 22"] },
  "Matthew 14:32": { title: "The Wind Ceases", text: "When Jesus and Peter enter the boat, the wind stops. The sudden calm confirms Jesus’ authority over the forces threatening the disciples.", refs: ["Psalm 89:9","Mark 4:39"] },
  "Matthew 14:33": { title: "The Disciples Worship Jesus", text: "Those in the boat worship Jesus and confess that He truly is the Son of God. Matthew presents worship and confession in response to the authority Jesus has displayed.", refs: ["Matthew 16:16","John 20:28–31"] },
  "Matthew 14:34": { title: "They Reach Gennesaret", text: "The boat reaches the land of Gennesaret. The narrative moves from danger at sea to a region where people will seek Jesus for healing.", refs: ["Mark 6:53","John 6:21"] },
  "Matthew 14:35": { title: "The People Bring the Sick", text: "The people recognize Jesus and spread the news throughout the surrounding area, bringing all who are sick to Him. His ministry is marked by public compassion and healing.", refs: ["Matthew 4:24","Matthew 9:35"] },
  "Matthew 14:36": { title: "Those Who Touch His Garment Are Healed", text: "The sick beg merely to touch the hem of Jesus’ garment, and those who touch it are made whole. Their faith looks to Jesus as the source of healing, not to the garment as an independent power.", refs: ["Matthew 9:20–22","Mark 6:56"] },

  "Matthew 15:1": { title: "Religious Leaders Question Jesus", text: "Scribes and Pharisees from Jerusalem ask Jesus why His disciples do not follow the elders’ tradition concerning handwashing. The dispute concerns human tradition, not a commandment given by God in the law.", refs: ["Mark 7:1–5","Colossians 2:8"] },
  "Matthew 15:2": { title: "Tradition of the Elders", text: "The leaders accuse the disciples of eating with unwashed hands according to their ceremonial tradition. The issue is not ordinary hygiene but treating an inherited rule as a religious obligation.", refs: ["Mark 7:3–4","Isaiah 29:13"] },
  "Matthew 15:3": { title: "Jesus Exposes Their Tradition", text: "Jesus asks why they transgress God’s commandment by their tradition. Human customs must be tested against God’s word rather than allowed to displace it.", refs: ["Deuteronomy 4:2","Mark 7:8–9"] },
  "Matthew 15:4": { title: "Honor Father and Mother", text: "Jesus recalls God’s command to honor parents and the serious penalty attached to cursing them. He establishes God’s command as the standard by which religious practice must be judged.", refs: ["Exodus 20:12","Exodus 21:17","Ephesians 6:2"] },
  "Matthew 15:5": { title: "A Tradition That Evades Duty", text: "The leaders allow a person to claim that support owed to parents has been dedicated as a gift to God. Their rule can excuse a person from the very responsibility God commanded.", refs: ["Mark 7:11–12","1 Timothy 5:4"] },
  "Matthew 15:6": { title: "God’s Word Made Void", text: "By their tradition, they make God’s command ineffective in practice. Religious sincerity does not justify a rule that contradicts the clear duty taught by Scripture.", refs: ["Matthew 23:23","Titus 1:14"] },
  "Matthew 15:7": { title: "Hypocrisy Exposed", text: "Jesus calls the leaders hypocrites and introduces Isaiah’s rebuke. Outward religious appearance cannot conceal a heart that resists God’s authority.", refs: ["Isaiah 29:13","Matthew 23:27–28"] },
  "Matthew 15:8": { title: "Lips Near, Heart Far", text: "The people honor God with their lips while their heart remains far from Him. True worship requires inward devotion and obedience, not words alone.", refs: ["Isaiah 29:13","Ezekiel 33:31"] },
  "Matthew 15:9": { title: "Vain Worship by Human Commandments", text: "Jesus says worship becomes vain when human commandments are taught as doctrines. Scripture must govern teaching; tradition cannot claim God’s authority merely because it is old.", refs: ["Mark 7:7","Colossians 2:20–23"] },
  "Matthew 15:10": { title: "Jesus Calls the Crowd", text: "Jesus calls the multitude to hear and understand. He brings the issue beyond a private dispute and teaches a principle that concerns everyone’s spiritual life.", refs: ["Mark 7:14","Proverbs 2:2"] },
  "Matthew 15:11": { title: "What Defiles a Person", text: "Jesus teaches that what enters the mouth does not by itself defile the person; what comes out of the mouth reveals the heart. He is confronting the defilement issue under discussion, not declaring that evil speech and conduct are unimportant.", refs: ["Matthew 12:34–37","Mark 7:18–23"] },
  "Matthew 15:12": { title: "The Pharisees Are Offended", text: "The disciples report that the Pharisees were offended by Jesus’ words. Offense from those whose traditions are challenged does not prove that the teaching is false.", refs: ["Galatians 4:16","John 6:60–61"] },
  "Matthew 15:13": { title: "Every Plant Not Planted by the Father", text: "Jesus says every plant not planted by His heavenly Father will be rooted up. A religious system lacking God’s approval cannot endure merely because influential people defend it.", refs: ["Isaiah 60:21","John 15:1–2"] },
  "Matthew 15:14": { title: "Blind Guides", text: "Jesus describes the leaders as blind guides: both guide and follower may fall into a ditch. Spiritual leadership requires truth and discernment, not merely status or confidence.", refs: ["Luke 6:39","Romans 2:19–21"] },
  "Matthew 15:15": { title: "Peter Asks for an Explanation", text: "Peter asks Jesus to explain the parable. The disciples do not understand everything immediately, and the passage encourages seeking clarification rather than pretending to understand.", refs: ["Mark 7:17","James 1:5"] },
  "Matthew 15:16": { title: "Understanding Still Lacking", text: "Jesus asks whether the disciples also lack understanding. Being close to Jesus does not remove the need to listen carefully and learn His teaching.", refs: ["Matthew 16:9","John 14:26"] },
  "Matthew 15:17": { title: "The Path of Food", text: "Jesus describes food entering the mouth and passing through the body. This ordinary process helps distinguish physical food from the moral source of defilement.", refs: ["Mark 7:18–19","1 Corinthians 6:13"] },
  "Matthew 15:18": { title: "The Heart Produces Words", text: "Words that come from the mouth proceed from the heart, and these defile the person. Speech can expose inner motives and moral condition.", refs: ["Proverbs 4:23","Luke 6:45"] },
  "Matthew 15:19": { title: "Evil Proceeds from Within", text: "Jesus lists evil thoughts, murders, adultery, sexual immorality, theft, false witness, and blasphemy as coming from the heart. The answer to sin must address the inward person, not only outward ritual.", refs: ["Jeremiah 17:9","Galatians 5:19–21"] },
  "Matthew 15:20": { title: "Defilement and Unwashed Hands", text: "Jesus summarizes that these evils defile a person, while eating with unwashed hands does not make one morally unclean in the way the leaders alleged. He is correcting their misplaced priority, not dismissing holiness.", refs: ["Mark 7:20–23","Psalm 24:3–4"] },
  "Matthew 15:21": { title: "Jesus Goes to the Coasts of Tyre and Sidon", text: "Jesus withdraws into the region of Tyre and Sidon. The following encounter shows faith reaching toward Him beyond the immediate Jewish setting of His ministry.", refs: ["Mark 7:24","Isaiah 42:6"] },
  "Matthew 15:22": { title: "A Canaanite Woman Cries for Mercy", text: "A Canaanite woman calls Jesus the Son of David and pleads for her demon-oppressed daughter. She recognizes His messianic identity and appeals to His mercy.", refs: ["Matthew 9:27","Matthew 20:30–31"] },
  "Matthew 15:23": { title: "The Disciples Ask Jesus to Send Her Away", text: "Jesus initially gives no answer, and the disciples urge Him to send the woman away because she keeps crying after them. The tension in the scene prepares for a deeper revelation of persistent faith.", refs: ["Matthew 15:24–28","Luke 18:1–8"] },
  "Matthew 15:24": { title: "Jesus Describes His Mission to Israel", text: "Jesus says He was sent to the lost sheep of the house of Israel, reflecting the covenant order of His earthly ministry. The wider New Testament later shows the gospel going to all nations.", refs: ["Matthew 10:5–6","Romans 1:16","Acts 1:8"] },
  "Matthew 15:25": { title: "The Woman Worships and Pleads", text: "The woman comes nearer, worships Jesus, and asks Him to help her. Her persistence is joined with humility and confidence in His ability to deliver her daughter.", refs: ["Matthew 8:2","Hebrews 11:6"] },
  "Matthew 15:26": { title: "The Children’s Bread", text: "Jesus uses the image of children’s bread and little dogs to express the priority of His mission to Israel. The exchange tests and brings to light the woman’s understanding and faith.", refs: ["Mark 7:27","Romans 9:4–5"] },
  "Matthew 15:27": { title: "Even the Dogs Eat the Crumbs", text: "The woman accepts the image but points out that even little dogs eat crumbs from their masters’ table. She does not demand status; she trusts that even a portion of Jesus’ mercy is sufficient.", refs: ["Luke 7:6–9","Ephesians 2:12–13"] },
  "Matthew 15:28": { title: "Great Faith and Healing", text: "Jesus commends the woman’s great faith and grants her request; her daughter is healed that very hour. The passage shows that faith in Jesus’ mercy crosses social boundaries.", refs: ["Matthew 8:10–13","Galatians 3:28–29"] },
  "Matthew 15:29": { title: "Jesus Returns to the Sea of Galilee", text: "Jesus comes near the Sea of Galilee and sits on a mountain. The setting leads to another scene of healing and provision for the gathered people.", refs: ["Mark 7:31","Matthew 14:23"] },
  "Matthew 15:30": { title: "Many Are Healed", text: "Great multitudes bring people with varied disabilities and illnesses and lay them at Jesus’ feet, and He heals them. His compassion reaches people whose conditions had limited their lives.", refs: ["Isaiah 35:5–6","Matthew 11:4–5"] },
  "Matthew 15:31": { title: "The Multitude Glorifies the God of Israel", text: "The people see the healed speaking, walking, and made whole, and they glorify the God of Israel. Jesus’ works lead observers to praise God, showing God’s saving power active through Him.", refs: ["Matthew 9:8","Luke 7:16"] },
  "Matthew 15:32": { title: "Jesus Has Compassion on the Hungry Crowd", text: "Jesus says He has compassion on the multitude because they have stayed with Him three days and have no food. He is unwilling to send them away fainting, displaying practical care as well as spiritual teaching.", refs: ["Matthew 14:14–16","Mark 8:1–3"] },
  "Matthew 15:33": { title: "The Disciples See No Supply", text: "The disciples ask where enough bread could be found in the wilderness to feed so many. They focus on the scarcity around them, despite having already witnessed Jesus multiply food.", refs: ["Matthew 14:17","Matthew 16:9–10"] },
  "Matthew 15:34": { title: "Seven Loaves and a Few Small Fish", text: "Jesus asks what food they have, and they report seven loaves and a few small fish. As before, the miracle begins with an honest accounting of what is available.", refs: ["Matthew 14:17–18","Mark 8:5–7"] },
  "Matthew 15:35": { title: "The People Sit Down", text: "Jesus commands the multitude to sit on the ground. The ordered setting prepares for the distribution and shows that the meal is provided deliberately, not through confusion.", refs: ["Matthew 14:19","Mark 8:6"] },
  "Matthew 15:36": { title: "Jesus Gives Thanks and Breaks the Food", text: "Jesus takes the seven loaves and fish, gives thanks, breaks them, and gives them to His disciples. Thanksgiving precedes distribution, and the disciples serve as instruments through whom the crowd receives provision.", refs: ["Matthew 14:19","1 Timothy 4:4–5"] },
  "Matthew 15:37": { title: "Four Thousand Are Filled", text: "The people eat and are filled, and seven baskets of fragments remain. The abundance again demonstrates Jesus’ power to provide beyond the immediate need.", refs: ["Matthew 14:20","Mark 8:8"] },
  "Matthew 15:38": { title: "Four Thousand Men", text: "About four thousand men are counted, besides women and children. Matthew records the scale of the second feeding, distinct from the earlier feeding of the five thousand.", refs: ["Matthew 14:21","Mark 8:9"] },
  "Matthew 15:39": { title: "Jesus Departs by Ship", text: "After sending the multitude away, Jesus enters a ship and comes to the coasts of Magdala. The account closes the feeding episode and moves the narrative onward.", refs: ["Mark 8:10","Matthew 16:1"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 16:1": { title: "A Sign Demanded from Heaven", text: "The Pharisees and Sadducees test Jesus by demanding a sign from heaven. Their request is not honest inquiry; they have already seen works that testify to His authority.", refs: ["Matthew 12:38–40","Mark 8:11–12"] },
  "Matthew 16:2": { title: "Reading the Sky", text: "Jesus describes how people interpret the evening sky. Their ability to observe natural signs contrasts with their refusal to consider the spiritual significance of what God is doing.", refs: ["Luke 12:54–56","Jeremiah 8:7"] },
  "Matthew 16:3": { title: "Discerning the Times", text: "They can judge the weather but fail to discern the signs of their time. Religious knowledge is incomplete when it refuses to recognize God’s work before them.", refs: ["Matthew 11:4–6","Luke 19:44"] },
  "Matthew 16:4": { title: "The Sign of Jonah", text: "Jesus calls the generation wicked and adulterous and points to the sign of Jonah rather than satisfying their demand. Jonah’s experience foreshadows Jesus’ death and resurrection.", refs: ["Jonah 1:17","Matthew 12:39–40"] },
  "Matthew 16:5": { title: "The Disciples Forget Bread", text: "The disciples cross the sea and realize they have forgotten to bring bread. Their immediate concern sets up Jesus’ warning about a more dangerous kind of leaven.", refs: ["Mark 8:14","Matthew 15:34–36"] },
  "Matthew 16:6": { title: "Beware the Leaven", text: "Jesus warns them to beware the leaven of the Pharisees and Sadducees. The image points to the corrupting influence of their teaching and unbelief, not merely to physical bread.", refs: ["Luke 12:1","1 Corinthians 5:6–8"] },
  "Matthew 16:7": { title: "The Disciples Misunderstand", text: "The disciples assume Jesus is speaking because they brought no bread. They remain focused on the literal situation and miss the spiritual meaning of His warning.", refs: ["Matthew 15:16","Mark 8:17"] },
  "Matthew 16:8": { title: "Little Faith", text: "Jesus challenges their lack of faith and understanding. Their anxiety about bread overlooks the provision they have already witnessed.", refs: ["Matthew 6:30–32","Matthew 14:19–21"] },
  "Matthew 16:9": { title: "Remember the Five Thousand", text: "Jesus reminds them of the five loaves and the twelve baskets left over. Remembering God’s past provision should strengthen trust in present need.", refs: ["Matthew 14:17–21","Psalm 77:11–12"] },
  "Matthew 16:10": { title: "Remember the Four Thousand", text: "Jesus also recalls the seven loaves and seven baskets from the feeding of the four thousand. The repeated miracle should have taught the disciples that He is not limited by scarcity.", refs: ["Matthew 15:34–38","Mark 8:19–20"] },
  "Matthew 16:11": { title: "Understand the Warning", text: "Jesus clarifies that He was not warning them about literal bread but about the leaven of the Pharisees and Sadducees. Spiritual discernment requires hearing the intended meaning of His words.", refs: ["Matthew 16:6","Mark 8:21"] },
  "Matthew 16:12": { title: "The Doctrine of the Pharisees", text: "The disciples finally understand that Jesus means their doctrine. Teaching can spread through a community like leaven, so believers must examine it against God’s word.", refs: ["Acts 17:11","Colossians 2:8"] },
  "Matthew 16:13": { title: "Who Do People Say the Son of Man Is?", text: "Jesus asks His disciples who people say the Son of man is. The question moves from public opinion toward the personal confession that will define their understanding of Him.", refs: ["Daniel 7:13–14","Matthew 8:20"] },
  "Matthew 16:14": { title: "Many Opinions About Jesus", text: "The disciples report that some identify Jesus with John the Baptist, Elijah, Jeremiah, or another prophet. Respectful opinions are not enough; the decisive question is who Jesus truly is.", refs: ["Matthew 14:2","Malachi 4:5","Deuteronomy 18:15"] },
  "Matthew 16:15": { title: "Who Do You Say I Am?", text: "Jesus turns the question directly to the disciples. Faith cannot rest only on what others say; each hearer must respond to the truth revealed about Jesus.", refs: ["John 6:67–69","Romans 10:9–10"] },
  "Matthew 16:16": { title: "Peter Confesses the Christ", text: "Peter declares Jesus to be the Christ, the Son of the living God. This confession identifies Him as the promised Messiah and God's Son; the Gospel also teaches that the fullness of deity dwells bodily in Christ.", refs: ["John 20:31","Colossians 2:9","Matthew 1:23"] },
  "Matthew 16:17": { title: "Revelation from the Father", text: "Jesus says Peter did not arrive at this confession by human reasoning alone; the Father in heaven revealed it. True recognition of Jesus is a gift of divine revelation.", refs: ["Matthew 11:25–27","John 6:44–45"] },
  "Matthew 16:18": { title: "Christ Builds His Church", text: "Jesus declares that He will build His church upon this foundational confession, and the gates of hell will not prevail against it. The church belongs to Christ and rests on the truth of His identity, not on human power.", refs: ["1 Corinthians 3:11","Ephesians 2:20","Acts 2:41–42"] },
  "Matthew 16:19": { title: "The Keys of the Kingdom", text: "Jesus gives Peter the keys of the kingdom and speaks of binding and loosing. In the apostolic mission, the gospel announces the terms of entry into the kingdom; Acts records the apostles preaching repentance, baptism in Jesus’ name, and the gift of the Spirit.", refs: ["Matthew 18:18","Acts 2:38","Acts 10:44–48"] },
  "Matthew 16:20": { title: "Jesus Commands Silence for a Time", text: "Jesus charges the disciples not to announce yet that He is the Christ. His messianic mission must be understood in light of the cross and resurrection, not reduced to popular political expectations.", refs: ["Matthew 17:9","Mark 9:9"] },
  "Matthew 16:21": { title: "Jesus Foretells His Death and Resurrection", text: "Jesus begins to explain that He must go to Jerusalem, suffer, be killed, and rise again. The cross is not an accident but central to the saving mission He willingly fulfills.", refs: ["Isaiah 53:3–12","Luke 24:6–7"] },
  "Matthew 16:22": { title: "Peter Rebukes Jesus", text: "Peter objects that these things must not happen to Jesus. His affection is real, but he is thinking in human terms and resisting the very purpose Jesus has come to accomplish.", refs: ["John 12:27","Matthew 26:51–54"] },
  "Matthew 16:23": { title: "Get Behind Me, Satan", text: "Jesus sharply rebukes Peter because his words oppose God’s saving purpose. Peter is not literally identified as Satan; he has become an obstacle by thinking about glory without the cross.", refs: ["Isaiah 55:8–9","Matthew 4:8–10"] },
  "Matthew 16:24": { title: "Deny Yourself and Follow Jesus", text: "Jesus calls anyone who would follow Him to deny self, take up the cross, and follow. Discipleship means surrendering self-rule and remaining faithful even when obedience is costly.", refs: ["Luke 9:23","Galatians 2:20"] },
  "Matthew 16:25": { title: "Losing Life to Save It", text: "Whoever tries to save life at any cost will lose it, while whoever loses life for Jesus’ sake will find it. Faithfulness to Christ is worth more than preserving earthly security.", refs: ["John 12:25","Philippians 1:21"] },
  "Matthew 16:26": { title: "The Value of the Soul", text: "The whole world cannot compensate for the loss of one’s soul. Earthly gain is temporary, while a person’s standing before God has eternal significance.", refs: ["Psalm 49:7–8","Mark 8:36–37"] },
  "Matthew 16:27": { title: "The Son of Man Comes in Glory", text: "The Son of man will come in the glory of His Father with His angels and reward each according to works. Jesus speaks of divine judgment and the accountability of every person before Him.", refs: ["Daniel 7:13–14","Romans 2:6–8","Revelation 22:12"] },
  "Matthew 16:28": { title: "Some Will See the Kingdom Coming", text: "Jesus says some standing there will not taste death before seeing the Son of man coming in His kingdom. The next chapter’s transfiguration offers a foretaste of His majesty, while the saying has also been discussed in connection with the kingdom’s powerful arrival.", refs: ["Matthew 17:1–8","Mark 9:1","2 Peter 1:16–18"] },

  "Matthew 17:1": { title: "The Transfiguration", text: "Six days later Jesus takes Peter, James, and John up a high mountain. The private setting prepares these witnesses to see a revelation of Jesus’ glory.", refs: ["Mark 9:2","Luke 9:28"] },
  "Matthew 17:2": { title: "Jesus’ Face Shines", text: "Jesus is transfigured before them, His face shining like the sun and His clothes becoming white as light. The scene reveals heavenly glory through Jesus and anticipates His exaltation.", refs: ["Exodus 34:29–35","John 1:14","2 Peter 1:16–18"] },
  "Matthew 17:3": { title: "Moses and Elijah Appear", text: "Moses and Elijah appear and speak with Jesus. Their presence can be understood as bearing witness from the Law and the Prophets to the mission Jesus fulfills.", refs: ["Luke 9:30–31","Luke 24:27"] },
  "Matthew 17:4": { title: "Peter Offers to Build Tabernacles", text: "Peter proposes making three tabernacles for Jesus, Moses, and Elijah. His words show awe and confusion, and the heavenly voice will direct the disciples to hear Jesus above all.", refs: ["Mark 9:5–6","Deuteronomy 18:15"] },
  "Matthew 17:5": { title: "The Father Identifies His Beloved Son", text: "A bright cloud overshadows them, and a voice declares Jesus to be the beloved Son in whom God is well pleased, commanding the disciples to hear Him. The distinction between the heavenly voice and Jesus’ human life does not by itself require three divine persons; the passage identifies Jesus as the uniquely appointed Son.", refs: ["Matthew 3:17","Deuteronomy 18:15","2 Peter 1:17"] },
  "Matthew 17:6": { title: "The Disciples Fall on Their Faces", text: "The disciples fall down in great fear when they hear the voice. Encountering God’s majesty produces reverence and humility.", refs: ["Exodus 20:18–19","Daniel 10:8–9"] },
  "Matthew 17:7": { title: "Jesus Touches Them", text: "Jesus comes, touches the disciples, and tells them to rise and not be afraid. His reassuring presence meets them in their fear.", refs: ["Matthew 14:27","Daniel 10:10–12"] },
  "Matthew 17:8": { title: "They See Jesus Only", text: "When they look up, they see no one but Jesus. Moses and Elijah’s appearance was temporary; the disciples are directed to the Son whom the Father commanded them to hear.", refs: ["Hebrews 1:1–2","Luke 9:36"] },
  "Matthew 17:9": { title: "Tell the Vision After the Resurrection", text: "Jesus commands them not to tell the vision until the Son of man rises from the dead. The resurrection will provide the proper context for understanding His glory and messianic mission.", refs: ["Matthew 16:20–21","Mark 9:9–10"] },
  "Matthew 17:10": { title: "The Question About Elijah", text: "The disciples ask why the scribes say Elijah must come first. They are trying to reconcile the prophetic expectation with what they have just witnessed.", refs: ["Malachi 4:5–6","John 1:21"] },
  "Matthew 17:11": { title: "Elijah Restores All Things", text: "Jesus affirms that Elijah comes and restores all things. The prophecy establishes a preparatory ministry before the day of the Lord.", refs: ["Malachi 3:1","Malachi 4:5–6"] },
  "Matthew 17:12": { title: "Elijah Has Already Come", text: "Jesus explains that Elijah has already come, but people did not recognize him and mistreated him; Jesus likewise will suffer. The statement points to John the Baptist’s preparatory role.", refs: ["Matthew 11:13–14","Luke 1:17"] },
  "Matthew 17:13": { title: "The Disciples Understand John’s Role", text: "The disciples understand that Jesus is speaking about John the Baptist. John came in the spirit and power of Elijah, preparing people for the Lord.", refs: ["Luke 1:16–17","John 1:23"] },
  "Matthew 17:14": { title: "A Father Kneels Before Jesus", text: "A man comes to Jesus and kneels, bringing the desperate need of his afflicted son. The father approaches Jesus because he needs help beyond his own ability.", refs: ["Mark 9:17–18","Luke 9:38"] },
  "Matthew 17:15": { title: "The Son Suffers Terribly", text: "The father describes his son’s severe suffering and dangerous episodes. The account portrays a real family crisis and calls forth Jesus’ compassion and authority.", refs: ["Mark 9:20–22","Luke 9:39"] },
  "Matthew 17:16": { title: "The Disciples Cannot Heal Him", text: "The father says he brought the boy to Jesus’ disciples, but they could not cure him. Their inability prepares for Jesus’ correction about faith and dependence upon God.", refs: ["Matthew 10:1","Mark 9:18"] },
  "Matthew 17:17": { title: "Jesus Rebukes the Unbelieving Generation", text: "Jesus laments the unbelieving and perverse generation and asks how long He must be with them. His words expose persistent unbelief, not a lack of willingness to help the suffering boy.", refs: ["Deuteronomy 32:5","Mark 9:19"] },
  "Matthew 17:18": { title: "The Devil Leaves the Boy", text: "Jesus rebukes the devil, and it departs; the boy is healed from that hour. Jesus’ authority over evil is decisive and brings deliverance.", refs: ["Luke 4:35–36","Acts 10:38"] },
  "Matthew 17:19": { title: "The Disciples Ask Privately", text: "The disciples ask Jesus why they could not cast the devil out. They seek an explanation for their failure rather than hiding it.", refs: ["Mark 9:28","James 1:5"] },
  "Matthew 17:20": { title: "Faith as a Grain of Mustard Seed", text: "Jesus points to their little faith and says faith as a mustard seed can move a mountain. The image teaches confidence in God’s power, not a magical formula or a guarantee that every personal wish will occur.", refs: ["Matthew 21:21","Luke 17:6"] },
  "Matthew 17:21": { title: "Prayer and Fasting", text: "Some later manuscript traditions include a verse about this kind not going out except by prayer and fasting, while many modern editions omit it or place it in a note. The related teaching about prayer and fasting appears in Mark’s account.", refs: ["Mark 9:29","Acts 13:2–3"] },
  "Matthew 17:22": { title: "The Son of Man Will Be Betrayed", text: "Jesus tells the disciples again that the Son of man will be delivered into human hands. His coming suffering is part of the mission He knowingly continues.", refs: ["Matthew 16:21","Matthew 20:18–19"] },
  "Matthew 17:23": { title: "Death and Resurrection Foretold", text: "Jesus says He will be killed and raised the third day, and the disciples are exceedingly sorry. Their grief shows they hear the prediction’s pain but have not yet embraced the hope of resurrection.", refs: ["Matthew 12:40","Luke 24:6–8"] },
  "Matthew 17:24": { title: "The Temple Tribute", text: "Collectors of the half-shekel temple tribute ask Peter whether Jesus pays it. The question concerns the temple tax, not the Roman tribute imposed by Caesar.", refs: ["Exodus 30:13–16","Mark 12:17"] },
  "Matthew 17:25": { title: "Children Are Free", text: "Jesus asks Peter whether kings collect taxes from their own children or from strangers. The illustration leads to a point about the Son’s relationship to the temple and the freedom of God’s children.", refs: ["Romans 8:15–17","Galatians 4:4–7"] },
  "Matthew 17:26": { title: "The Sons Are Free", text: "Peter answers that tribute is collected from strangers, and Jesus concludes that the children are free. Jesus is not submitting because He lacks authority; He is explaining His status and the principle behind the next action.", refs: ["Matthew 12:6","John 2:19–21"] },
  "Matthew 17:27": { title: "The Coin in the Fish’s Mouth", text: "To avoid needless offense, Jesus tells Peter to catch a fish and use the coin found in its mouth to pay for both of them. Jesus exercises knowledge and authority while choosing a peaceful course in a matter that does not compromise truth.", refs: ["Romans 14:13","1 Corinthians 9:19–23"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 18:1": { title: "Who Is Greatest in the Kingdom?", text: "The disciples ask who is greatest in the kingdom of heaven. Their question exposes the temptation to measure kingdom life by rank rather than humility and service.", refs: ["Mark 9:33–34","Luke 22:24–26"] },
  "Matthew 18:2": { title: "Jesus Sets a Child Among Them", text: "Jesus calls a little child and sets the child in their midst. He uses the child as a living lesson about the humble posture required of kingdom citizens.", refs: ["Mark 9:36","Luke 9:47"] },
  "Matthew 18:3": { title: "Become as Little Children", text: "Jesus says they must be converted and become as little children to enter the kingdom. He calls for a changed disposition marked by humility and dependence, not childish ignorance.", refs: ["Matthew 5:3","1 Peter 2:2"] },
  "Matthew 18:4": { title: "Humility Is Greatness", text: "Whoever humbles himself like this child is greatest in the kingdom. God’s measure of greatness differs from worldly ambition and self-promotion.", refs: ["Matthew 23:11–12","James 4:6"] },
  "Matthew 18:5": { title: "Receiving a Child in Jesus’ Name", text: "Receiving a child in Jesus’ name is treated as receiving Jesus Himself. How people treat the vulnerable matters to the Lord.", refs: ["Matthew 10:40–42","Mark 9:37"] },
  "Matthew 18:6": { title: "Do Not Cause Little Ones to Stumble", text: "Jesus gives a severe warning against causing a believer who is little in faith to stumble. Spiritual influence carries serious responsibility, especially toward the vulnerable.", refs: ["Luke 17:1–2","Romans 14:13"] },
  "Matthew 18:7": { title: "Woe to the World Because of Offences", text: "Jesus acknowledges that stumbling blocks will come but pronounces woe on the person through whom they come. The presence of evil in the world does not excuse anyone who chooses to cause harm.", refs: ["Luke 17:1","Romans 1:32"] },
  "Matthew 18:8": { title: "Remove What Leads You to Sin", text: "Jesus uses strong imagery about cutting off a hand or foot rather than being cast into everlasting fire. The language stresses decisive action against sin, not self-mutilation.", refs: ["Matthew 5:29–30","Colossians 3:5"] },
  "Matthew 18:9": { title: "Guard the Eye", text: "The warning about plucking out an eye likewise calls for radical resistance to sin. Nothing in this teaching makes bodily injury the remedy; Jesus emphasizes the eternal seriousness of sin.", refs: ["Matthew 5:29","Romans 6:12–13"] },
  "Matthew 18:10": { title: "Do Not Despise Little Ones", text: "Jesus warns against despising these little ones and speaks of their angels beholding the Father’s face. Heaven is not indifferent to those whom the world may overlook.", refs: ["Psalm 91:11","Hebrews 1:14"] },
  "Matthew 18:11": { title: "The Son of Man Saves the Lost", text: "Some later manuscript traditions include a verse stating that the Son of man came to save the lost, while many modern editions omit it or place it in a note. The teaching itself is clearly affirmed elsewhere in the Gospels.", refs: ["Luke 19:10","Matthew 9:13"] },
  "Matthew 18:12": { title: "The Lost Sheep", text: "Jesus asks whether a shepherd would leave ninety-nine sheep to seek one that has gone astray. The illustration reveals the value of the wandering one and the seeking heart of God.", refs: ["Luke 15:4–7","Ezekiel 34:11–16"] },
  "Matthew 18:13": { title: "Joy over the Found Sheep", text: "The shepherd rejoices more over the recovered sheep than over those that never strayed. Heaven rejoices when the lost are restored.", refs: ["Luke 15:7","Zephaniah 3:17"] },
  "Matthew 18:14": { title: "The Father’s Will for Little Ones", text: "Jesus says it is not the Father’s will that one of these little ones should perish. This underscores God’s concern for the vulnerable and those in danger of wandering.", refs: ["John 6:39","2 Peter 3:9"] },
  "Matthew 18:15": { title: "Go to a Brother Who Sins", text: "Jesus instructs a believer to address a sinning brother privately first. The aim is to gain the brother, not to shame him publicly or spread the matter unnecessarily.", refs: ["Leviticus 19:17","Galatians 6:1"] },
  "Matthew 18:16": { title: "Take One or Two Witnesses", text: "If the brother will not hear, take one or two others so that the matter may be established by witnesses. This protects fairness and follows the scriptural principle of reliable testimony.", refs: ["Deuteronomy 19:15","2 Corinthians 13:1"] },
  "Matthew 18:17": { title: "Tell It to the Church", text: "If he refuses to hear the witnesses, the matter is brought to the church; continued refusal affects fellowship. The process is serious but restorative in purpose, and discipline must follow truth and justice.", refs: ["1 Corinthians 5:1–5","2 Thessalonians 3:14–15"] },
  "Matthew 18:18": { title: "Binding and Loosing", text: "Jesus speaks of binding and loosing in the context of the church’s handling of sin and reconciliation. Such authority must be exercised under His teaching, not as personal power to contradict God’s will.", refs: ["Matthew 16:19","John 20:23"] },
  "Matthew 18:19": { title: "Agreement in Prayer", text: "Jesus teaches that when two agree in prayer concerning a matter, the Father hears. The promise encourages united, God-directed prayer; it is not a guarantee that every selfish request will be granted.", refs: ["John 14:13–14","1 John 5:14"] },
  "Matthew 18:20": { title: "Gathered in Jesus’ Name", text: "Jesus promises to be in the midst of two or three gathered in His name. The power of the assembly rests in His presence and authority, not merely in the size of the gathering.", refs: ["Matthew 28:20","1 Corinthians 5:4"] },
  "Matthew 18:21": { title: "Peter Asks How Often to Forgive", text: "Peter asks whether forgiving a brother seven times is enough. He is trying to define a limit, while Jesus is about to teach a more generous spirit of forgiveness.", refs: ["Luke 17:3–4","Colossians 3:13"] },
  "Matthew 18:22": { title: "Forgive Without Keeping Count", text: "Jesus answers with a figure expressing forgiveness far beyond a narrow numerical limit. His point is not arithmetic but a heart ready to forgive repeatedly when repentance is shown.", refs: ["Genesis 4:24","Ephesians 4:32"] },
  "Matthew 18:23": { title: "A King Settles Accounts", text: "Jesus compares the kingdom to a king who begins settling accounts with his servants. The parable teaches that people who receive mercy from God must show mercy to others.", refs: ["Matthew 6:12","Romans 14:12"] },
  "Matthew 18:24": { title: "A Servant Owes a Great Debt", text: "One servant is brought in who owes an enormous sum. The debt illustrates the overwhelming account a person cannot repay by his own resources.", refs: ["Psalm 130:3–4","Romans 3:23–24"] },
  "Matthew 18:25": { title: "The Servant Cannot Pay", text: "Because the servant cannot repay, the king orders that he and his family and possessions be sold. The situation emphasizes the servant’s helplessness under the debt.", refs: ["Luke 7:42","Romans 6:23"] },
  "Matthew 18:26": { title: "The Servant Begs for Patience", text: "The servant falls down and pleads for patience, promising repayment. His promise cannot realistically meet the enormous debt, making the king’s mercy all the more striking.", refs: ["Psalm 51:1","Luke 18:13"] },
  "Matthew 18:27": { title: "The King Forgives the Debt", text: "Moved with compassion, the king releases the servant and forgives the debt. This is a picture of mercy freely granted rather than earned by repayment.", refs: ["Ephesians 1:7","Titus 3:5"] },
  "Matthew 18:28": { title: "The Forgiven Servant Refuses Mercy", text: "The servant finds a fellow servant who owes him a much smaller amount and demands payment harshly. Having received mercy, he fails to extend it to someone else.", refs: ["James 2:13","Matthew 6:14–15"] },
  "Matthew 18:29": { title: "His Fellow Servant Begs", text: "The fellow servant uses the same plea for patience that the first servant had made to the king. The parallel exposes the first servant’s hypocrisy.", refs: ["Matthew 18:26","Proverbs 21:13"] },
  "Matthew 18:30": { title: "He Will Not Forgive", text: "The first servant refuses and has the fellow servant imprisoned until the debt is paid. His lack of compassion contradicts the mercy he himself received.", refs: ["Matthew 5:7","Mark 11:25"] },
  "Matthew 18:31": { title: "Other Servants Are Grieved", text: "The other servants are deeply troubled and report what happened to the king. Cruelty and unforgiveness harm the wider community and are not hidden from judgment.", refs: ["Romans 12:15","1 John 3:17"] },
  "Matthew 18:32": { title: "The King Calls Him Wicked", text: "The king rebukes the servant for failing to show the mercy that had been shown to him. Receiving forgiveness creates a moral obligation to forgive others.", refs: ["Luke 6:36","Ephesians 4:32"] },
  "Matthew 18:33": { title: "Should You Not Have Had Compassion?", text: "The king asks whether the servant should have had compassion on his fellow servant. The question summarizes the moral center of the parable.", refs: ["Matthew 5:7","Colossians 3:12–13"] },
  "Matthew 18:34": { title: "Judgment for Unforgiveness", text: "The angry king delivers the servant to the tormentors until the debt is paid. The severe ending warns that a settled refusal to forgive is incompatible with truly receiving God’s mercy.", refs: ["Matthew 6:15","Hebrews 10:26–27"] },
  "Matthew 18:35": { title: "Forgive from the Heart", text: "Jesus applies the parable: each must forgive a brother from the heart. Biblical forgiveness is not merely polite words; it is a sincere release of vengeance, while accountability and wise boundaries may still be necessary.", refs: ["Mark 11:25","Romans 12:19","Ephesians 4:32"] },

  "Matthew 19:1": { title: "Jesus Departs from Galilee", text: "Jesus finishes these sayings and travels from Galilee into the coasts of Judaea beyond Jordan. The narrative moves toward the final journey to Jerusalem.", refs: ["Mark 10:1","Luke 9:51"] },
  "Matthew 19:2": { title: "The Multitudes Follow and Are Healed", text: "Great multitudes follow Jesus, and He heals them there. His teaching ministry continues alongside acts of compassion.", refs: ["Matthew 4:23","Matthew 14:14"] },
  "Matthew 19:3": { title: "A Question About Divorce", text: "The Pharisees test Jesus by asking whether a man may put away his wife for every cause. Their question seeks controversy, but Jesus directs them back to God’s design in creation.", refs: ["Mark 10:2","Deuteronomy 24:1"] },
  "Matthew 19:4": { title: "Male and Female from the Beginning", text: "Jesus points to the Creator’s making of male and female. Marriage is grounded in God’s creative purpose, not merely in later custom or convenience.", refs: ["Genesis 1:27","Genesis 5:2"] },
  "Matthew 19:5": { title: "One Flesh", text: "Jesus quotes the creation account: a man leaves father and mother and cleaves to his wife, and the two become one flesh. Marriage forms a covenantal union that is not to be treated lightly.", refs: ["Genesis 2:24","Ephesians 5:31"] },
  "Matthew 19:6": { title: "What God Has Joined", text: "Jesus says the two are no longer two but one flesh, and people should not separate what God has joined. His teaching upholds the seriousness and intended permanence of marriage.", refs: ["Malachi 2:14–16","Mark 10:9"] },
  "Matthew 19:7": { title: "Moses and the Writing of Divorce", text: "The Pharisees ask why Moses commanded a writing of divorcement. Jesus distinguishes a concession in the law from God’s original design.", refs: ["Deuteronomy 24:1–4","Mark 10:3–4"] },
  "Matthew 19:8": { title: "Hardness of Heart", text: "Jesus says Moses permitted divorce because of hardness of heart, but it was not so from the beginning. A concession addressing human sin should not be mistaken for the Creator’s ideal.", refs: ["Matthew 5:31–32","Genesis 2:24"] },
  "Matthew 19:9": { title: "Jesus’ Serious Warning on Divorce", text: "Jesus gives a strict warning against divorce and remarriage, with the exception clause concerning fornication. This verse must be read carefully alongside the broader biblical teaching on marriage, sexual faithfulness, and covenant responsibility.", refs: ["Matthew 5:32","Mark 10:11–12","1 Corinthians 7:10–15"] },
  "Matthew 19:10": { title: "The Disciples React", text: "The disciples conclude that if marriage carries such responsibility, it may be better not to marry. Their reaction shows how demanding Jesus’ teaching seemed to them.", refs: ["Mark 10:10–12","1 Corinthians 7:7–9"] },
  "Matthew 19:11": { title: "Not Everyone Receives This Saying", text: "Jesus says not everyone can receive the saying, but those to whom it is given can. He recognizes that people have different callings and capacities regarding marriage and celibacy.", refs: ["1 Corinthians 7:7","1 Corinthians 7:17"] },
  "Matthew 19:12": { title: "Those Who Remain Unmarried for the Kingdom", text: "Jesus describes different reasons some remain unmarried, including choosing a single life for the kingdom’s sake. This is a calling for some, not a command that all must avoid marriage.", refs: ["1 Corinthians 7:32–35","Isaiah 56:4–5"] },
  "Matthew 19:13": { title: "Children Brought to Jesus", text: "People bring little children to Jesus so He can lay hands on them and pray, but the disciples rebuke them. Jesus’ response will correct the idea that children are unworthy of His attention.", refs: ["Mark 10:13","Luke 18:15"] },
  "Matthew 19:14": { title: "Let the Children Come", text: "Jesus commands that the children be allowed to come to Him, for the kingdom of heaven belongs to such as these. He welcomes them and commends the humble posture they illustrate.", refs: ["Matthew 18:3–4","Mark 10:14"] },
  "Matthew 19:15": { title: "Jesus Blesses the Children", text: "Jesus lays His hands on the children and departs. His action confirms that His welcome is real and personal, not merely a lesson in symbolism.", refs: ["Mark 10:16","Luke 18:16"] },
  "Matthew 19:16": { title: "The Rich Young Man Asks About Life", text: "A man asks Jesus what good thing he must do to have eternal life. His question begins a conversation that exposes the difference between outward obedience and wholehearted surrender.", refs: ["Mark 10:17","Luke 18:18"] },
  "Matthew 19:17": { title: "Goodness and God’s Commandments", text: "Jesus directs the man to God’s goodness and the commandments. The response challenges shallow assumptions about goodness and places the questioner under God’s moral standard.", refs: ["Exodus 20:12–16","Romans 3:20"] },
  "Matthew 19:18": { title: "Commandments Concerning Neighbor", text: "Jesus names commandments against murder, adultery, theft, and false witness. These commands concern concrete conduct toward other people.", refs: ["Exodus 20:13–16","Romans 13:9"] },
  "Matthew 19:19": { title: "Honor Parents and Love Your Neighbor", text: "Jesus includes honoring parents and loving one’s neighbor as oneself. Love fulfills the law’s intent but does not turn obedience into a means of boasting.", refs: ["Exodus 20:12","Leviticus 19:18","Romans 13:8–10"] },
  "Matthew 19:20": { title: "The Man Claims to Have Kept the Commands", text: "The young man says he has kept these commandments and asks what he still lacks. Jesus will reveal the deeper allegiance that his self-assessment has not confronted.", refs: ["Luke 18:21","Philippians 3:6–9"] },
  "Matthew 19:21": { title: "Sell, Give, and Follow Jesus", text: "Jesus tells him to sell his possessions, give to the poor, gain treasure in heaven, and follow Him. The command exposes the man’s attachment to wealth and calls him to place Jesus above his possessions.", refs: ["Luke 12:33","Matthew 6:19–21"] },
  "Matthew 19:22": { title: "The Young Man Goes Away Sorrowful", text: "The man leaves grieving because he has great possessions. His sorrow reveals that he is unwilling to surrender what competes with obedience to Jesus.", refs: ["Mark 10:22","Luke 12:15"] },
  "Matthew 19:23": { title: "The Difficulty of the Rich Entering", text: "Jesus says it is difficult for a rich person to enter the kingdom of heaven. Wealth can foster self-reliance and attachment, making surrender to God harder.", refs: ["1 Timothy 6:9–10","James 5:1–3"] },
  "Matthew 19:24": { title: "A Camel Through a Needle’s Eye", text: "Jesus uses an intentionally striking image to show the difficulty of wealth obstructing entry into God’s kingdom. The point is not a clever loophole but the impossibility of relying on riches as a route to life.", refs: ["Mark 10:25","Luke 18:25"] },
  "Matthew 19:25": { title: "Who Then Can Be Saved?", text: "The disciples are astonished and ask who can be saved. They recognize that if wealth and status cannot secure salvation, no one can presume on human advantage.", refs: ["Psalm 49:6–9","Romans 3:23"] },
  "Matthew 19:26": { title: "With God All Things Are Possible", text: "Jesus says that salvation is impossible with people but possible with God. Eternal life is ultimately made possible by God’s saving work, not human achievement or wealth.", refs: ["Jeremiah 32:17","Luke 1:37","Ephesians 2:8–9"] },
  "Matthew 19:27": { title: "Peter Asks About Their Reward", text: "Peter says the disciples have left all to follow Jesus and asks what they will receive. The question raises the cost of discipleship and the hope of God’s promised restoration.", refs: ["Mark 10:28","Luke 18:28"] },
  "Matthew 19:28": { title: "The Regeneration and the Twelve Thrones", text: "Jesus speaks of the regeneration, when the Son of man sits on His glorious throne, and promises the twelve apostles a role in judging the twelve tribes of Israel. The saying points to future kingdom restoration and apostolic responsibility.", refs: ["Luke 22:28–30","Revelation 21:12–14"] },
  "Matthew 19:29": { title: "Reward for Leaving All for Jesus", text: "Those who leave homes, family, or lands for Jesus’ name will receive abundantly and inherit eternal life. Jesus does not teach contempt for family; He teaches that loyalty to Him outranks every earthly claim.", refs: ["Mark 10:29–30","Luke 14:26"] },
  "Matthew 19:30": { title: "The First and the Last", text: "Jesus warns that many who are first will be last and the last first. Kingdom reward overturns worldly ranking and calls for humility rather than entitlement.", refs: ["Matthew 20:16","Luke 13:30"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 20:1": { title: "The Laborers in the Vineyard", text: "Jesus compares the kingdom of heaven to a householder who hires laborers for his vineyard. The parable addresses God's generosity and warns against measuring His goodness by human comparisons.", refs: ["Matthew 19:30","Matthew 20:16"] },
  "Matthew 20:2": { title: "An Agreed Penny", text: "The householder agrees with the first laborers for a penny a day and sends them to work. Their agreement establishes the expectation against which the later payment is judged.", refs: ["Leviticus 19:13","Matthew 20:13"] },
  "Matthew 20:3": { title: "Laborers at the Third Hour", text: "The householder finds others standing idle in the marketplace at the third hour. He continues seeking workers rather than limiting his invitation to the first group.", refs: ["Matthew 9:37–38","John 4:35"] },
  "Matthew 20:4": { title: "A Promise to Pay What Is Right", text: "He tells the later workers to go into the vineyard and promises to give them what is right. Their trust rests on the householder's word rather than a specified wage.", refs: ["Psalm 9:8","Romans 9:14–16"] },
  "Matthew 20:5": { title: "More Workers Are Hired", text: "The householder goes out again at the sixth and ninth hours and does the same. The repeated invitations show his continuing willingness to bring people into the work.", refs: ["Isaiah 55:6","John 6:37"] },
  "Matthew 20:6": { title: "Workers at the Eleventh Hour", text: "Near the end of the day, the householder finds others still standing idle and asks why they have not worked. They explain that no one hired them.", refs: ["Luke 23:39–43","2 Peter 3:9"] },
  "Matthew 20:7": { title: "Go Into the Vineyard", text: "The householder sends them into the vineyard too. The invitation reaches even those who begin late, displaying generosity without suggesting that a person should deliberately delay obedience.", refs: ["Luke 14:21–23","Hebrews 3:15"] },
  "Matthew 20:8": { title: "The Wages Are Paid", text: "At evening, the owner tells his steward to pay the laborers, beginning with the last and ending with the first. The order of payment exposes the attitudes of those who compare their reward with others.", refs: ["Leviticus 19:13","Deuteronomy 24:15"] },
  "Matthew 20:9": { title: "The Last Receive a Penny", text: "Those hired at the eleventh hour each receive a penny. The householder's generosity toward them is the central surprise of the parable.", refs: ["Romans 4:4–5","Titus 3:5–7"] },
  "Matthew 20:10": { title: "The First Expect More", text: "The first laborers assume they will receive more when they see the late workers paid the same amount. Their expectation turns another person's blessing into a reason for resentment.", refs: ["Jonah 4:1–4","Luke 15:28–30"] },
  "Matthew 20:11": { title: "They Complain Against the Householder", text: "After receiving their wages, the first laborers murmur against the householder. Their complaint reveals dissatisfaction with his generosity, despite receiving the wage they had agreed upon.", refs: ["Exodus 16:2–8","1 Corinthians 10:10"] },
  "Matthew 20:12": { title: "The Complaint of Unequal Hours", text: "They complain that those who worked only one hour were paid equally with them despite the day's heat and burden. They judge fairness only by comparison, not by the agreement they received.", refs: ["Luke 15:29–30","Romans 12:15"] },
  "Matthew 20:13": { title: "No Wrong Was Done", text: "The householder answers one of them that he has done no wrong and paid the agreed wage. God's generosity to another person does not mean He has broken His promise to us.", refs: ["Deuteronomy 32:4","Romans 9:14"] },
  "Matthew 20:14": { title: "Take What Is Yours", text: "The householder tells the laborer to take what is his and says he chooses to give the last worker the same. The parable distinguishes justice in keeping a promise from generosity freely extended.", refs: ["Romans 11:6","James 1:17"] },
  "Matthew 20:15": { title: "The Right to Be Generous", text: "The householder asks whether he may do what he wishes with his own and whether the laborer's eye is evil because he is good. Envy resents goodness when it benefits someone else.", refs: ["Deuteronomy 15:9–10","Proverbs 23:6–7"] },
  "Matthew 20:16": { title: "The Last Shall Be First", text: "Jesus concludes that the last will be first and the first last. God's kingdom overturns pride and entitlement; His generosity is not controlled by human rankings.", refs: ["Matthew 19:30","Luke 13:30"] },
  "Matthew 20:17": { title: "Jesus Goes Up to Jerusalem", text: "Jesus takes the twelve disciples aside on the way to Jerusalem. He prepares them for what is coming rather than allowing them to misunderstand His mission as earthly triumph alone.", refs: ["Mark 10:32","Luke 18:31"] },
  "Matthew 20:18": { title: "The Son of Man Will Be Delivered", text: "Jesus says the Son of man will be delivered to the chief priests and scribes and condemned to death. His suffering is foreknown and central to His saving work.", refs: ["Isaiah 53:3–8","Matthew 16:21"] },
  "Matthew 20:19": { title: "Crucifixion and Resurrection Foretold", text: "Jesus says He will be delivered to the Gentiles, mocked, scourged, crucified, and raised on the third day. The prediction joins the humiliation of the cross with the certainty of resurrection.", refs: ["Psalm 22:1–18","Matthew 28:5–6","Luke 24:7"] },
  "Matthew 20:20": { title: "A Request for Her Sons", text: "The mother of Zebedee's sons approaches Jesus with her sons and makes a request. The next exchange reveals that even close followers still misunderstand the nature of kingdom greatness.", refs: ["Mark 10:35","Matthew 18:1"] },
  "Matthew 20:21": { title: "Seats at the Right and Left", text: "She asks that her sons sit at Jesus' right and left in His kingdom. Their ambition seeks honor before they have understood the suffering Jesus has just described.", refs: ["Matthew 19:28","Mark 10:37"] },
  "Matthew 20:22": { title: "Can You Drink the Cup?", text: "Jesus asks whether they can drink the cup He is about to drink. The cup points to suffering; discipleship is not simply a claim to honor but a willingness to remain faithful through hardship.", refs: ["Matthew 26:39","John 18:11"] },
  "Matthew 20:23": { title: "Places of Honor Are Not His to Assign", text: "Jesus says they will share in His cup, but places at His right and left are prepared by the Father. The passage emphasizes that kingdom honor is assigned according to God's purpose, not secured by ambition.", refs: ["Acts 1:7","Mark 10:40"] },
  "Matthew 20:24": { title: "The Ten Are Indignant", text: "The other ten disciples are displeased with the two brothers. Their indignation suggests that rivalry is not confined to the pair who made the request.", refs: ["Luke 22:24","Philippians 2:3"] },
  "Matthew 20:25": { title: "Gentile Rulers Exercise Authority", text: "Jesus contrasts kingdom leadership with rulers who dominate those under them. His followers must not imitate leadership built on oppression and status.", refs: ["Mark 10:42","1 Peter 5:2–3"] },
  "Matthew 20:26": { title: "Greatness Through Service", text: "Jesus says it must not be so among His disciples; whoever would be great must become a servant. Kingdom greatness is measured by service rather than control.", refs: ["Matthew 23:11","John 13:14–15"] },
  "Matthew 20:27": { title: "The First Must Be Servant", text: "Whoever wants to be first must become a servant. Jesus calls His people to put others' needs ahead of self-promotion.", refs: ["Mark 9:35","Romans 12:10"] },
  "Matthew 20:28": { title: "The Son of Man Gives His Life", text: "Jesus says the Son of man came not to be served but to serve and give His life a ransom for many. The sacrifice is His own life freely given for the deliverance of others; the verse does not require describing salvation as one divine person paying another divine person.", refs: ["Isaiah 53:10–12","1 Timothy 2:5–6","John 10:17–18"] },
  "Matthew 20:29": { title: "Two Blind Men Near Jericho", text: "As Jesus and His disciples leave Jericho, a great multitude follows. The setting leads to a public appeal for mercy from two blind men.", refs: ["Mark 10:46","Luke 18:35"] },
  "Matthew 20:30": { title: "Jesus, Son of David, Have Mercy", text: "Two blind men hear that Jesus is passing and cry out to Him as Son of David. Their title recognizes His messianic lineage, and their plea depends on His mercy.", refs: ["Isaiah 35:5","Matthew 9:27"] },
  "Matthew 20:31": { title: "They Cry Out More Earnestly", text: "The crowd rebukes the men and tells them to be quiet, but they cry out even more. They refuse to let public pressure silence their appeal to Jesus.", refs: ["Luke 18:39","Psalm 34:6"] },
  "Matthew 20:32": { title: "Jesus Stops and Asks", text: "Jesus stands still, calls the men, and asks what they want Him to do. He gives them the opportunity to state their need plainly.", refs: ["Mark 10:49–51","Philippians 4:6"] },
  "Matthew 20:33": { title: "Lord, Open Our Eyes", text: "They ask Jesus to open their eyes. Their request is direct and shows confidence that He can restore their sight.", refs: ["Psalm 146:8","Isaiah 42:7"] },
  "Matthew 20:34": { title: "Jesus Has Compassion and Heals", text: "Moved with compassion, Jesus touches their eyes, and immediately they receive sight and follow Him. His healing power is joined with mercy and leads the men into discipleship.", refs: ["Matthew 9:29–30","Mark 10:52"] },

  "Matthew 21:1": { title: "Approaching Jerusalem", text: "Jesus and His disciples come near Jerusalem to Bethphage at the Mount of Olives. The setting prepares for His public entry as the promised King.", refs: ["Zechariah 14:4","Mark 11:1"] },
  "Matthew 21:2": { title: "The Donkey and Her Colt", text: "Jesus sends two disciples to find a donkey tied with her colt and tells them to bring them. The precise instructions show that the entry unfolds according to His direction.", refs: ["Mark 11:2–3","Luke 19:30–31"] },
  "Matthew 21:3": { title: "The Lord Has Need of Them", text: "Jesus tells the disciples what to say if anyone questions them: the Lord has need of them and will send them back. The statement asserts His authority over the arrangements for His entry.", refs: ["Matthew 28:18","Mark 11:3"] },
  "Matthew 21:4": { title: "The Prophet's Word Fulfilled", text: "These events fulfill what was spoken through the prophet. Matthew presents Jesus' entry as the fulfillment of Scripture, not an accidental public scene.", refs: ["Zechariah 9:9","John 12:14–16"] },
  "Matthew 21:5": { title: "The King Comes Meekly", text: "The daughter of Sion is told that her King comes meek, riding on a donkey and a colt. Jesus displays royal identity without the symbols of a conquering military ruler.", refs: ["Zechariah 9:9","Isaiah 62:11"] },
  "Matthew 21:6": { title: "The Disciples Obey", text: "The disciples do as Jesus commanded them. Their simple obedience helps bring the prophetic sign to pass.", refs: ["John 2:5","Matthew 28:19–20"] },
  "Matthew 21:7": { title: "The Animals Are Brought to Jesus", text: "They bring the donkey and colt, place garments on them, and Jesus sits on them. The action gives visible expression to the prophecy of the humble King.", refs: ["Mark 11:7","Luke 19:35"] },
  "Matthew 21:8": { title: "Garments and Branches on the Road", text: "Many spread their garments in the way, while others cut branches and lay them down. The crowd honors Jesus in a manner associated with welcoming a king.", refs: ["2 Kings 9:13","John 12:13"] },
  "Matthew 21:9": { title: "Hosanna to the Son of David", text: "The crowds cry Hosanna to the Son of David and bless the One who comes in the Lord's name. Their words echo the Psalms and proclaim messianic hope.", refs: ["Psalm 118:25–26","Matthew 12:23"] },
  "Matthew 21:10": { title: "Jerusalem Is Stirred", text: "Jesus' entry stirs the whole city, and people ask who He is. His presence demands a response and makes His identity a public question.", refs: ["Matthew 2:3","John 12:19"] },
  "Matthew 21:11": { title: "Jesus the Prophet of Nazareth", text: "The crowds answer that Jesus is the prophet from Nazareth of Galilee. This is true as far as it goes, but Matthew's Gospel has already revealed Him as more than a prophet: the Christ and Son of God.", refs: ["Deuteronomy 18:15","Matthew 16:16"] },
  "Matthew 21:12": { title: "Jesus Cleanses the Temple", text: "Jesus drives out those buying and selling in the temple and overturns the money changers' tables. His action confronts the corruption of worship and asserts the holiness of God's house.", refs: ["Isaiah 56:7","Jeremiah 7:11","John 2:14–16"] },
  "Matthew 21:13": { title: "A House of Prayer Made a Den of Thieves", text: "Jesus cites Scripture to declare that God's house should be called a house of prayer, but they have made it a den of thieves. Worship must honor God's purpose rather than exploit people.", refs: ["Isaiah 56:7","Jeremiah 7:11"] },
  "Matthew 21:14": { title: "The Blind and Lame Come to Jesus", text: "Blind and lame people come to Jesus in the temple, and He heals them. After confronting corruption, He demonstrates the healing mercy that should characterize God's house.", refs: ["Isaiah 35:5–6","Matthew 15:30"] },
  "Matthew 21:15": { title: "Children Cry Hosanna", text: "The chief priests and scribes are displeased by Jesus' works and by children crying Hosanna to the Son of David. Those in authority resent praise that recognizes Jesus' messianic identity.", refs: ["Psalm 8:2","Matthew 21:9"] },
  "Matthew 21:16": { title: "Praise from the Mouths of Children", text: "Jesus quotes Scripture about praise perfected from the mouths of children. He accepts their praise and rebukes the leaders for failing to recognize what Scripture says.", refs: ["Psalm 8:2","Luke 19:40"] },
  "Matthew 21:17": { title: "Jesus Goes to Bethany", text: "Jesus leaves the city and lodges in Bethany. His movements between Bethany and Jerusalem frame the events of the final week.", refs: ["Mark 11:11","John 11:18"] },
  "Matthew 21:18": { title: "Jesus Is Hungry", text: "In the morning Jesus returns to the city and is hungry. The ordinary detail of hunger underscores His real human experience.", refs: ["Matthew 4:2","John 4:6"] },
  "Matthew 21:19": { title: "The Fig Tree Withers", text: "Jesus finds no fruit on a fig tree, speaks judgment upon it, and it withers. The acted parable warns against a show of religious life without the fruit God seeks.", refs: ["Mark 11:12–14","Luke 13:6–9"] },
  "Matthew 21:20": { title: "The Disciples Marvel", text: "The disciples are amazed at how quickly the fig tree withers. Their wonder opens the way for Jesus to teach them about faith and prayer.", refs: ["Mark 11:20–21","Matthew 17:20"] },
  "Matthew 21:21": { title: "Faith Without Doubting", text: "Jesus teaches that faith can accomplish what seems impossible, using the mountain and sea as vivid imagery. This is a call to trust God, not a promise that human desire can command any outcome.", refs: ["Matthew 17:20","James 1:6–7"] },
  "Matthew 21:22": { title: "Ask in Prayer, Believing", text: "Jesus connects prayer with believing. Biblical prayer trusts God's wisdom and will rather than treating faith as a technique to force an answer.", refs: ["1 John 5:14","Mark 11:24"] },
  "Matthew 21:23": { title: "Who Gave You This Authority?", text: "Chief priests and elders challenge Jesus' authority to teach and act in the temple. Their question is institutional, but Jesus exposes their unwillingness to respond honestly to God's witness.", refs: ["Matthew 7:29","Acts 4:7"] },
  "Matthew 21:24": { title: "Jesus Asks a Question in Return", text: "Jesus says He will answer if they first answer His question about John's baptism. Their response to John will reveal whether they are truly seeking truth.", refs: ["Matthew 11:7–11","Luke 20:3–4"] },
  "Matthew 21:25": { title: "The Baptism of John", text: "Jesus asks whether John's baptism came from heaven or from men. The leaders privately weigh the consequences of each answer instead of asking which answer is true.", refs: ["John 1:6–8","Matthew 3:5–6"] },
  "Matthew 21:26": { title: "Fear of the Multitude", text: "They fear the crowd because the people regard John as a prophet. Fear of public opinion prevents them from speaking plainly about God's messenger.", refs: ["Matthew 14:5","John 9:22"] },
  "Matthew 21:27": { title: "We Cannot Tell", text: "The leaders answer that they do not know, so Jesus declines to answer their challenge. Their evasive response reveals that their question was not a sincere search for truth.", refs: ["Proverbs 26:4–5","Luke 20:7–8"] },
  "Matthew 21:28": { title: "A Father and Two Sons", text: "Jesus introduces a parable of a father who tells two sons to work in his vineyard. Their different responses will show that obedience is demonstrated by action, not words alone.", refs: ["Matthew 7:21","Luke 6:46"] },
  "Matthew 21:29": { title: "The Son Who First Refuses", text: "One son says he will not go, but afterward repents and goes. His initial refusal is wrong, yet he ultimately responds with action.", refs: ["Ezekiel 18:21–23","Luke 15:18–20"] },
  "Matthew 21:30": { title: "The Son Who Says Yes", text: "The second son says he will go but does not. A respectful-sounding promise is worthless when it is not followed by obedience.", refs: ["James 1:22","Titus 1:16"] },
  "Matthew 21:31": { title: "Publicans and Harlots Enter First", text: "Jesus says tax collectors and harlots go into the kingdom before the leaders because they believed John, while the leaders did not repent afterward. Responding to God's call matters more than a reputation for religious respectability.", refs: ["Luke 7:29–30","Matthew 3:5–8"] },
  "Matthew 21:32": { title: "John Came in the Way of Righteousness", text: "John came showing the way of righteousness, yet the leaders did not believe him even after seeing sinners respond. Their failure is not lack of evidence but refusal to repent and believe.", refs: ["Matthew 3:1–8","Luke 7:30"] },
  "Matthew 21:33": { title: "The Parable of the Vineyard", text: "Jesus tells of a householder who plants a vineyard, equips it, leases it, and travels away. The imagery echoes Isaiah's vineyard song and prepares an indictment of leaders who reject God's messengers.", refs: ["Isaiah 5:1–7","Mark 12:1"] },
  "Matthew 21:34": { title: "Servants Sent for Fruit", text: "At harvest, the owner sends servants to receive the fruit. The servants represent those sent to call the tenants to fulfill their responsibility.", refs: ["2 Chronicles 36:15–16","Jeremiah 7:25–26"] },
  "Matthew 21:35": { title: "The Servants Are Mistreated", text: "The tenants seize the servants, beat one, kill another, and stone another. The parable recalls the repeated rejection and persecution of God's messengers.", refs: ["Nehemiah 9:26","Hebrews 11:36–38"] },
  "Matthew 21:36": { title: "More Servants Are Sent", text: "The owner sends additional servants, more than before, and they are treated the same way. God's repeated warnings reveal patience, while continued rejection increases accountability.", refs: ["Jeremiah 25:4","Matthew 23:37"] },
  "Matthew 21:37": { title: "The Beloved Son Is Sent", text: "Finally the owner sends his son, expecting the tenants to respect him. In the parable, the son has a unique status that the servants do not share, reflecting Jesus' unique sonship and mission.", refs: ["Hebrews 1:1–2","John 3:16–17"] },
  "Matthew 21:38": { title: "The Heir Is Rejected", text: "The tenants recognize the heir and decide to kill him to seize his inheritance. The parable points to the leaders' rejection of Jesus and exposes the selfish motives behind it.", refs: ["John 11:47–53","Acts 2:23"] },
  "Matthew 21:39": { title: "The Son Is Cast Out and Killed", text: "The tenants cast the son out of the vineyard and kill him. The image foreshadows Jesus' rejection and death outside Jerusalem.", refs: ["Hebrews 13:12","John 19:16–18"] },
  "Matthew 21:40": { title: "The Owner Will Judge the Tenants", text: "Jesus asks what the owner will do when he comes. The question invites the hearers to pronounce judgment on the tenants before recognizing that the parable concerns them.", refs: ["Matthew 21:41","Luke 20:15–16"] },
  "Matthew 21:41": { title: "The Vineyard Given to Others", text: "The hearers answer that the owner will destroy the wicked tenants and lease the vineyard to others who will give him fruit. The answer anticipates judgment on unfaithful leadership and the raising up of a fruitful people.", refs: ["Matthew 8:11–12","Romans 11:17–21"] },
  "Matthew 21:42": { title: "The Rejected Stone Becomes the Head", text: "Jesus cites the Scripture about the stone rejected by builders becoming the chief cornerstone. The rejected Jesus becomes the foundation of God's saving work, as the Lord has done this.", refs: ["Psalm 118:22–23","Acts 4:11","1 Peter 2:6–7"] },
  "Matthew 21:43": { title: "The Kingdom Given to a Fruitful Nation", text: "Jesus says the kingdom will be taken from those who refuse its fruit and given to a nation producing its fruits. The warning is against unbelief and unfaithfulness, not a license for ethnic contempt; all who belong to Christ are called to bear fruit.", refs: ["Galatians 3:28–29","John 15:5–8"] },
  "Matthew 21:44": { title: "The Stone That Breaks and Crushes", text: "Jesus describes the stone as a source of ruin to those who fall upon it and judgment upon those it falls on. Rejecting God's chosen cornerstone carries serious consequences.", refs: ["Isaiah 8:14–15","Daniel 2:34–35"] },
  "Matthew 21:45": { title: "The Leaders Know He Speaks of Them", text: "The chief priests and Pharisees understand that Jesus' parables speak against them. Recognition does not necessarily produce repentance; they respond with hostility.", refs: ["Luke 20:19","John 7:30"] },
  "Matthew 21:46": { title: "They Fear the People", text: "They want to seize Jesus but fear the crowd, which regards Him as a prophet. Their concern is shaped by public reaction rather than submission to the truth.", refs: ["Matthew 14:5","John 11:47–48"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 22:1": { title: "The Parable of the Marriage Feast", text: "Jesus compares the kingdom of heaven to a king who prepares a marriage feast for his son. The feast pictures God's gracious invitation and the honor of the Son.", refs: ["Luke 14:16–17","Revelation 19:7–9"] },
  "Matthew 22:2": { title: "A King Makes a Marriage for His Son", text: "The king prepares a marriage feast for his son. The image centers on the son's honor and the king's desire to share the celebration with invited guests.", refs: ["Psalm 45:6–7","John 3:29"] },
  "Matthew 22:3": { title: "The Invited Guests Refuse", text: "The king sends servants to call those already invited, but they will not come. God's invitation can be refused even when it is graciously and clearly presented.", refs: ["Isaiah 65:2","Luke 14:18"] },
  "Matthew 22:4": { title: "The Invitation Is Repeated", text: "The king sends other servants and describes the prepared meal and feast. The repeated invitation demonstrates patience and the abundance prepared for the guests.", refs: ["Proverbs 9:1–5","Isaiah 25:6"] },
  "Matthew 22:5": { title: "Some Ignore the Invitation", text: "The invited guests make light of the call and go to their own fields or business. Everyday responsibilities become excuses when people refuse to give God His rightful place.", refs: ["Luke 14:18–20","Haggai 1:5–9"] },
  "Matthew 22:6": { title: "The Servants Are Mistreated", text: "Others seize the king's servants, treat them spitefully, and kill them. The parable echoes the rejection of God's messengers and the hostility shown toward His word.", refs: ["Matthew 21:35–36","2 Chronicles 36:15–16"] },
  "Matthew 22:7": { title: "The King Judges the Murderers", text: "The king responds with judgment against the murderers and their city. The parable warns that rejecting God's invitation with violence brings accountability.", refs: ["Luke 19:41–44","Matthew 23:37–38"] },
  "Matthew 22:8": { title: "The Guests Were Not Worthy", text: "The king says those invited were not worthy and orders the feast to continue with others. Their unworthiness is shown by their refusal, not by a lack of generosity from the king.", refs: ["Acts 13:46","Hebrews 2:3"] },
  "Matthew 22:9": { title: "Invite Whomever You Find", text: "The servants are sent to the crossroads to invite everyone they find. God's invitation extends beyond those who first assumed they would attend.", refs: ["Matthew 28:19","Acts 10:34–35"] },
  "Matthew 22:10": { title: "The Wedding Is Filled", text: "The servants gather both bad and good, and the wedding is filled with guests. The invitation reaches people from every kind of background, while the next verses show that responding to the invitation also matters.", refs: ["Luke 14:21–23","Acts 2:39"] },
  "Matthew 22:11": { title: "A Guest Without a Wedding Garment", text: "The king sees a man without a wedding garment. The scene shifts from the invitation being offered to the necessity of being properly prepared for the king's feast.", refs: ["Revelation 19:8","Isaiah 61:10"] },
  "Matthew 22:12": { title: "The Guest Has No Answer", text: "The king asks how the man entered without a wedding garment, and he is speechless. The encounter warns that outward presence among God's people is not a substitute for a fitting response to His grace.", refs: ["Romans 13:14","Colossians 3:12"] },
  "Matthew 22:13": { title: "Cast into Outer Darkness", text: "The king orders the unprepared guest removed into outer darkness, where there is weeping and gnashing of teeth. Jesus uses severe imagery to warn of final judgment.", refs: ["Matthew 8:12","Matthew 13:41–42"] },
  "Matthew 22:14": { title: "Many Are Called, Few Chosen", text: "Jesus concludes that many are called but few are chosen. The parable joins the breadth of God's invitation with the seriousness of truly responding to it.", refs: ["Matthew 7:13–14","2 Peter 1:10"] },
  "Matthew 22:15": { title: "A Plot to Trap Jesus", text: "The Pharisees take counsel about how to entangle Jesus in His words. Their aim is not to learn but to manufacture a reason to accuse Him.", refs: ["Mark 12:13","Psalm 2:1–2"] },
  "Matthew 22:16": { title: "Flattery Before a Question", text: "They send disciples with Herodians who flatter Jesus as truthful and impartial before asking their question. Their praise is manipulative, demonstrating that even accurate words can be spoken with deceitful motives.", refs: ["Luke 20:20","Proverbs 26:24–26"] },
  "Matthew 22:17": { title: "Is It Lawful to Pay Tribute?", text: "They ask whether it is lawful to pay tribute to Caesar. They hope to force Jesus into a politically dangerous answer either way.", refs: ["Romans 13:7","Mark 12:14"] },
  "Matthew 22:18": { title: "Jesus Knows Their Wickedness", text: "Jesus perceives their wickedness and calls them hypocrites. He is not deceived by their respectful approach and exposes the trap behind their question.", refs: ["John 2:24–25","Luke 6:8"] },
  "Matthew 22:19": { title: "Show the Tribute Money", text: "Jesus asks them to show Him the tribute coin. He uses the coin itself to lead them toward the answer rather than accepting their false dilemma.", refs: ["Mark 12:15","Luke 20:24"] },
  "Matthew 22:20": { title: "Whose Image and Superscription?", text: "Jesus asks whose image and inscription are on the coin. The visible mark establishes the point that follows.", refs: ["Genesis 1:26–27","Mark 12:16"] },
  "Matthew 22:21": { title: "Render to Caesar and to God", text: "They answer that the coin bears Caesar's image, and Jesus tells them to render to Caesar what belongs to Caesar and to God what belongs to God. Civic obligations do not cancel God's higher claim upon the whole person, who bears God's image.", refs: ["Romans 13:1–7","Genesis 1:27","Acts 5:29"] },
  "Matthew 22:22": { title: "They Marvel and Depart", text: "The questioners marvel at Jesus' answer and leave. His wisdom defeats their trap without surrendering either truth or proper civic responsibility.", refs: ["Luke 20:26","Proverbs 2:6"] },
  "Matthew 22:23": { title: "The Sadducees Deny the Resurrection", text: "The Sadducees, who deny the resurrection, present Jesus with a hypothetical case about marriage. Their question is designed to make resurrection seem absurd.", refs: ["Acts 23:8","Mark 12:18"] },
  "Matthew 22:24": { title: "Moses' Law About a Brother's Wife", text: "They quote the law requiring a brother to raise up seed for a deceased brother who died childless. The provision addressed family continuity in Israel, but they use it to challenge resurrection.", refs: ["Deuteronomy 25:5–6","Genesis 38:8"] },
  "Matthew 22:25": { title: "Seven Brothers", text: "The hypothetical story begins with seven brothers, the first of whom marries and dies without children. The elaborate example is intended to create a puzzle rather than honestly seek understanding.", refs: ["Mark 12:20","Luke 20:29"] },
  "Matthew 22:26": { title: "The Second and Third Brother", text: "The second and third brothers likewise marry the woman and die. The repeated pattern continues the Sadducees' proposed dilemma.", refs: ["Matthew 22:25","Luke 20:30–31"] },
  "Matthew 22:27": { title: "The Woman Also Dies", text: "After all seven brothers, the woman dies too. The questioners now present the situation as if it invalidates the resurrection.", refs: ["Matthew 22:25–26","Mark 12:22"] },
  "Matthew 22:28": { title: "Whose Wife in the Resurrection?", text: "They ask whose wife she will be in the resurrection, since all seven had married her. Their error is assuming the life to come simply repeats earthly arrangements.", refs: ["Luke 20:33","Matthew 22:30"] },
  "Matthew 22:29": { title: "Mistaken About Scripture and Power", text: "Jesus says they err because they do not know the Scriptures or the power of God. False conclusions often come from limiting God to human assumptions and failing to read His word rightly.", refs: ["2 Timothy 2:15","Ephesians 1:19–20"] },
  "Matthew 22:30": { title: "No Marriage in the Resurrection", text: "Jesus explains that in the resurrection people neither marry nor are given in marriage but are as the angels in heaven in this respect. He does not say redeemed humans become angels; He teaches that resurrection life is not governed by the same marriage arrangements.", refs: ["Luke 20:34–36","1 Corinthians 15:42–44"] },
  "Matthew 22:31": { title: "Have You Not Read About the Resurrection?", text: "Jesus points them back to what God spoke concerning the resurrection. He grounds the answer in Scripture rather than speculative argument.", refs: ["Exodus 3:6","Mark 12:26"] },
  "Matthew 22:32": { title: "God of the Living", text: "God calls Himself the God of Abraham, Isaac, and Jacob; Jesus concludes that God is not the God of the dead but of the living. God's covenant relationship and power overcome the Sadducees' assumption that death ends all hope.", refs: ["Exodus 3:6","Luke 20:37–38","Hebrews 11:16"] },
  "Matthew 22:33": { title: "The Multitude Is Astonished", text: "The multitude is astonished at Jesus' teaching. His answer has shown that the resurrection is consistent with Scripture and God's power.", refs: ["Matthew 7:28–29","Mark 12:27"] },
  "Matthew 22:34": { title: "The Pharisees Gather Together", text: "When the Pharisees hear that Jesus has silenced the Sadducees, they gather. Another group attempts to challenge Him, now with a question about the law's greatest commandment.", refs: ["Mark 12:28","Luke 10:25"] },
  "Matthew 22:35": { title: "A Lawyer Tests Jesus", text: "A lawyer asks a question to test Jesus. The question is about the law, but the motive is adversarial rather than humble inquiry.", refs: ["Luke 10:25","Matthew 19:3"] },
  "Matthew 22:36": { title: "Which Commandment Is Greatest?", text: "The lawyer asks which commandment is greatest in the law. Jesus' answer will show that the whole law's moral purpose is centered on love for God and neighbor.", refs: ["Deuteronomy 6:4–5","Leviticus 19:18"] },
  "Matthew 22:37": { title: "Love the Lord with All Your Being", text: "Jesus commands love for the Lord with all the heart, soul, and mind. True devotion involves the whole person and is grounded in the one Lord Israel confesses.", refs: ["Deuteronomy 6:4–5","Mark 12:29–30"] },
  "Matthew 22:38": { title: "The First and Great Commandment", text: "Jesus calls this the first and great commandment. Every part of life is to be ordered by wholehearted love for God.", refs: ["Deuteronomy 10:12","Joshua 22:5"] },
  "Matthew 22:39": { title: "Love Your Neighbor as Yourself", text: "The second commandment is to love one's neighbor as oneself. Love for God must be expressed in how people treat other people.", refs: ["Leviticus 19:18","Romans 13:9–10"] },
  "Matthew 22:40": { title: "The Law and the Prophets Hang on Love", text: "Jesus says all the law and prophets hang on these two commandments. Love does not abolish God's word; it expresses its central moral purpose and guides faithful obedience.", refs: ["Matthew 7:12","Galatians 5:14"] },
  "Matthew 22:41": { title: "Jesus Questions the Pharisees", text: "While the Pharisees are gathered, Jesus asks them a question about the Christ. He moves the discussion from their tests to the identity of the Messiah.", refs: ["Mark 12:35","Luke 20:41"] },
  "Matthew 22:42": { title: "Whose Son Is the Christ?", text: "Jesus asks whose son the Christ is, and they answer that He is David's son. This is correct but incomplete; the next verses ask how David can call the Christ his Lord.", refs: ["2 Samuel 7:12–16","Isaiah 11:1"] },
  "Matthew 22:43": { title: "David Speaks by the Spirit", text: "Jesus says David spoke in the Spirit when he called the Christ Lord. The Messiah is more than a merely human descendant; Scripture reveals His exalted authority.", refs: ["Psalm 110:1","Acts 2:34–36"] },
  "Matthew 22:44": { title: "The Lord Says to My Lord", text: "Jesus quotes the Psalm in which the Lord tells David's Lord to sit at His right hand until His enemies are made His footstool. The verse distinguishes the speakers in the prophetic scene while revealing the Messiah's exaltation; it should be read with the Bible's wider testimony to the one God and the identity of Jesus.", refs: ["Psalm 110:1","Hebrews 1:13","Acts 2:34–36"] },
  "Matthew 22:45": { title: "How Is the Christ David's Son?", text: "Jesus asks how David can call the Christ Lord if the Christ is only his son. The question presses the hearers to recognize the Messiah's greater status and divine authority.", refs: ["Romans 1:3–4","Revelation 22:16"] },
  "Matthew 22:46": { title: "No One Dares Ask Further", text: "No one can answer Jesus, and from that day no one dares ask Him further questions. Their silence shows that His scriptural reasoning has overturned their challenge.", refs: ["Mark 12:34","Luke 20:40"] },

  "Matthew 23:1": { title: "Jesus Speaks to the Multitude", text: "Jesus addresses the multitudes and His disciples concerning the scribes and Pharisees. He distinguishes public religious authority from the need to live faithfully.", refs: ["Mark 12:38","Luke 20:45"] },
  "Matthew 23:2": { title: "Moses' Seat", text: "The scribes and Pharisees sit in Moses' seat, a position associated with teaching the law. Jesus acknowledges the role while exposing the hypocrisy that follows.", refs: ["Deuteronomy 17:9–11","Romans 2:21"] },
  "Matthew 23:3": { title: "Do What They Teach, Not Their Hypocrisy", text: "Jesus tells the people to observe what they teach from Moses' seat but not imitate their works, because they do not practice what they preach. Truth should be obeyed, while hypocrisy must not be copied.", refs: ["Malachi 2:7–8","James 1:22"] },
  "Matthew 23:4": { title: "Heavy Burdens on Others", text: "The leaders bind heavy burdens and lay them on people's shoulders but will not help carry them. Spiritual leadership should assist people in obedience, not burden them for the sake of control.", refs: ["Luke 11:46","Acts 15:10"] },
  "Matthew 23:5": { title: "Works to Be Seen of Men", text: "They perform religious works to be noticed, enlarging their phylacteries and the borders of their garments. The problem is not the objects alone but using visible religion to seek human praise.", refs: ["Numbers 15:38–40","Matthew 6:1"] },
  "Matthew 23:6": { title: "Chief Seats and Uppermost Rooms", text: "They love the chief places at feasts and the best seats in synagogues. Their pursuit of honor reveals a heart centered on status rather than service.", refs: ["Luke 14:7–11","James 2:1–4"] },
  "Matthew 23:7": { title: "Greetings and Titles in the Market", text: "They enjoy respectful greetings and being called Rabbi. Jesus challenges the craving for religious prestige, not the ordinary courtesy of respectful address.", refs: ["Matthew 6:2","3 John 9"] },
  "Matthew 23:8": { title: "One Master, All Brethren", text: "Jesus tells His disciples not to seek status as masters, because they have one Master and are brethren. Spiritual leadership must not erase the shared dependence of believers on Christ.", refs: ["James 3:1","Ephesians 4:5"] },
  "Matthew 23:9": { title: "One Father in Heaven", text: "Jesus warns against claiming ultimate spiritual fatherhood over others, for one is the heavenly Father. The teaching confronts religious pride and ultimate allegiance; it need not be read as forbidding every ordinary familial use of the word father.", refs: ["Malachi 2:10","Ephesians 4:6"] },
  "Matthew 23:10": { title: "One Master, the Christ", text: "Jesus says not to be called masters, because the Christ is the one Master. The community must look to Him as its final authority rather than elevate human teachers into rivals to His rule.", refs: ["Matthew 28:18","Colossians 1:18"] },
  "Matthew 23:11": { title: "The Greatest Shall Be Servant", text: "The greatest among the disciples must be their servant. Kingdom leadership is measured by humble service, following Jesus' own example.", refs: ["Matthew 20:26–28","John 13:14–15"] },
  "Matthew 23:12": { title: "Humility and Exaltation", text: "Whoever exalts himself will be humbled, and whoever humbles himself will be exalted. God opposes pride and honors genuine humility.", refs: ["Proverbs 29:23","James 4:10","1 Peter 5:6"] },
  "Matthew 23:13": { title: "Woe to Those Who Shut the Kingdom", text: "Jesus rebukes the scribes and Pharisees for shutting the kingdom of heaven against people and refusing to enter themselves. Leaders are accountable when their teaching and conduct obstruct others from coming to God.", refs: ["Luke 11:52","Matthew 18:6"] },
  "Matthew 23:14": { title: "A Manuscript Note on This Verse", text: "Some later manuscript traditions include a woe about devouring widows' houses and making long prayers, while many modern editions omit this verse or place it in a note because it is absent from early witnesses. The same charge appears in Mark and Luke.", refs: ["Mark 12:40","Luke 20:47"] },
  "Matthew 23:15": { title: "Making One a Child of Gehenna", text: "Jesus condemns their zeal to make converts when their teaching produces people even more bound to error. Religious growth is not good if it multiplies hypocrisy and spiritual ruin.", refs: ["Acts 20:30","Galatians 4:17"] },
  "Matthew 23:16": { title: "Blind Guides and Oaths", text: "Jesus calls them blind guides because they make distinctions about which oaths are binding based on the temple and its gold. Their rules obscure the holiness of God and the truthfulness He requires.", refs: ["Matthew 5:33–37","James 5:12"] },
  "Matthew 23:17": { title: "The Temple Sanctifies the Gold", text: "Jesus asks which is greater, the gold or the temple that sanctifies it. Their reasoning reverses the proper order by valuing the gift more than the holy purpose of the temple.", refs: ["Exodus 30:29","Matthew 12:6"] },
  "Matthew 23:18": { title: "The Altar and the Gift", text: "They say an oath by the altar is nothing but an oath by the gift on it is binding. Jesus exposes a system that elevates offerings above the altar's sacred significance.", refs: ["Matthew 5:23–24","Matthew 23:19"] },
  "Matthew 23:19": { title: "The Altar Sanctifies the Gift", text: "Jesus again asks which is greater, the gift or the altar that sanctifies it. The altar's role shows that devotion to God cannot be reduced to the value of a material offering.", refs: ["Exodus 29:37","Matthew 23:17"] },
  "Matthew 23:20": { title: "An Oath by the Altar", text: "Jesus explains that swearing by the altar includes swearing by everything on it. He rejects the artificial distinctions by which people try to manipulate the seriousness of their words.", refs: ["Matthew 5:34–37","James 5:12"] },
  "Matthew 23:21": { title: "An Oath by the Temple", text: "Swearing by the temple also invokes the One who dwells there. Sacred language cannot be separated from the God whose presence gives it meaning.", refs: ["1 Kings 8:10–13","2 Chronicles 6:18"] },
  "Matthew 23:22": { title: "An Oath by Heaven", text: "Jesus says that one who swears by heaven swears by God's throne and the One who sits on it. No verbal formula allows a person to escape accountability before God.", refs: ["Isaiah 66:1","Matthew 5:34"] },
  "Matthew 23:23": { title: "Justice, Mercy, and Faith", text: "Jesus rebukes them for tithing small herbs while neglecting weightier matters of the law: judgment, mercy, and faith. He says the latter should be done without neglecting the former, correcting imbalance rather than praising carelessness.", refs: ["Micah 6:8","Luke 11:42"] },
  "Matthew 23:24": { title: "Straining at a Gnat", text: "Jesus uses the image of straining out a gnat while swallowing a camel to expose their distorted priorities. Small ceremonial details cannot compensate for major moral failures.", refs: ["Matthew 23:23","Luke 11:42"] },
  "Matthew 23:25": { title: "Clean Outside, Unclean Within", text: "They clean the outside of the cup and dish while inside they are full of extortion and excess. Outward religious appearance cannot hide greed and self-indulgence.", refs: ["Mark 7:20–23","Luke 11:39"] },
  "Matthew 23:26": { title: "Clean the Inside First", text: "Jesus tells the blind Pharisee to cleanse the inside of the cup so the outside may also be clean. Genuine reform begins with the heart and then shapes outward conduct.", refs: ["Psalm 51:10","Titus 2:11–12"] },
  "Matthew 23:27": { title: "Whited Sepulchres", text: "Jesus compares them to whitewashed tombs that look beautiful outside but contain uncleanness within. The metaphor exposes a religious image that conceals inward corruption.", refs: ["Luke 11:44","Acts 23:3"] },
  "Matthew 23:28": { title: "Righteous Appearance, Lawlessness Within", text: "They appear righteous to people but inwardly are full of hypocrisy and iniquity. God sees beyond public reputation to the true condition of the heart.", refs: ["1 Samuel 16:7","Luke 16:15"] },
  "Matthew 23:29": { title: "Building the Prophets' Tombs", text: "They build tombs for the prophets and decorate the monuments of the righteous. Honoring past messengers can become hollow when people refuse the truth those messengers proclaimed.", refs: ["Luke 11:47","Acts 7:52"] },
  "Matthew 23:30": { title: "Claiming Not to Share Their Fathers' Deeds", text: "They claim they would not have joined their ancestors in killing the prophets. Jesus will show that their present hostility reveals the same spirit despite their words.", refs: ["Matthew 23:31–32","Acts 7:51"] },
  "Matthew 23:31": { title: "Witnesses Against Themselves", text: "By claiming descent from those who killed the prophets, they testify to their connection with that history. Their conduct will reveal whether they have truly rejected their ancestors' sins.", refs: ["Luke 11:48","John 8:39–40"] },
  "Matthew 23:32": { title: "Fill Up the Measure", text: "Jesus tells them to fill up the measure of their fathers. The phrase warns that their persistent rejection will bring the pattern of rebellion to its full consequence.", refs: ["Genesis 15:16","1 Thessalonians 2:15–16"] },
  "Matthew 23:33": { title: "Serpents and Generation of Vipers", text: "Jesus asks how they can escape the judgment of Gehenna. His severe language confronts hardened hypocrisy and the danger of rejecting God's messengers.", refs: ["Matthew 3:7","Matthew 12:34"] },
  "Matthew 23:34": { title: "Prophets, Wise Men, and Scribes Sent", text: "Jesus says He will send prophets, wise men, and scribes, some of whom will be killed, crucified, scourged, and persecuted. God's mission continues, but the response to His messengers reveals the hearers' hearts.", refs: ["Matthew 10:16–23","Luke 11:49"] },
  "Matthew 23:35": { title: "Righteous Blood from Abel to Zacharias", text: "Jesus speaks of the righteous blood shed from Abel to Zacharias. The phrase gathers the story of Scripture's persecuted righteous and warns that accumulated violence will be judged.", refs: ["Genesis 4:8–10","2 Chronicles 24:20–22"] },
  "Matthew 23:36": { title: "These Things Come on This Generation", text: "Jesus declares that the consequences will come upon that generation. The warning concerns the culmination of persistent rejection and the judgment approaching Jerusalem.", refs: ["Matthew 24:34","Luke 19:43–44"] },
  "Matthew 23:37": { title: "Jesus Laments over Jerusalem", text: "Jesus laments that Jerusalem kills the prophets and stones those sent to her, and He describes His desire to gather her children as a hen gathers her chicks. His words reveal divine compassion and the people's unwillingness to receive it.", refs: ["Luke 13:34","Psalm 91:4"] },
  "Matthew 23:38": { title: "Your House Is Left Desolate", text: "Jesus says their house is left desolate. The temple and city face judgment because the people have rejected the visitation and messengers of God.", refs: ["Jeremiah 22:5","Luke 19:41–44"] },
  "Matthew 23:39": { title: "Until You Say, Blessed Is He", text: "Jesus says they will not see Him again until they say, Blessed is He that comes in the Lord's name. The saying points toward a future recognition of the Messiah and echoes the welcome sung at His entry.", refs: ["Psalm 118:26","Matthew 21:9","Romans 11:25–27"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 24:1": { title: "Jesus Leaves the Temple", text: "Jesus departs from the temple, and His disciples point out its buildings. The scene contrasts the impressive structure with the judgment Jesus is about to announce.", refs: ["Mark 13:1","Luke 21:5–6"] },
  "Matthew 24:2": { title: "Not One Stone Left", text: "Jesus declares that the temple buildings will be thrown down so that not one stone will be left upon another. This points to the coming destruction of Jerusalem and its temple.", refs: ["Luke 19:41–44","Luke 21:20–24"] },
  "Matthew 24:3": { title: "The Disciples Ask About the Future", text: "Privately on the Mount of Olives, the disciples ask about the timing of the temple's destruction and the sign of Jesus' coming and the end of the age. Jesus' answer includes warnings about Jerusalem, the coming of the Son of man, and the need for watchfulness.", refs: ["Mark 13:3–4","Luke 21:7"] },
  "Matthew 24:4": { title: "Take Heed That No One Deceives You", text: "Jesus begins with a warning against deception. Discernment is essential because religious claims and reports about the end can mislead believers.", refs: ["2 Thessalonians 2:3","1 John 4:1"] },
  "Matthew 24:5": { title: "Many Claim to Come in His Name", text: "Many will come using Jesus' name and claiming messianic authority, deceiving many. The warning calls believers to test claims rather than accept a title or slogan as proof.", refs: ["Jeremiah 14:14","Matthew 7:22–23"] },
  "Matthew 24:6": { title: "Wars and Rumors of Wars", text: "Jesus says wars and reports of wars will occur, but the disciples must not be troubled; these things must happen, yet the end is not immediately at hand. Calamity should not be used to set dates or produce panic.", refs: ["Mark 13:7","Luke 21:9"] },
  "Matthew 24:7": { title: "Nation Against Nation", text: "Jesus lists conflict, famines, and earthquakes as the beginning of sorrows. These events are real suffering, but they are not by themselves proof that the final moment has arrived.", refs: ["Isaiah 19:2","Luke 21:10–11"] },
  "Matthew 24:8": { title: "The Beginning of Sorrows", text: "Jesus compares these events to the beginning of birth pains. The image indicates distress preceding what is to come, without giving a calendar for the end.", refs: ["Romans 8:22","1 Thessalonians 5:3"] },
  "Matthew 24:9": { title: "Persecution of Disciples", text: "Jesus warns that His followers will be afflicted, killed, and hated by all nations for His name's sake. Faithfulness may bring suffering, and persecution must not be mistaken for proof that Christ has abandoned His people.", refs: ["John 15:18–20","2 Timothy 3:12"] },
  "Matthew 24:10": { title: "Many Will Be Offended", text: "Many will stumble, betray one another, and hate one another. Pressure reveals hearts and can fracture fellowship, so believers must guard against fear and resentment.", refs: ["Matthew 10:21–22","2 Thessalonians 2:3"] },
  "Matthew 24:11": { title: "False Prophets Arise", text: "Many false prophets will rise and deceive many. Jesus repeats the danger of deceptive religious leadership and calls for testing every teaching by truth.", refs: ["Deuteronomy 13:1–3","1 John 4:1"] },
  "Matthew 24:12": { title: "Love Grows Cold", text: "Because lawlessness increases, the love of many grows cold. Persistent evil can harden people, but disciples are called to preserve sincere love and obedience.", refs: ["2 Timothy 3:1–5","Revelation 2:4–5"] },
  "Matthew 24:13": { title: "Endure to the End", text: "The one who endures to the end will be saved. Jesus calls for persevering faith, not a momentary profession that collapses under pressure.", refs: ["Matthew 10:22","Hebrews 3:14"] },
  "Matthew 24:14": { title: "The Gospel Preached to All Nations", text: "The gospel of the kingdom will be preached in all the world as a witness to all nations, and then the end will come. The mission is to proclaim the good news faithfully rather than speculate about dates.", refs: ["Matthew 28:19–20","Acts 1:8"] },
  "Matthew 24:15": { title: "The Abomination of Desolation", text: "Jesus refers to Daniel's prophecy and warns readers to understand it. The phrase has been interpreted in relation to desecration and the crisis surrounding Jerusalem; the immediate instruction is to recognize danger and act without delay.", refs: ["Daniel 9:27","Daniel 11:31","Daniel 12:11"] },
  "Matthew 24:16": { title: "Flee to the Mountains", text: "Those in Judaea are told to flee to the mountains when the sign appears. Jesus gives practical urgency to His warning rather than inviting people to remain in danger for curiosity's sake.", refs: ["Luke 21:21","Mark 13:14"] },
  "Matthew 24:17": { title: "Do Not Return for Possessions", text: "The person on the housetop must not come down to retrieve belongings. The instruction emphasizes immediate flight when the crisis comes.", refs: ["Luke 17:31","Genesis 19:17"] },
  "Matthew 24:18": { title: "Do Not Return from the Field", text: "The worker in the field must not turn back for a garment. Ordinary possessions must not delay escape from the approaching danger.", refs: ["Luke 17:31–32","Genesis 19:26"] },
  "Matthew 24:19": { title: "Woe to the Pregnant and Nursing", text: "Jesus expresses compassion for pregnant women and those nursing infants because fleeing will be especially difficult for them. His warning recognizes the human cost of the coming distress.", refs: ["Luke 21:23","Matthew 2:18"] },
  "Matthew 24:20": { title: "Pray Your Flight Is Not in Winter or Sabbath", text: "Jesus tells them to pray that their flight not occur in winter or on the Sabbath. He acknowledges practical hardships and the constraints that could make escape more difficult.", refs: ["Mark 13:18","Luke 21:23"] },
  "Matthew 24:21": { title: "Great Tribulation", text: "Jesus describes great tribulation unlike anything before it. The words convey the extraordinary severity of the crisis and should be read with the surrounding instructions and prophetic context.", refs: ["Daniel 12:1","Mark 13:19"] },
  "Matthew 24:22": { title: "The Days Are Shortened", text: "Unless those days were shortened, no flesh would be saved, but for the elect's sake they will be shortened. God limits the time of distress and remembers those who belong to Him.", refs: ["Isaiah 65:8–9","Mark 13:20"] },
  "Matthew 24:23": { title: "Do Not Believe False Messiahs", text: "If anyone says the Christ is here or there, Jesus warns not to believe it. His followers must not be carried away by sensational claims.", refs: ["Matthew 24:5","Luke 17:23"] },
  "Matthew 24:24": { title: "Signs and Wonders Can Deceive", text: "False christs and false prophets will show great signs and wonders to deceive, if possible, even the elect. Miraculous appearance alone is not proof of truth; teaching must be tested against God's word.", refs: ["Deuteronomy 13:1–4","2 Thessalonians 2:9–10"] },
  "Matthew 24:25": { title: "Jesus Has Forewarned Them", text: "Jesus tells His disciples that He has warned them beforehand. Forewarning equips believers to remain steady instead of being surprised into credulity or panic.", refs: ["John 14:29","2 Peter 3:17"] },
  "Matthew 24:26": { title: "Do Not Go Out After Secret Claims", text: "If people say Christ is in the desert or in secret chambers, disciples must not believe them. Jesus rejects secret, localized claims that seek to draw people after false messiahs.", refs: ["Luke 17:23–24","Acts 1:11"] },
  "Matthew 24:27": { title: "The Coming Like Lightning", text: "The coming of the Son of man will be like lightning visible from east to west. Jesus contrasts His coming with secret rumors and hidden claims; it will not depend on a private announcement.", refs: ["Luke 17:24","Revelation 1:7"] },
  "Matthew 24:28": { title: "Where the Carcase Is", text: "Jesus uses the picture of vultures gathering around a carcass. The saying suggests that the signs of judgment will be recognizable where the judgment is taking place.", refs: ["Luke 17:37","Job 39:30"] },
  "Matthew 24:29": { title: "Cosmic Signs After the Tribulation", text: "Jesus describes the sun darkened, the moon without light, stars falling, and heavenly powers shaken. Prophetic language portrays a world-shaking intervention and judgment; interpreters differ on how literally and in what sequence these signs occur.", refs: ["Isaiah 13:10","Joel 2:10","Mark 13:24–25"] },
  "Matthew 24:30": { title: "The Sign of the Son of Man", text: "The sign of the Son of man appears, the tribes mourn, and they see Him coming with power and great glory. The coming is public and majestic, bringing both recognition and judgment.", refs: ["Daniel 7:13–14","Revelation 1:7"] },
  "Matthew 24:31": { title: "The Elect Gathered", text: "The Son of man sends His angels with a great trumpet to gather His elect from the four winds. The image promises that God's people will be gathered and not forgotten.", refs: ["Isaiah 27:13","1 Thessalonians 4:16–17"] },
  "Matthew 24:32": { title: "The Lesson of the Fig Tree", text: "As budding branches indicate that summer is near, Jesus says signs teach observers to recognize nearness. The lesson is discernment, not setting a date beyond what He has revealed.", refs: ["Luke 21:29–31","Matthew 16:2–3"] },
  "Matthew 24:33": { title: "When You See These Things", text: "When the described things occur, the disciples are to know that the event is near. Jesus calls for alertness and readiness in response to the signs He has given.", refs: ["Luke 21:31","James 5:8–9"] },
  "Matthew 24:34": { title: "This Generation Shall Not Pass", text: "Jesus declares that this generation will not pass until all these things are fulfilled. Interpreters understand 'this generation' in different ways, including the generation witnessing the events, the people of Israel, or the kind of people Jesus describes; the verse should be handled carefully in its full context.", refs: ["Matthew 23:36","Matthew 24:3"] },
  "Matthew 24:35": { title: "Jesus' Words Will Not Pass Away", text: "Heaven and earth will pass away, but Jesus' words will not pass away. His teaching is more enduring and reliable than the created order.", refs: ["Isaiah 40:8","Matthew 5:18"] },
  "Matthew 24:36": { title: "No One Knows the Day or Hour", text: "No one knows the day and hour, not even the angels, but the Father only. Jesus forbids date-setting and calls His disciples to humility about what has not been revealed.", refs: ["Acts 1:7","1 Thessalonians 5:1–2"] },
  "Matthew 24:37": { title: "As in the Days of Noah", text: "The coming of the Son of man will be like the days of Noah. People carried on ordinary life without taking the warning seriously until judgment arrived.", refs: ["Genesis 6:5–13","Luke 17:26–27"] },
  "Matthew 24:38": { title: "Eating, Drinking, and Marrying", text: "People ate, drank, and married until the day Noah entered the ark. Ordinary activities are not inherently sinful; the danger is living without regard for God's warning and coming judgment.", refs: ["Genesis 7:7–10","Luke 17:27"] },
  "Matthew 24:39": { title: "They Did Not Know Until the Flood", text: "They did not understand until the flood came and took them away. Sudden judgment overtakes those who ignore God's warning, so Jesus calls for readiness.", refs: ["Genesis 7:21–23","Luke 17:28–30"] },
  "Matthew 24:40": { title: "One Taken and One Left", text: "Two men are in the field; one is taken and the other left. The image emphasizes sudden separation and the need to be ready; the precise meaning of 'taken' is debated in light of the Noah comparison.", refs: ["Luke 17:34–36","Genesis 7:23"] },
  "Matthew 24:41": { title: "Two Women Grinding", text: "Two women are grinding at the mill; one is taken and one left. Even people engaged in the same ordinary task may face different outcomes when the Lord acts.", refs: ["Luke 17:35–36","Matthew 24:40"] },
  "Matthew 24:42": { title: "Watch, for You Do Not Know", text: "Jesus commands His disciples to watch because they do not know the hour of His Lord's coming. Readiness, not prediction, is the proper response to uncertainty.", refs: ["Matthew 25:13","1 Peter 4:7"] },
  "Matthew 24:43": { title: "The Householder and the Thief", text: "If a householder knew when a thief would come, he would watch and prevent the break-in. The illustration urges constant readiness because the time is unknown.", refs: ["Luke 12:39–40","1 Thessalonians 5:2"] },
  "Matthew 24:44": { title: "Be Ready", text: "The Son of man comes at an hour people do not expect, so they must be ready. Readiness means faithful living and obedience rather than anxious speculation.", refs: ["Luke 12:40","Titus 2:11–13"] },
  "Matthew 24:45": { title: "The Faithful and Wise Servant", text: "Jesus asks who the faithful and wise servant is, whom the master appoints to give the household food at the proper time. Leaders are accountable to care for those entrusted to them.", refs: ["Luke 12:42","1 Peter 5:2–4"] },
  "Matthew 24:46": { title: "Blessed Is the Faithful Servant", text: "The servant is blessed if the master finds him faithfully doing his work when he returns. The proper way to await Jesus is to remain diligent in one's responsibility.", refs: ["Luke 12:43","1 Corinthians 4:2"] },
  "Matthew 24:47": { title: "Set Over All the Master's Goods", text: "The master rewards the faithful servant by placing him over all his goods. Faithfulness in present service prepares for greater responsibility in the kingdom.", refs: ["Luke 19:17","Matthew 25:21"] },
  "Matthew 24:48": { title: "The Evil Servant Delays", text: "The evil servant says his master delays his coming. When expectation weakens, he reveals his character by mistreating others and living without restraint.", refs: ["2 Peter 3:3–4","Luke 12:45"] },
  "Matthew 24:49": { title: "Abusing Fellow Servants", text: "The servant begins to beat fellow servants and indulge with the drunken. Claiming that the master is delayed becomes an excuse for cruelty and self-indulgence.", refs: ["Ezekiel 34:2–4","Galatians 5:19–21"] },
  "Matthew 24:50": { title: "The Master Comes Unexpectedly", text: "The master arrives on a day and at an hour the servant does not expect. Delay does not mean absence, and accountability may come suddenly.", refs: ["Luke 12:46","1 Thessalonians 5:3"] },
  "Matthew 24:51": { title: "Judgment for the Hypocritical Servant", text: "The master cuts the servant asunder and assigns him a place with the hypocrites, where there is weeping and gnashing of teeth. Jesus closes with a grave warning that professed service without faithfulness faces judgment.", refs: ["Matthew 25:30","Luke 12:46"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 25:1": { title: "The Ten Virgins", text: "Jesus compares the kingdom of heaven to ten virgins who take their lamps and go to meet the bridegroom. The parable emphasizes readiness for the bridegroom's arrival.", refs: ["Matthew 24:42–44","Revelation 19:7–9"] },
  "Matthew 25:2": { title: "Five Wise and Five Foolish", text: "Five virgins are wise and five are foolish. The distinction is not outward appearance but the preparation that will matter when the bridegroom is delayed.", refs: ["Proverbs  wise","Matthew 7:24–27"] },
  "Matthew 25:3": { title: "The Foolish Take No Extra Oil", text: "The foolish virgins take lamps but no extra oil. They have the appearance of readiness without making adequate provision for the wait.", refs: ["Luke 12:35","Matthew 13:20–21"] },
  "Matthew 25:4": { title: "The Wise Bring Oil", text: "The wise virgins bring oil in their vessels along with their lamps. Their foresight shows readiness that can endure delay.", refs: ["Proverbs 6:6–8","Matthew 24:45–46"] },
  "Matthew 25:5": { title: "The Bridegroom Delays", text: "Because the bridegroom delays, all the virgins become drowsy and sleep. The key difference is not that some grow tired, but that some are prepared when the moment arrives.", refs: ["Matthew 24:48–50","2 Peter 3:9"] },
  "Matthew 25:6": { title: "A Cry at Midnight", text: "At midnight a cry announces that the bridegroom is coming and calls the virgins to go meet him. His arrival comes at an unexpected hour.", refs: ["Matthew 24:44","1 Thessalonians 5:2"] },
  "Matthew 25:7": { title: "They Trim Their Lamps", text: "All the virgins arise and trim their lamps. The arrival forces a moment of decision, revealing whether their preparation is sufficient.", refs: ["Luke 12:35","Matthew 25:8"] },
  "Matthew 25:8": { title: "The Foolish Ask for Oil", text: "The foolish virgins discover that their lamps are going out and ask the wise for oil. Some forms of readiness cannot simply be borrowed at the last moment from another person.", refs: ["Ezekiel 14:14","Romans 14:12"] },
  "Matthew 25:9": { title: "Go to Those Who Sell Oil", text: "The wise refuse to divide their oil lest all lack enough, and direct the others to buy for themselves. The parable is not teaching selfishness in ordinary charity; it shows that personal readiness before God cannot be transferred.", refs: ["Galatians 6:5","Romans 2:6"] },
  "Matthew 25:10": { title: "The Door Is Shut", text: "While the foolish go to buy oil, the bridegroom arrives, the ready enter the marriage, and the door is shut. The warning is that the opportunity to prepare will not remain open indefinitely.", refs: ["Luke 13:25","Matthew 7:21–23"] },
  "Matthew 25:11": { title: "Lord, Lord, Open to Us", text: "The other virgins arrive later and plead for the door to be opened. Their urgent appeal comes after the time of preparation has passed.", refs: ["Matthew 7:21","Luke 13:25"] },
  "Matthew 25:12": { title: "I Know You Not", text: "The bridegroom answers that he does not know them. Mere association with the wedding party does not replace true readiness and relationship.", refs: ["Matthew 7:23","John 10:14"] },
  "Matthew 25:13": { title: "Watch, for You Know Not the Day", text: "Jesus applies the parable by commanding His disciples to watch because they do not know the day or hour. The intended response is steady readiness, not date-setting.", refs: ["Matthew 24:42","1 Thessalonians 5:6"] },
  "Matthew 25:14": { title: "The Parable of the Talents", text: "Jesus compares the kingdom to a man who travels and entrusts his goods to servants. Each servant receives a responsibility to manage faithfully during the master's absence.", refs: ["Luke 19:12–13","1 Corinthians 4:2"] },
  "Matthew 25:15": { title: "According to Each Ability", text: "The master gives different amounts to each servant according to ability and then departs. God does not give every person identical responsibilities, but each is accountable for what is entrusted.", refs: ["Romans 12:6","1 Peter 4:10"] },
  "Matthew 25:16": { title: "The First Servant Trades", text: "The servant given five talents immediately puts them to work and gains five more. Faithfulness is active and productive, using what has been entrusted rather than leaving it unused.", refs: ["Proverbs 10:4","Colossians 3:23"] },
  "Matthew 25:17": { title: "The Second Servant Gains Two", text: "The servant with two talents also gains two more. His faithfulness is equal in principle to the first servant's even though the amount differs.", refs: ["Luke 16:10","Romans 12:6"] },
  "Matthew 25:18": { title: "The Third Servant Hides the Talent", text: "The servant with one talent digs in the earth and hides his master's money. Fear and passivity cause him to neglect the responsibility entrusted to him.", refs: ["Proverbs 26:13–16","James 4:17"] },
  "Matthew 25:19": { title: "The Master Returns to Settle Accounts", text: "After a long time the master returns and settles accounts with the servants. The delay does not cancel accountability; every servant must answer for his stewardship.", refs: ["Romans 14:12","2 Corinthians 5:10"] },
  "Matthew 25:20": { title: "Five Talents Gained", text: "The first servant presents the original five talents and five more, acknowledging that the master entrusted the resources to him. His report demonstrates productive faithfulness.", refs: ["Matthew 25:16","Luke 19:16"] },
  "Matthew 25:21": { title: "Well Done, Good and Faithful Servant", text: "The master commends the servant as good and faithful, promotes him over more, and invites him into his master's joy. Faithfulness in limited responsibility is honored by God.", refs: ["Luke 16:10","1 Corinthians 4:5"] },
  "Matthew 25:22": { title: "The Two-Talent Servant Reports", text: "The servant given two talents reports that he has gained two more. He presents his work honestly and receives the same commendation as the servant with five.", refs: ["Matthew 25:17","Luke 19:18"] },
  "Matthew 25:23": { title: "The Same Commendation", text: "The master gives the two-talent servant the same words of praise and invites him into the master's joy. God's approval is not measured by comparing the size of people's assignments.", refs: ["Matthew 20:12–16","Galatians 6:4"] },
  "Matthew 25:24": { title: "The Servant's Accusation", text: "The one-talent servant describes the master as a hard man who reaps where he has not sown. His words reveal a distorted view of the master and prepare to expose his excuse.", refs: ["Luke 19:20–21","Proverbs 26:13"] },
  "Matthew 25:25": { title: "Fear Leads to Hiding", text: "The servant says he was afraid and hid the talent in the earth. Fear becomes his excuse for doing nothing with what he was given.", refs: ["2 Timothy 1:7","James 1:22"] },
  "Matthew 25:26": { title: "The Master Calls Him Wicked and Slothful", text: "The master calls the servant wicked and lazy. Even on the servant's own stated view, he should have acted responsibly rather than burying the money.", refs: ["Luke 19:22–23","Proverbs 18:9"] },
  "Matthew 25:27": { title: "At Least Deposit the Money", text: "The master says the servant could have placed the money with bankers so it would earn interest. The rebuke shows that the servant's inaction was not unavoidable.", refs: ["Luke 19:23","Ecclesiastes 11:1–2"] },
  "Matthew 25:28": { title: "The Talent Is Taken Away", text: "The master orders the talent taken from the unfaithful servant and given to the one with ten. Entrusted opportunity is not meant to be wasted.", refs: ["Luke 19:24","Matthew 13:12"] },
  "Matthew 25:29": { title: "More Given to the Faithful", text: "Jesus states that the one who has will receive more, while from the one who has not, even what he has will be taken away. Faithful use of God's gifts leads to greater responsibility, while neglect brings loss.", refs: ["Matthew 13:12","Luke 8:18"] },
  "Matthew 25:30": { title: "Outer Darkness", text: "The unprofitable servant is cast into outer darkness, where there is weeping and gnashing of teeth. The severe conclusion warns that empty profession without faithful obedience is dangerous.", refs: ["Matthew 8:12","Matthew 24:51"] },
  "Matthew 25:31": { title: "The Son of Man Comes in Glory", text: "The Son of man comes in His glory with all the holy angels and sits on His glorious throne. Jesus presents Himself as the appointed judge of the nations.", refs: ["Daniel 7:13–14","John 5:22–27"] },
  "Matthew 25:32": { title: "All Nations Gathered", text: "All nations are gathered before Him, and He separates them as a shepherd separates sheep from goats. No nation or person stands outside His authority to judge.", refs: ["Joel 3:2","Ezekiel 34:17"] },
  "Matthew 25:33": { title: "Sheep on the Right, Goats on the Left", text: "The sheep are placed at the right hand and the goats at the left. The separation symbolizes the difference between those who belong to the King and those who do not.", refs: ["Psalm 110:1","Matthew 13:49"] },
  "Matthew 25:34": { title: "Come, Blessed of My Father", text: "The King invites those at His right hand to inherit the kingdom prepared for them from the foundation of the world. Their inheritance is God's gracious purpose, not a reward they can boastfully claim apart from Him.", refs: ["Ephesians 1:4","1 Peter 1:4"] },
  "Matthew 25:35": { title: "Food, Drink, and Welcome", text: "The King recounts that they fed Him when hungry, gave Him drink when thirsty, and welcomed Him as a stranger. Practical mercy toward people in need is treated as service rendered to the King.", refs: ["Isaiah 58:7","Hebrews 13:2"] },
  "Matthew 25:36": { title: "Clothing, Care, and Visiting", text: "The King continues by naming care for the naked, sick, and imprisoned. Genuine faith expresses itself through compassionate action toward people who are vulnerable.", refs: ["James 2:15–17","Hebrews 13:3"] },
  "Matthew 25:37": { title: "The Righteous Ask When", text: "The righteous ask when they saw the King hungry, thirsty, or in need. They have not been performing acts of mercy merely to earn public praise or to calculate a reward.", refs: ["Matthew 6:1–4","Luke 14:13–14"] },
  "Matthew 25:38": { title: "When Did We See You a Stranger?", text: "They ask when they saw Him as a stranger or naked and cared for Him. Their question shows that their service was not based on recognizing the recipient as the King in disguise.", refs: ["Hebrews 13:2","Proverbs 19:17"] },
  "Matthew 25:39": { title: "When Did We Visit You?", text: "They ask when they saw the King sick or in prison and came to Him. The repeated question emphasizes that small acts of care have kingdom significance.", refs: ["Matthew 10:42","Hebrews 13:3"] },
  "Matthew 25:40": { title: "Done to the Least of These", text: "The King says that what they did to one of the least of His brethren, they did to Him. Jesus identifies Himself with those who belong to Him and are vulnerable; the verse calls for serious, practical care.", refs: ["Proverbs 19:17","Matthew 10:40–42"] },
  "Matthew 25:41": { title: "Depart into Everlasting Fire", text: "The King tells those on the left to depart into everlasting fire prepared for the devil and his angels. The warning portrays final judgment as real and grave.", refs: ["Revelation 20:10–15","Jude 7"] },
  "Matthew 25:42": { title: "They Did Not Feed the Hungry", text: "The condemned are judged for failing to feed the hungry and give drink to the thirsty. Their neglect reveals a lack of merciful love, not merely an isolated omission.", refs: ["James 2:15–16","1 John 3:17"] },
  "Matthew 25:43": { title: "They Did Not Welcome or Clothe", text: "The King names their failure to welcome the stranger, clothe the naked, and visit the sick and imprisoned. Indifference toward suffering is incompatible with the mercy God commands.", refs: ["Isaiah 58:6–7","Hebrews 13:2–3"] },
  "Matthew 25:44": { title: "When Did We Fail to Serve You?", text: "The condemned ask when they saw the King in need and did not minister to Him. Their question cannot excuse their neglect; the King has already identified the people whose needs they ignored.", refs: ["Matthew 25:40","Luke 10:29–37"] },
  "Matthew 25:45": { title: "Not Done to the Least", text: "The King answers that what they failed to do for one of the least, they failed to do for Him. The passage warns against separating devotion to Jesus from responsibility toward those He identifies with.", refs: ["1 John 4:20","James 1:27"] },
  "Matthew 25:46": { title: "Everlasting Punishment and Eternal Life", text: "Jesus concludes that the wicked go into everlasting punishment, while the righteous enter eternal life. The verse presents both outcomes as serious and enduring, urging hearers to live in faithful obedience to God.", refs: ["Daniel 12:2","John 5:28–29","Romans 2:6–8"] }
});
